/// A validated absolute tolerance for approximate extension folds.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct ApproxTolerance(f64);

impl ApproxTolerance {
    pub fn new(tolerance: f64) -> Result<Self> {
        if !tolerance.is_finite() || tolerance < 0.0 {
            return Err(Error::invalid(format!(
                "measure extensions: invalid approximate tolerance {tolerance}"
            )));
        }
        Ok(Self(tolerance))
    }

    pub fn get(self) -> f64 {
        self.0
    }
}

/// What a measurement accumulator promises about its merge.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum FoldLaw {
    /// The partials can be merged in any order with byte-identical results.
    ExactAssociative,
    /// The result is intentionally approximate, with a validated absolute tolerance.
    Approximate { tolerance: ApproxTolerance },
    /// The result depends on order and must not be merged as an unordered block
    /// reduction.
    OrderedOnly,
}

impl FoldLaw {
    pub fn approximate(tolerance: f64) -> Result<Self> {
        Ok(Self::Approximate {
            tolerance: ApproxTolerance::new(tolerance)?,
        })
    }
}

/// Scalar value exposed through a derived feature selector.
///
/// Count-like features are integer accumulators internally but are projected as
/// `f64` for uniform selector APIs. This wrapper names that precision boundary
/// and refuses integer values that `f64` cannot represent exactly.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct FeatureScalar(f64);

impl FeatureScalar {
    pub const MAX_EXACT_INTEGER: u64 = 1u64 << f64::MANTISSA_DIGITS;

    pub fn exact_u64(value: u64) -> Option<Self> {
        (value <= Self::MAX_EXACT_INTEGER).then_some(Self(value as f64))
    }

    pub fn exact_i64(value: i64) -> Option<Self> {
        (value.unsigned_abs() <= Self::MAX_EXACT_INTEGER).then_some(Self(value as f64))
    }

    pub fn exact_usize(value: usize) -> Option<Self> {
        u64::try_from(value).ok().and_then(Self::exact_u64)
    }

    pub fn get(self) -> f64 {
        self.0
    }
}

fn exact_u64_feature(value: u64) -> Option<f64> {
    FeatureScalar::exact_u64(value).map(FeatureScalar::get)
}

fn exact_i64_feature(value: i64) -> Option<f64> {
    FeatureScalar::exact_i64(value).map(FeatureScalar::get)
}

fn exact_usize_feature(value: usize) -> Option<f64> {
    FeatureScalar::exact_usize(value).map(FeatureScalar::get)
}

fn exact_u64_sum_feature(values: impl IntoIterator<Item = u64>) -> Option<f64> {
    let mut total = 0u64;
    for value in values {
        total = total.checked_add(value)?;
    }
    exact_u64_feature(total)
}

fn compatibility_u64_feature(value: u64) -> f64 {
    exact_u64_feature(value).unwrap_or(value as f64)
}

fn compatibility_i64_feature(value: i64) -> f64 {
    exact_i64_feature(value).unwrap_or(value as f64)
}

fn compatibility_usize_feature(value: usize) -> f64 {
    exact_usize_feature(value).unwrap_or(value as f64)
}

fn compatibility_u64_sum_feature(values: impl IntoIterator<Item = u64>) -> f64 {
    values.into_iter().map(|value| value as f64).sum()
}

