mod built_in_accumulator {
    pub trait Sealed {}
}

trait BuiltInExactAccumulator: built_in_accumulator::Sealed {}

impl<T> built_in_accumulator::Sealed for &T where T: BuiltInExactAccumulator + ?Sized {}

impl<T> BuiltInExactAccumulator for &T where T: BuiltInExactAccumulator + ?Sized {}

macro_rules! built_in_exact_accumulators {
    ($($ty:ty),+ $(,)?) => {
        $(
            impl built_in_accumulator::Sealed for $ty {}
            impl BuiltInExactAccumulator for $ty {}
        )+
    };
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct ExactReduction<T: BuiltInExactAccumulator> {
    value: T,
}

impl<T> ExactReduction<T>
where
    T: BuiltInExactAccumulator,
{
    fn new(value: T) -> Self {
        Self { value }
    }

    fn into_inner(self) -> T {
        self.value
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
struct ApproxReduction<T> {
    value: T,
    tolerance: ApproxTolerance,
}

impl<T> ApproxReduction<T> {
    fn new(value: T, tolerance: ApproxTolerance) -> Self {
        Self { value, tolerance }
    }

    fn into_inner(self) -> T {
        self.value
    }

    fn tolerance(self) -> ApproxTolerance {
        self.tolerance
    }
}

/// Fold law after rejecting order-sensitive extension reductions.
#[derive(Debug, Clone, Copy, PartialEq)]
enum ValidatedExtensionFoldLaw {
    ExactAssociative,
    Approximate { tolerance: ApproxTolerance },
}

impl ValidatedExtensionFoldLaw {
    fn combine(self, other: Self) -> Self {
        match (self, other) {
            (Self::Approximate { tolerance: left }, Self::Approximate { tolerance: right }) => {
                Self::Approximate {
                    tolerance: if left.get() >= right.get() {
                        left
                    } else {
                        right
                    },
                }
            }
            (Self::Approximate { tolerance }, Self::ExactAssociative)
            | (Self::ExactAssociative, Self::Approximate { tolerance }) => {
                Self::Approximate { tolerance }
            }
            (Self::ExactAssociative, Self::ExactAssociative) => Self::ExactAssociative,
        }
    }

    fn as_fold_law(self) -> FoldLaw {
        match self {
            Self::ExactAssociative => FoldLaw::ExactAssociative,
            Self::Approximate { tolerance } => FoldLaw::Approximate { tolerance },
        }
    }

    fn is_exact(self) -> bool {
        matches!(self, Self::ExactAssociative)
    }

    fn tolerance(self) -> Option<ApproxTolerance> {
        match self {
            Self::ExactAssociative => None,
            Self::Approximate { tolerance } => Some(tolerance),
        }
    }
}

/// A planner cost declared by a measurement extension after validation.
#[derive(Debug, Clone, Copy, PartialEq)]
struct ExtensionCost(f64);

impl ExtensionCost {
    fn new(class: &str, key: &str, cost: f64) -> Result<Self> {
        if !cost.is_finite() || cost < 0.0 {
            return Err(Error::invalid(format!(
                "measure extensions: {class} measure {key:?} has invalid planner cost {cost}"
            )));
        }
        Ok(Self(cost))
    }

    fn get(self) -> f64 {
        self.0
    }
}

