#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct MeasurementGrid {
    extent: [NonZeroUsize; 3],
}

impl MeasurementGrid {
    fn new(extent: [usize; 3]) -> Result<Self> {
        Ok(Self {
            extent: nonzero_measurement_extent(extent)?,
        })
    }

    fn extent(self) -> [usize; 3] {
        self.extent.map(NonZeroUsize::get)
    }

    fn ensure_matches(
        self,
        role: &'static str,
        image: ImageId,
        expected: Self,
        expected_role: &'static str,
    ) -> Result<()> {
        if self != expected {
            return Err(Error::invalid(format!(
                "measurements: {role} {} has extent {:?}, but the {expected_role} has extent {:?}",
                image.index(),
                self.extent(),
                expected.extent()
            )));
        }
        Ok(())
    }
}

fn nonzero_measurement_extent(extent: [usize; 3]) -> Result<[NonZeroUsize; 3]> {
    let [z, y, x] = extent;
    Ok([
        NonZeroUsize::new(z).ok_or_else(|| {
            Error::invalid("measurement source facts: extent has zero length on axis 0")
        })?,
        NonZeroUsize::new(y).ok_or_else(|| {
            Error::invalid("measurement source facts: extent has zero length on axis 1")
        })?,
        NonZeroUsize::new(x).ok_or_else(|| {
            Error::invalid("measurement source facts: extent has zero length on axis 2")
        })?,
    ])
}

/// Physical coordinate facts known about a measurement source before planning starts.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct MeasurementFrameId(NonZeroU64);

impl MeasurementFrameId {
    pub fn new(id: u64) -> Result<Self> {
        NonZeroU64::new(id)
            .map(Self)
            .ok_or_else(|| Error::invalid("measurement source facts: coordinate frame id is zero"))
    }

    pub fn get(self) -> u64 {
        self.0.get()
    }
}

/// Physical coordinate facts known about a measurement source before planning starts.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct MeasurementFrame {
    spacing: PhysicalSpacing,
    id: Option<MeasurementFrameId>,
}

impl MeasurementFrame {
    pub fn from_spacing(spacing: PhysicalSpacing) -> Self {
        Self { spacing, id: None }
    }

    pub fn from_spacing_and_id(spacing: PhysicalSpacing, id: MeasurementFrameId) -> Self {
        Self {
            spacing,
            id: Some(id),
        }
    }

    pub fn with_id(mut self, id: MeasurementFrameId) -> Self {
        self.id = Some(id);
        self
    }

    pub fn spacing(self) -> PhysicalSpacing {
        self.spacing
    }

    pub fn id(self) -> Option<MeasurementFrameId> {
        self.id
    }

    fn ensure_matches(
        self,
        role: &'static str,
        image: ImageId,
        expected: Self,
        expected_role: &'static str,
    ) -> Result<()> {
        if self.spacing() != expected.spacing() {
            return Err(Error::invalid(format!(
                "measurements: {role} {} has physical spacing {:?}, but the {expected_role} has physical spacing {:?}",
                image.index(),
                self.spacing().axes(),
                expected.spacing().axes()
            )));
        }
        if let (Some(id), Some(expected_id)) = (self.id(), expected.id()) {
            if id != expected_id {
                return Err(Error::invalid(format!(
                    "measurements: {role} {} is in coordinate frame {}, but the {expected_role} is in coordinate frame {}",
                    image.index(),
                    id.get(),
                    expected_id.get()
                )));
            }
        }
        Ok(())
    }
}

/// Concrete facts known about a measurement source before planning starts.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct MeasurementSourceFact {
    dtype: Dtype,
    grid: MeasurementGrid,
    frame: Option<MeasurementFrame>,
}

impl MeasurementSourceFact {
    pub fn new(dtype: Dtype, extent: [usize; 3]) -> Result<Self> {
        Ok(Self {
            dtype,
            grid: MeasurementGrid::new(extent)?,
            frame: None,
        })
    }

    fn from_voxels(voxels: &Voxels) -> Result<Self> {
        Self::new(voxels.dtype(), voxels.shape())
    }

    pub fn with_physical_frame(mut self, frame: MeasurementFrame) -> Self {
        self.frame = Some(frame);
        self
    }

    pub fn with_spacing(self, spacing: PhysicalSpacing) -> Self {
        self.with_physical_frame(MeasurementFrame::from_spacing(spacing))
    }

    pub fn dtype(self) -> Dtype {
        self.dtype
    }

    pub fn extent(self) -> [usize; 3] {
        self.grid.extent()
    }

    fn grid(self) -> MeasurementGrid {
        self.grid
    }

    pub fn physical_frame(self) -> Option<MeasurementFrame> {
        self.frame
    }

    pub fn spacing(self) -> Option<PhysicalSpacing> {
        self.physical_frame().map(MeasurementFrame::spacing)
    }

    fn ensure_frame_compatible_with(
        self,
        role: &'static str,
        image: ImageId,
        expected: Self,
        expected_role: &'static str,
    ) -> Result<()> {
        match (self.physical_frame(), expected.physical_frame()) {
            (Some(frame), Some(expected)) => {
                frame.ensure_matches(role, image, expected, expected_role)
            }
            _ => Ok(()),
        }
    }
}

/// Build-time source registry for checked measurement plans.
#[derive(Debug, Clone, PartialEq)]
pub struct MeasurementSourceFacts {
    sources: BTreeMap<usize, MeasurementSourceFact>,
}

impl MeasurementSourceFacts {
    pub fn new() -> Self {
        Self {
            sources: BTreeMap::new(),
        }
    }

    pub fn from_decomposition(base: &Decomposition) -> Result<Self> {
        let mut facts = Self::new();
        for image in 0..=base.phases.len() {
            facts.try_insert_source(
                image,
                MeasurementSourceFact::new(base.dtype_at(image), base.volume_at(image))?,
            )?;
        }
        for image in base.supplied_input_images() {
            facts.try_insert_source(
                image,
                MeasurementSourceFact::new(base.dtype_at(image), base.volume_at(image))?,
            )?;
        }
        Ok(facts)
    }

    pub fn from_inputs(input: &Voxels, supplied: &[Voxels]) -> Result<Self> {
        Self::new()
            .try_with_source(0usize, MeasurementSourceFact::from_voxels(input)?)
            .and_then(|facts| facts.with_supplied_inputs(supplied))
    }

    #[cfg(feature = "zarr")]
    pub fn from_attached_images(images: &[crate::zarr_env::AttachedImage]) -> Result<Self> {
        let Some((input, supplied)) = images.split_first() else {
            return Err(Error::invalid(
                "measurement source facts: at least image 0 must be attached",
            ));
        };
        let (dtype, extent) = input.metadata()?;
        let mut facts =
            Self::new().try_with_source(0usize, MeasurementSourceFact::new(dtype, extent)?)?;
        for (which, image) in supplied.iter().enumerate() {
            let (dtype, extent) = image.metadata()?;
            facts.try_insert_source(
                ImageId::supplied(which),
                MeasurementSourceFact::new(dtype, extent)?,
            )?;
        }
        Ok(facts)
    }

    pub fn with_source(mut self, image: impl Into<ImageId>, fact: MeasurementSourceFact) -> Self {
        self.insert_source(image, fact);
        self
    }

    pub fn try_with_source(
        mut self,
        image: impl Into<ImageId>,
        fact: MeasurementSourceFact,
    ) -> Result<Self> {
        self.try_insert_source(image, fact)?;
        Ok(self)
    }

    pub fn with_physical_frame(mut self, frame: MeasurementFrame) -> Self {
        for fact in self.sources.values_mut() {
            *fact = fact.with_physical_frame(frame);
        }
        self
    }

    pub fn with_spacing(self, spacing: PhysicalSpacing) -> Self {
        self.with_physical_frame(MeasurementFrame::from_spacing(spacing))
    }

    pub fn with_source_physical_frame(
        mut self,
        image: impl Into<ImageId>,
        frame: MeasurementFrame,
    ) -> Result<Self> {
        let image = image.into();
        let Some(fact) = self.sources.get_mut(&image.index()) else {
            return Err(Error::invalid(format!(
                "measurement source facts: source {} has no registered dtype and extent",
                image.index()
            )));
        };
        *fact = fact.with_physical_frame(frame);
        Ok(self)
    }

    pub fn with_source_spacing(
        self,
        image: impl Into<ImageId>,
        spacing: PhysicalSpacing,
    ) -> Result<Self> {
        self.with_source_physical_frame(image, MeasurementFrame::from_spacing(spacing))
    }

    pub fn with_supplied_inputs(mut self, supplied: &[Voxels]) -> Result<Self> {
        for (which, voxels) in supplied.iter().enumerate() {
            self.try_insert_source(
                ImageId::supplied(which),
                MeasurementSourceFact::from_voxels(voxels)?,
            )?;
        }
        Ok(self)
    }

    pub fn insert_source(&mut self, image: impl Into<ImageId>, fact: MeasurementSourceFact) {
        self.sources.insert(image.into().index(), fact);
    }

    pub fn try_insert_source(
        &mut self,
        image: impl Into<ImageId>,
        fact: MeasurementSourceFact,
    ) -> Result<()> {
        let image = image.into();
        if self.sources.contains_key(&image.index()) {
            return Err(Error::invalid(format!(
                "measurement source facts: source {} is already registered",
                image.index()
            )));
        }
        self.sources.insert(image.index(), fact);
        Ok(())
    }

    pub fn get(&self, image: impl Into<ImageId>) -> Option<MeasurementSourceFact> {
        self.sources.get(&image.into().index()).copied()
    }
}

impl TryFrom<&Voxels> for MeasurementSourceFact {
    type Error = Error;

    fn try_from(voxels: &Voxels) -> Result<Self> {
        Self::from_voxels(voxels)
    }
}

impl Default for MeasurementSourceFacts {
    fn default() -> Self {
        Self::new()
    }
}

