/// Projected convex row-layout request with a bounded hull-vertex section.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ProjectedConvexSet {
    max_hull_vertices: NonZeroUsize,
    row_width: usize,
}

impl ProjectedConvexSet {
    pub fn new(max_hull_vertices: usize) -> Result<Self> {
        let max_hull_vertices = NonZeroUsize::new(max_hull_vertices).ok_or_else(|| {
            Error::invalid("measure projected convex: max_hull_vertices must be greater than zero")
        })?;
        let row_width =
            Self::row_width_for_max_hull_vertices(max_hull_vertices.get()).ok_or_else(|| {
                Error::invalid(format!(
                    "measure projected convex: max_hull_vertices {} makes the row width overflow",
                    max_hull_vertices.get()
                ))
            })?;
        Ok(Self {
            max_hull_vertices,
            row_width,
        })
    }

    pub fn max_hull_vertices(self) -> usize {
        self.max_hull_vertices.get()
    }

    fn row_width(self) -> usize {
        self.row_width
    }

    fn largest_row_width_bound() -> Result<Self> {
        Self::new((usize::MAX - PROJECTED_CONVEX_FIXED_ROW_WIDTH) / 2)
    }

    fn row_width_for_max_hull_vertices(max_hull_vertices: usize) -> Option<usize> {
        max_hull_vertices
            .checked_mul(2)
            .and_then(|words| PROJECTED_CONVEX_FIXED_ROW_WIDTH.checked_add(words))
    }
}

