#[derive(Debug, Clone, Copy, PartialEq)]
pub struct IntensitySet {
    features: IntensityFeatureSet,
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum IntensityFeatureSet {
    None,
    Basic,
    Distribution(DistributionSet),
    BasicAndDistribution(DistributionSet),
}

impl IntensityFeatureSet {
    fn with_distribution(self, set: DistributionSet) -> Self {
        match self {
            Self::None => Self::Distribution(set),
            Self::Distribution(_) => Self::Distribution(set),
            Self::Basic | Self::BasicAndDistribution(_) => Self::BasicAndDistribution(set),
        }
    }

    fn wants_any(self) -> bool {
        !matches!(self, Self::None)
    }

    fn wants_basic(self) -> bool {
        matches!(self, Self::Basic | Self::BasicAndDistribution(_))
    }

    fn distribution_set(self) -> Option<DistributionSet> {
        match self {
            Self::Distribution(set) | Self::BasicAndDistribution(set) => Some(set),
            Self::None | Self::Basic => None,
        }
    }
}

impl IntensitySet {
    pub fn none() -> Self {
        Self {
            features: IntensityFeatureSet::None,
        }
    }

    pub fn basic() -> Self {
        Self::standard()
    }

    pub fn standard() -> Self {
        Self {
            features: IntensityFeatureSet::Basic,
        }
    }

    pub fn distribution(bins: usize, min: f64, max: f64) -> Result<Self> {
        Self::approx_distribution(bins, min, max)
    }

    pub fn approx_distribution(bins: usize, min: f64, max: f64) -> Result<Self> {
        Self::approx_distribution_set(ApproxDistributionSet::new(bins, min, max)?)
    }

    pub fn approx_distribution_set(set: ApproxDistributionSet) -> Result<Self> {
        Ok(Self {
            features: IntensityFeatureSet::Distribution(set),
        })
    }

    pub fn with_distribution(self, bins: usize, min: f64, max: f64) -> Result<Self> {
        self.with_approx_distribution(bins, min, max)
    }

    pub fn with_approx_distribution(self, bins: usize, min: f64, max: f64) -> Result<Self> {
        self.with_approx_distribution_set(ApproxDistributionSet::new(bins, min, max)?)
    }

    pub fn with_approx_distribution_set(mut self, set: ApproxDistributionSet) -> Result<Self> {
        self.features = self.features.with_distribution(set);
        Ok(self)
    }

    pub fn wants_any(self) -> bool {
        self.features.wants_any()
    }

    pub fn wants_basic(self) -> bool {
        self.features.wants_basic()
    }

    pub fn distribution_set(self) -> Option<DistributionSet> {
        self.features.distribution_set()
    }
}

impl Default for IntensitySet {
    fn default() -> Self {
        Self::none()
    }
}

