impl<'a, M: RegionMeasure> ValidatedResidentRegionRequest<'a, M> {
    fn new(
        labels: ArrayView3<'_, f64>,
        sources: &[ArrayView3<'_, f64>],
        measure: &'a M,
    ) -> Result<Self> {
        let key = measure.key();
        let fold_law = validate_extension_fold_law(measure.fold_law(), key.as_str())?;
        let schema = ValidatedExtensionSchema::new("region", key.as_str(), measure.schema())?;
        let declared = measure.sources();
        validate_region_measure_sources(key.as_str(), &declared, sources.len())?;
        validate_region_source_shapes(labels, sources, key.as_str())?;
        Ok(Self {
            measure,
            schema,
            fold_law,
        })
    }

    fn measure(&self) -> &M {
        self.measure
    }

    fn schema(&self) -> Arc<Schema> {
        self.schema.clone_arc()
    }

    fn fold_law(&self) -> ValidatedExtensionFoldLaw {
        self.fold_law
    }
}

impl<'a, M: BoundaryMeasure> ValidatedResidentBoundaryRequest<'a, M> {
    fn new(labels: ArrayView3<'_, f64>, measure: &'a M) -> Result<Self> {
        let key = measure.key();
        let fold_law = validate_extension_fold_law(measure.fold_law(), key.as_str())?;
        let schema = ValidatedExtensionSchema::new("boundary", key.as_str(), measure.schema())?;
        validate_boundary_measure_reach(measure.label_reach(), labels.shape(), key.as_str())?;
        Ok(Self {
            measure,
            schema,
            fold_law,
            connectivity: measure.connectivity(),
        })
    }

    fn measure(&self) -> &M {
        self.measure
    }

    fn schema(&self) -> Arc<Schema> {
        self.schema.clone_arc()
    }

    fn fold_law(&self) -> ValidatedExtensionFoldLaw {
        self.fold_law
    }

    fn connectivity(&self) -> Connectivity {
        self.connectivity
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct CustomRegionSources {
    sources: Vec<TypedSource>,
}

impl CustomRegionSources {
    fn new(sources: Vec<TypedSource>, labels: ImageId) -> Result<Self> {
        let mut seen_images = BTreeSet::new();
        for source in &sources {
            validate_custom_region_source(*source, labels)?;
            if !seen_images.insert(source.image_index()) {
                return Err(Error::invalid(format!(
                    "measurements: custom region source image {} was supplied more than once",
                    source.image_index()
                )));
            }
        }
        Ok(Self { sources })
    }

    fn for_plan(sources: Vec<TypedSource>, labels: ImageId, base: &Decomposition) -> Result<Self> {
        for source in &sources {
            expected_measurement_source_extent(
                ImageId::from(source.image_index()),
                "custom region source image",
                base,
            )?;
        }
        Self::new(sources, labels)
    }

    fn into_vec(self) -> Vec<TypedSource> {
        self.sources
    }
}

fn validate_custom_region_source(source: TypedSource, labels: ImageId) -> Result<()> {
    if source.image == labels.index() {
        return Err(Error::invalid(format!(
            "measurements: the label volume and custom region source image are both image {}. \
             Measurements need labels and values to be separate sources.",
            source.image
        )));
    }
    if let Some(dtype) = source.dtype() {
        MeasurementValueDtype::new(dtype)?;
    }
    Ok(())
}

fn merged_measurement_source_facts(
    base: &Decomposition,
    facts: &MeasurementSourceFacts,
) -> Result<MeasurementSourceFacts> {
    let mut registry = MeasurementSourceFacts::from_decomposition(base)?;
    for (&image, &fact) in &facts.sources {
        validate_user_source_fact_against_base(ImageId::from(image), fact, base)?;
        registry.sources.insert(image, fact);
    }
    Ok(registry)
}

fn validate_user_source_fact_against_base(
    image: ImageId,
    fact: MeasurementSourceFact,
    base: &Decomposition,
) -> Result<()> {
    if image.is_supplied() && !base.supplied_input_images().contains(&image.index()) {
        return Ok(());
    }
    let expected_extent = expected_measurement_source_extent(image, "source registry fact", base)?;
    if fact.extent() != expected_extent {
        return Err(Error::invalid(format!(
            "measurement source facts: source {} has extent {:?}, but the base plan expects {:?}",
            image.index(),
            fact.extent(),
            expected_extent
        )));
    }
    let expected_dtype = base.dtype_at(image.index());
    if fact.dtype() != expected_dtype {
        return Err(Error::invalid(format!(
            "measurement source facts: source {} has dtype {:?}, but the base plan expects {:?}",
            image.index(),
            fact.dtype(),
            expected_dtype
        )));
    }
    Ok(())
}

fn validate_registered_source_fact(
    image: ImageId,
    dtype_hint: Option<Dtype>,
    role: &'static str,
    base: &Decomposition,
    registry: &MeasurementSourceFacts,
) -> Result<MeasurementSourceFact> {
    let expected_extent = expected_measurement_source_extent(image, role, base)?;
    let fact = registry.get(image).ok_or_else(|| {
        Error::invalid(format!(
            "measurements: {role} {} has no registered dtype and extent",
            image.index()
        ))
    })?;
    if let Some(dtype) = dtype_hint {
        if dtype != fact.dtype() {
            return Err(Error::invalid(format!(
                "measurements: {role} {} was declared as {:?}, but the source registry says {:?}",
                image.index(),
                dtype,
                fact.dtype()
            )));
        }
    }
    if fact.extent() != expected_extent {
        return Err(Error::invalid(format!(
            "measurements: {role} {} has extent {:?}, but the base plan expects {:?}",
            image.index(),
            fact.extent(),
            expected_extent
        )));
    }
    Ok(fact)
}

fn expected_measurement_source_extent(
    image: ImageId,
    role: &'static str,
    base: &Decomposition,
) -> Result<[usize; 3]> {
    if image.is_supplied() {
        return Ok(base.volume);
    }
    if image.index() > base.phases.len() {
        return Err(Error::invalid(format!(
            "measurements: {role} {} is not image 0 or an output of the {} phase base plan",
            image.index(),
            base.phases.len()
        )));
    }
    Ok(base.volume_at(image.index()))
}

fn validate_value_source_fact(
    image: ImageId,
    dtype_hint: Option<Dtype>,
    label_source: MeasurementSourceFact,
    role: &'static str,
    base: &Decomposition,
    registry: &MeasurementSourceFacts,
) -> Result<MeasurementSourceFact> {
    if let Some(dtype) = dtype_hint {
        MeasurementValueDtype::new(dtype)?;
    }
    let fact = validate_registered_source_fact(image, dtype_hint, role, base, registry)?;
    MeasurementValueDtype::new(fact.dtype())?;
    fact.grid()
        .ensure_matches(role, image, label_source.grid(), "label image")?;
    fact.ensure_frame_compatible_with(role, image, label_source, "label image")?;
    Ok(fact)
}

