struct ValidatedLabelSource {
    id: ImageId,
    source: MeasurementSourceFact,
}

impl ValidatedLabelSource {
    fn id(self) -> ImageId {
        self.id
    }

    fn typed_source(self) -> TypedSource {
        TypedSource::new(self.id).holding(self.dtype())
    }

    fn extent(self) -> [usize; 3] {
        self.source.extent()
    }

    fn dtype(self) -> Dtype {
        self.source.dtype()
    }

    fn source(self) -> MeasurementSourceFact {
        self.source
    }
}

fn validate_label_source_fact(
    source: LabelImage,
    base: &Decomposition,
    registry: &MeasurementSourceFacts,
) -> Result<ValidatedLabelSource> {
    if let Some(dtype) = source.dtype() {
        MeasurementLabelDtype::new(dtype)?;
    }
    let fact = validate_registered_source_fact(
        source.id(),
        source.dtype(),
        "label image",
        base,
        registry,
    )?;
    MeasurementLabelDtype::new(fact.dtype())?;
    Ok(ValidatedLabelSource {
        id: source.id(),
        source: fact,
    })
}

fn validate_same_grid_label_source_fact(
    source: LabelImage,
    labels: ValidatedLabelSource,
    role: &'static str,
    base: &Decomposition,
    registry: &MeasurementSourceFacts,
) -> Result<ValidatedLabelSource> {
    let checked = validate_label_source_fact(source, base, registry)?;
    checked.source().grid().ensure_matches(
        role,
        checked.id(),
        labels.source().grid(),
        "label image",
    )?;
    checked.source().ensure_frame_compatible_with(
        role,
        checked.id(),
        labels.source(),
        "label image",
    )?;
    Ok(checked)
}

/// Builder-validated intensity source for measurement execution.
///
/// This witness means the source exists in the base plan, has a supported value
/// dtype, is not the label source, and is known to share the label grid and any
/// available physical frame metadata.
#[derive(Debug, Clone, Copy, PartialEq)]
struct ValidatedIntensitySource {
    id: ImageId,
    source: MeasurementSourceFact,
}

impl ValidatedIntensitySource {
    fn id(self) -> ImageId {
        self.id
    }

    fn typed_source(self) -> TypedSource {
        TypedSource::new(self.id).holding(self.dtype())
    }

    fn source(self) -> MeasurementSourceFact {
        self.source
    }

    fn dtype(self) -> Dtype {
        self.source.dtype()
    }
}

fn validate_label_separated_same_grid_value_source(
    image: ImageId,
    dtype_hint: Option<Dtype>,
    labels: ValidatedLabelSource,
    role: &'static str,
    base: &Decomposition,
    registry: &MeasurementSourceFacts,
) -> Result<ValidatedIntensitySource> {
    if image == labels.id() {
        return Err(Error::invalid(format!(
            "measurements: the label volume and {role} are both image {}. Measurements need labels \
             and values to be separate sources.",
            image.index()
        )));
    }
    Ok(ValidatedIntensitySource {
        id: image,
        source: validate_value_source_fact(
            image,
            dtype_hint,
            labels.source(),
            role,
            base,
            registry,
        )?,
    })
}

fn plain_build_label_separated_same_grid_value_source(
    image: ImageId,
    dtype_hint: Option<Dtype>,
    labels: ValidatedLabelSource,
    role: &'static str,
    base: &Decomposition,
    registry: &MeasurementSourceFacts,
) -> Result<PlanBuildValueSource> {
    if registry.get(image).is_some() {
        let source = validate_label_separated_same_grid_value_source(
            image, dtype_hint, labels, role, base, registry,
        )?;
        return Ok(PlanBuildValueSource {
            typed: source.typed_source(),
        });
    }
    if image.is_supplied() {
        let source = label_separated_plan_value_source(labels.id(), image, dtype_hint, role, base)?;
        return Ok(PlanBuildValueSource {
            typed: source.typed_source(),
        });
    }
    validate_label_separated_same_grid_value_source(image, dtype_hint, labels, role, base, registry)
        .map(|source| PlanBuildValueSource {
            typed: source.typed_source(),
        })
}

fn validate_and_stamp_label_separated_same_grid_value_source(
    image: ImageId,
    dtype: &mut Option<Dtype>,
    labels: ValidatedLabelSource,
    role: &'static str,
    base: &Decomposition,
    registry: &MeasurementSourceFacts,
) -> Result<ValidatedIntensitySource> {
    let source = validate_label_separated_same_grid_value_source_pair(
        image, *dtype, labels, role, base, registry,
    )?
    .second();
    if source.id() != image {
        return Err(Error::invalid(format!(
            "measurements: validated {role} source {} but expected {}",
            source.id().index(),
            image.index()
        )));
    }
    *dtype = Some(source.dtype());
    Ok(source)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct SameGrid<A, B> {
    first: A,
    second: B,
}

impl<A, B> SameGrid<A, B> {
    fn first(self) -> A {
        self.first
    }

    fn second(self) -> B {
        self.second
    }
}

type SameGridValuePair = SameGrid<ValidatedIntensitySource, ValidatedIntensitySource>;
type SameGridLabelValueSource = SameGrid<ValidatedLabelSource, ValidatedIntensitySource>;

fn same_grid_label_value_source(
    labels: ValidatedLabelSource,
    value: ValidatedIntensitySource,
) -> SameGridLabelValueSource {
    SameGrid {
        first: labels,
        second: value,
    }
}

fn validate_label_separated_same_grid_value_source_pair(
    image: ImageId,
    dtype_hint: Option<Dtype>,
    labels: ValidatedLabelSource,
    role: &'static str,
    base: &Decomposition,
    registry: &MeasurementSourceFacts,
) -> Result<SameGridLabelValueSource> {
    let value = validate_label_separated_same_grid_value_source(
        image, dtype_hint, labels, role, base, registry,
    )?;
    Ok(same_grid_label_value_source(labels, value))
}

fn same_grid_value_pair(
    channel_a: ValidatedIntensitySource,
    channel_b: ValidatedIntensitySource,
) -> Result<SameGridValuePair> {
    channel_b.source().grid().ensure_matches(
        "colocalization intensity image",
        channel_b.id(),
        channel_a.source().grid(),
        "channel A",
    )?;
    channel_b.source().ensure_frame_compatible_with(
        "colocalization intensity image",
        channel_b.id(),
        channel_a.source(),
        "channel A",
    )?;
    Ok(SameGridValuePair {
        first: channel_a,
        second: channel_b,
    })
}

fn validate_colocalization_value_pair_facts(
    channel_a: ImageId,
    channel_a_dtype: Option<Dtype>,
    channel_b: ImageId,
    channel_b_dtype: Option<Dtype>,
    labels: ValidatedLabelSource,
    base: &Decomposition,
    registry: &MeasurementSourceFacts,
) -> Result<SameGridValuePair> {
    let channel_a = validate_label_separated_same_grid_value_source(
        channel_a,
        channel_a_dtype,
        labels,
        "colocalization intensity image",
        base,
        registry,
    )?;
    let channel_b = validate_label_separated_same_grid_value_source(
        channel_b,
        channel_b_dtype,
        labels,
        "colocalization intensity image",
        base,
        registry,
    )?;
    same_grid_value_pair(channel_a, channel_b)
}

fn plain_build_colocalization_value_pair(
    request: ColocalizationRequest,
    labels: ValidatedLabelSource,
    base: &Decomposition,
    registry: &MeasurementSourceFacts,
) -> Result<PlanBuildChannelPair> {
    if registry.get(request.channel_a).is_some() && registry.get(request.channel_b).is_some() {
        let pair = validate_colocalization_value_pair_facts(
            request.channel_a,
            request.channel_a_dtype,
            request.channel_b,
            request.channel_b_dtype,
            labels,
            base,
            registry,
        )?;
        let channel_a = pair.first();
        let channel_b = pair.second();
        return Ok(PlanBuildChannelPair {
            channel_a: PlanBuildValueSource {
                typed: channel_a.typed_source(),
            },
            channel_b: PlanBuildValueSource {
                typed: channel_b.typed_source(),
            },
            contract: ColocalizationContract::from_validated_pair(labels.id(), pair),
        });
    }
    let channel_a = plain_build_label_separated_same_grid_value_source(
        request.channel_a,
        request.channel_a_dtype,
        labels,
        "a colocalization intensity image",
        base,
        registry,
    )?;
    let channel_b = plain_build_label_separated_same_grid_value_source(
        request.channel_b,
        request.channel_b_dtype,
        labels,
        "a colocalization intensity image",
        base,
        registry,
    )?;
    let contract = colocalization_contract_from_build_pair(labels.id(), channel_a, channel_b);
    Ok(PlanBuildChannelPair {
        channel_a,
        channel_b,
        contract,
    })
}

fn validate_and_stamp_colocalization_request(
    request: &mut ColocalizationRequest,
    labels: ValidatedLabelSource,
    base: &Decomposition,
    registry: &MeasurementSourceFacts,
) -> Result<()> {
    let pair = validate_colocalization_value_pair_facts(
        request.channel_a,
        request.channel_a_dtype,
        request.channel_b,
        request.channel_b_dtype,
        labels,
        base,
        registry,
    )?;
    let channel_a = pair.first();
    let channel_b = pair.second();
    if channel_a.id() != request.channel_a || channel_b.id() != request.channel_b {
        return Err(Error::invalid(
            "measurements: validated colocalization sources do not match the request",
        ));
    }
    request.channel_a_dtype = Some(channel_a.dtype());
    request.channel_b_dtype = Some(channel_b.dtype());
    Ok(())
}

#[derive(Debug, Clone)]
struct CustomBoundaryRequest {
    measure: Arc<dyn ErasedBoundaryMeasure>,
}

struct ActiveMeasurementInputs<'a> {
    shape: ShapeSet,
    intensity: Vec<IntensityRequest>,
    texture: &'a [TextureRequest],
    auto_distribution: &'a [AutoDistributionRequest],
    granularity: &'a [GranularityRequest],
    exact_distribution: &'a [ExactDistributionRequest],
    colocalization: &'a [ColocalizationRequest],
    costes_colocalization: &'a [ColocalizationRequest],
    rank_weighted_colocalization: &'a [ColocalizationRequest],
    radius: Option<RadiusRequest>,
    exact_radius: Option<RadiusRequest>,
    centroid_relationships: Option<CentroidRelationshipRequest>,
    centroid_neighbors: Option<CentroidNeighborRequest>,
    touching_neighbors: Option<TouchingNeighborRequest>,
    overlap_relationships: Option<OverlapRelationshipRequest>,
    overlap_assignments: Option<OverlapAssignmentRequest>,
    overlap_child_counts: Option<OverlapChildCountRequest>,
    boundary_distance_relationships: Option<BoundaryDistanceRelationshipRequest>,
    expansion_relationships: Option<ExpansionRelationshipRequest>,
    moment3d: Option<ObjectMoment3dRequest>,
    geometry: Option<ObjectGeometryRequest>,
    geometry_basic: Option<ObjectGeometryBasicRequest>,
    directional_feret: Option<ObjectDirectionalFeretRequest>,
    convex_hull: Option<ObjectConvexHullRequest>,
    voxel_face_convex_hull: Option<ObjectVoxelFaceConvexHullRequest>,
    enclosing_sphere: Option<EnclosingSphereRequest>,
    projected_convex: Option<ProjectedConvexRequest>,
    hu_moments: Option<ObjectHuMomentRequest>,
    zernike_moments: Option<ObjectZernikeMomentRequest>,
    zernike3d: Option<ObjectZernike3dRequest>,
    weighted_hu_moments: Option<ObjectWeightedHuMomentRequest>,
    custom_object: &'a [Arc<dyn ObjectMeasure>],
    custom_region: &'a [CustomRegionRequest],
    custom_boundary: &'a [CustomBoundaryRequest],
    labels: ImageId,
}

impl ActiveMeasurementInputs<'_> {
    fn requests_any_family(&self) -> bool {
        ActiveShapeRequests::new(self.shape).wants_any()
            || self
                .intensity
                .iter()
                .any(|request| ActiveIntensityRequest::new(*request).is_some())
            || !self.texture.is_empty()
            || !self.auto_distribution.is_empty()
            || !self.granularity.is_empty()
            || !self.exact_distribution.is_empty()
            || !self.colocalization.is_empty()
            || !self.costes_colocalization.is_empty()
            || !self.rank_weighted_colocalization.is_empty()
            || self.radius.is_some()
            || self.exact_radius.is_some()
            || self.centroid_relationships.is_some()
            || self.centroid_neighbors.is_some()
            || self.touching_neighbors.is_some()
            || self.overlap_relationships.is_some()
            || self.overlap_assignments.is_some()
            || self.overlap_child_counts.is_some()
            || self.boundary_distance_relationships.is_some()
            || self.expansion_relationships.is_some()
            || self.moment3d.is_some()
            || self.geometry.is_some()
            || self.geometry_basic.is_some()
            || self.directional_feret.is_some()
            || self.convex_hull.is_some()
            || self.voxel_face_convex_hull.is_some()
            || self.enclosing_sphere.is_some()
            || self.projected_convex.is_some()
            || self.hu_moments.is_some()
            || self.zernike_moments.is_some()
            || self.zernike3d.is_some()
            || self.weighted_hu_moments.is_some()
            || !self.custom_object.is_empty()
            || !self.custom_region.is_empty()
            || !self.custom_boundary.is_empty()
    }
}

impl ActiveMeasurementRequests {
    fn new(input: ActiveMeasurementInputs<'_>) -> Result<Self> {
        if !input.requests_any_family() {
            return Err(Error::invalid(
                "measurements: at least one measurement family must be requested: shape, \
                 intensity, texture, granularity, distribution, radius, relationship, \
                 object-local, colocalization or custom extension",
            ));
        }
        let ActiveMeasurementInputs {
            shape,
            intensity,
            texture,
            auto_distribution,
            granularity,
            exact_distribution,
            colocalization,
            costes_colocalization,
            rank_weighted_colocalization,
            radius,
            exact_radius,
            centroid_relationships,
            centroid_neighbors,
            touching_neighbors,
            overlap_relationships: _,
            overlap_assignments: _,
            overlap_child_counts: _,
            zernike_moments,
            zernike3d,
            weighted_hu_moments,
            labels,
            ..
        } = input;
        let active: Vec<_> = intensity
            .into_iter()
            .filter_map(ActiveIntensityRequest::new)
            .collect();
        let shape = if centroid_relationships.is_some() || centroid_neighbors.is_some() {
            shape.with_basic()
        } else {
            shape
        };
        let shape = if touching_neighbors.is_some() {
            shape.with_contacts()
        } else {
            shape
        };
        let active_shape = ActiveShapeRequests::new(shape);
        if let Some(radius) = radius {
            radius.params.squared_sampling()?;
        }
        if let Some(radius) = exact_radius {
            radius.params.squared_sampling()?;
        }
        if let Some(request) = zernike_moments {
            object_zernike_moment_measurement_schema_set(request.set)?;
        }
        if let Some(request) = zernike3d {
            object_zernike3d_measurement_schema_set(request.set)?;
        }
        for request in &active {
            request.source_distinct_from_labels(labels, "intensity image")?;
        }
        for request in texture {
            request.source_distinct_from_labels(labels, "texture intensity image")?;
        }
        for request in auto_distribution {
            request.source_distinct_from_labels(labels, "auto-distribution intensity image")?;
        }
        for request in granularity {
            request.source_distinct_from_labels(labels, "granularity intensity image")?;
        }
        for request in exact_distribution {
            request.source_distinct_from_labels(labels, "exact-distribution intensity image")?;
        }
        if let Some(request) = weighted_hu_moments {
            request.source_distinct_from_labels(labels, "weighted-Hu intensity image")?;
        }
        for request in colocalization {
            MeasurementChannelPair::new(*request, labels)?;
        }
        for request in costes_colocalization {
            MeasurementChannelPair::new(*request, labels)?;
        }
        for request in rank_weighted_colocalization {
            MeasurementChannelPair::new(*request, labels)?;
        }
        let basic_intensity = active
            .iter()
            .copied()
            .filter(|request| request.wants_basic())
            .collect::<Vec<_>>();
        if basic_intensity.len() > MAX_FUSED_BASIC_INTENSITIES {
            return Err(Error::invalid(format!(
                "measurements: Class A basic intensity fusion supports at most \
                 {MAX_FUSED_BASIC_INTENSITIES} value image(s), got {}",
                basic_intensity.len()
            )));
        }
        let mut basic_images = BTreeSet::new();
        for request in &basic_intensity {
            if !basic_images.insert(request.id.index()) {
                return Err(Error::invalid(format!(
                    "measurements: Class A basic intensity fusion was given image {} more than \
                     once",
                    request.id.index()
                )));
            }
        }
        let distribution_intensity = active
            .iter()
            .copied()
            .filter(|request| request.distribution_set().is_some())
            .collect::<Vec<_>>();
        let distribution_intensity = match distribution_intensity.as_slice() {
            [] => None,
            [request] => Some(*request),
            many => {
                return Err(Error::invalid(format!(
                    "measurements: this implementation compiles at most one fixed-range intensity \
                     distribution request, got {}",
                    many.len()
                )));
            }
        };
        Ok(Self {
            active_shape,
            basic_intensity,
            distribution_intensity,
        })
    }

    fn shape(&self) -> ShapeSet {
        self.active_shape.to_shape_set()
    }

    fn active_shape(&self) -> ActiveShapeRequests {
        self.active_shape
    }

    fn basic_intensity(&self) -> &[ActiveIntensityRequest] {
        &self.basic_intensity
    }

    fn distribution_intensity(&self) -> Option<ActiveIntensityRequest> {
        self.distribution_intensity
    }

    fn intensity_set(&self) -> IntensitySet {
        if self
            .basic_intensity
            .iter()
            .any(|request| request.wants_basic())
        {
            IntensitySet::basic()
        } else {
            self.distribution_intensity
                .map(ActiveIntensityRequest::to_set)
                .unwrap_or_else(IntensitySet::none)
        }
    }
}

