macro_rules! non_empty_stream_type {
    ($name:ident, $empty_message:literal) => {
        #[derive(Debug, Clone, PartialEq, Eq)]
        struct $name(String);

        impl $name {
            fn new(stream: impl Into<String>) -> Result<Self> {
                let stream = stream.into();
                if stream.is_empty() {
                    return Err(Error::invalid($empty_message));
                }
                Ok(Self(stream))
            }

            fn as_str(&self) -> &str {
                &self.0
            }
        }

        impl ValidatedStreamName for $name {
            fn as_str(&self) -> &str {
                self.as_str()
            }
        }
    };
}

trait ValidatedStreamName {
    fn as_str(&self) -> &str;
}

trait RowStreamToken {
    fn as_str(&self) -> &str;
}

trait PartialStreamToken {
    fn as_str(&self) -> &str;
}

fn partial_stream_name(stream: &dyn PartialStreamToken) -> &str {
    stream.as_str()
}

macro_rules! row_stream_type {
    ($name:ident, $empty_message:literal) => {
        non_empty_stream_type!($name, $empty_message);

        impl RowStreamToken for $name {
            fn as_str(&self) -> &str {
                self.as_str()
            }
        }
    };
}

macro_rules! partial_stream_type {
    ($name:ident, $empty_message:literal) => {
        non_empty_stream_type!($name, $empty_message);

        impl PartialStreamToken for $name {
            fn as_str(&self) -> &str {
                self.as_str()
            }
        }
    };
}

non_empty_stream_type!(
    MeasurementOutputRoot,
    "measurements: output stream root must not be empty"
);

impl RowStreamToken for MeasurementOutputRoot {
    fn as_str(&self) -> &str {
        self.as_str()
    }
}

