struct OnePhaseMeasurementPlan<Output, Op, Meta = ()> {
    output: Output,
    rows_phase: usize,
    meta: Meta,
    op: Op,
}

impl<Output, Op, Meta> OnePhaseMeasurementPlan<Output, Op, Meta>
where
    Op: FragmentOp,
{
    fn rows_phase(&self) -> usize {
        self.rows_phase
    }

    fn phase_work(&self) -> PhaseWork<'_> {
        PhaseWork::Fragments(&self.op)
    }
}

impl<Output, Op, Meta, K> RowPlan<K> for OnePhaseMeasurementPlan<Output, Op, Meta>
where
    Output: RowStreamToken,
{
    fn rows_handle(&self) -> MeasurementRows<K> {
        measurement_rows(&self.output, self.rows_phase)
    }
}

impl<Output, Op, Meta> OnePhaseMeasurementPlan<Output, Op, Meta>
where
    Output: RowStreamToken,
    Meta: Clone,
{
    fn rows_with_contract<K>(&self) -> MeasurementRowsWithContract<K, Meta> {
        MeasurementRowsWithContract::new(self.rows_handle(), self.meta.clone())
    }
}

fn push_measurement_fragment_phase(
    decomposition: &mut Decomposition,
    grid: &BlockGrid,
    op: &dyn FragmentOp,
) -> Result<usize> {
    let phase = next_measurement_phase_index(decomposition);
    decomposition.phases.push(fragment_phase(op, grid.clone())?);
    Ok(phase)
}

fn next_measurement_phase_index(decomposition: &Decomposition) -> usize {
    decomposition.phases.len()
}

fn append_one_phase_measurement<Output, Op>(
    decomposition: &mut Decomposition,
    grid: &BlockGrid,
    output: Output,
    op: Op,
) -> Result<OnePhaseMeasurementPlan<Output, Op>>
where
    Op: FragmentOp,
{
    append_one_phase_measurement_with_meta(decomposition, grid, output, (), op)
}

fn append_one_phase_measurement_with_meta<Output, Meta, Op>(
    decomposition: &mut Decomposition,
    grid: &BlockGrid,
    output: Output,
    meta: Meta,
    op: Op,
) -> Result<OnePhaseMeasurementPlan<Output, Op, Meta>>
where
    Op: FragmentOp,
{
    let rows_phase = push_measurement_fragment_phase(decomposition, grid, &op)?;
    Ok(OnePhaseMeasurementPlan {
        output,
        rows_phase,
        meta,
        op,
    })
}

type RadiusPlan =
    OnePhaseMeasurementPlan<RadiusOutputStream, SharedBoundaryRadiusOp, DistanceParams>;
type ExactRadiusPlan =
    OnePhaseMeasurementPlan<RadiusOutputStream, ExactLabelRadiusOp, DistanceParams>;
type TopologyPlan = OnePhaseMeasurementPlan<TopologyOutputStream, ObjectTopologyOp>;
type ComponentPlan = OnePhaseMeasurementPlan<ComponentOutputStream, ObjectComponentOp>;
type AutoDistributionPlan =
    OnePhaseMeasurementPlan<AutoDistributionOutputStream, AutoDistributionOp, AutoDistributionSet>;
type GranularityPlan =
    OnePhaseMeasurementPlan<GranularityOutputStream, GranularityOp, GranularitySet>;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct OrderedPhasePair {
    tally: usize,
    merge: usize,
}

impl OrderedPhasePair {
    fn new(tally: usize, merge: usize) -> Result<Self> {
        if tally >= merge {
            return Err(Error::invalid(format!(
                "measurement phase pair: producer phase {tally} must precede merge phase {merge}"
            )));
        }
        Ok(Self { tally, merge })
    }

    fn merge(self) -> usize {
        self.merge
    }

    fn tally(self) -> usize {
        self.tally
    }
}

struct PhasePair<Tally, Merge, Layout = ()> {
    phases: OrderedPhasePair,
    tally: Tally,
    merge: Merge,
    layout: std::marker::PhantomData<Layout>,
}

impl<Tally, Merge, Layout> PhasePair<Tally, Merge, Layout> {
    fn from_inserted_phases(
        tally_phase: usize,
        merge_phase: usize,
        tally: Tally,
        merge: Merge,
    ) -> Result<Self> {
        Ok(Self {
            phases: OrderedPhasePair::new(tally_phase, merge_phase)?,
            tally,
            merge,
            layout: std::marker::PhantomData,
        })
    }

    fn rows_phase(&self) -> usize {
        self.phases.merge()
    }
}

impl<Tally, Merge, Layout> PhasePair<Tally, Merge, Layout>
where
    Tally: FragmentOp,
    Merge: FragmentOp,
{
    fn new(
        decomposition: &mut Decomposition,
        grid: &BlockGrid,
        tally: Tally,
        merge: impl FnOnce(usize) -> Result<Merge>,
    ) -> Result<Self> {
        let tally_phase = next_measurement_phase_index(decomposition);
        let merge = merge(tally_phase)?;
        let inserted_tally_phase = push_measurement_fragment_phase(decomposition, grid, &tally)?;
        if inserted_tally_phase != tally_phase {
            return Err(Error::invalid(format!(
                "measurement phase pair: inserted producer phase {inserted_tally_phase} differed from planned phase {tally_phase}"
            )));
        }
        let merge_phase = push_measurement_fragment_phase(decomposition, grid, &merge)?;
        Self::from_inserted_phases(tally_phase, merge_phase, tally, merge)
    }

    fn phase_work(&self) -> [PhaseWork<'_>; 2] {
        [
            PhaseWork::Fragments(&self.tally),
            PhaseWork::Fragments(&self.merge),
        ]
    }
}

struct ClassAOutputPlan {
    output: MeasurementOutputRoot,
    phases: OrderedPhasePair,
}

impl ClassAOutputPlan {
    fn new(
        output: MeasurementOutputRoot,
        producer_phase: usize,
        rows_phase: usize,
    ) -> Result<Self> {
        Ok(Self {
            output,
            phases: OrderedPhasePair::new(producer_phase, rows_phase)?,
        })
    }

    fn rows_phase(&self) -> usize {
        self.phases.merge()
    }

    fn rows_handle<K>(&self) -> MeasurementRows<K> {
        measurement_rows(&self.output, self.rows_phase())
    }
}

struct ClassATabulationPlan {
    scan: OneProducerManyMergesPlan<MeasureTabulateOp, MergeTabulationOp>,
    primary: ClassAOutputPlan,
    intensity: Vec<ClassAOutputPlan>,
}

impl ClassATabulationPlan {
    fn rows_phase(&self) -> usize {
        self.primary.rows_phase()
    }

    fn phase_work(&self) -> Vec<PhaseWork<'_>> {
        self.scan.phase_work()
    }

    fn primary_rows<K>(&self) -> MeasurementRows<K> {
        self.primary.rows_handle()
    }

    fn intensity_rows<K>(&self, index: usize) -> Option<MeasurementRows<K>> {
        self.intensity.get(index).map(ClassAOutputPlan::rows_handle)
    }
}

fn append_class_a_tabulation(
    decomposition: &mut Decomposition,
    grid: &BlockGrid,
    output: MeasurementOutputRoot,
    intensity_output: bool,
    tabulate: MeasureTabulateOp,
    merge: impl FnOnce(usize) -> Result<MergeTabulationOp>,
) -> Result<ClassATabulationPlan> {
    let partial_phase = push_measurement_fragment_phase(decomposition, grid, &tabulate)?;
    let merge = merge(partial_phase)?;
    let rows_phase = push_measurement_fragment_phase(decomposition, grid, &merge)?;
    let primary = ClassAOutputPlan::new(output.clone(), partial_phase, rows_phase)?;
    Ok(ClassATabulationPlan {
        scan: OneProducerManyMergesPlan {
            tally: tabulate,
            merges: vec![merge],
        },
        primary,
        intensity: if intensity_output {
            vec![ClassAOutputPlan::new(output, partial_phase, rows_phase)?]
        } else {
            Vec::new()
        },
    })
}

fn append_multi_class_a_tabulation(
    decomposition: &mut Decomposition,
    grid: &BlockGrid,
    primary: MeasurementOutputRoot,
    tabulate: MeasureTabulateOp,
    entries: Vec<(MeasurementOutputRoot, TabulationPartialStream)>,
    merge: impl Fn(&MeasurementOutputRoot, &TabulationPartialStream, usize) -> Result<MergeTabulationOp>,
) -> Result<ClassATabulationPlan> {
    let partial_phase = push_measurement_fragment_phase(decomposition, grid, &tabulate)?;
    let mut merges = Vec::with_capacity(entries.len());
    let mut intensity = Vec::with_capacity(entries.len());
    for (output, partials) in entries {
        let merge = merge(&output, &partials, partial_phase)?;
        let rows_phase = push_measurement_fragment_phase(decomposition, grid, &merge)?;
        intensity.push(ClassAOutputPlan::new(output, partial_phase, rows_phase)?);
        merges.push(merge);
    }
    let primary = intensity
        .first()
        .map(|output| ClassAOutputPlan::new(primary, partial_phase, output.rows_phase()))
        .transpose()?
        .ok_or_else(|| Error::invalid("measurements: multi-intensity Class A has no outputs"))?;
    Ok(ClassATabulationPlan {
        scan: OneProducerManyMergesPlan {
            tally: tabulate,
            merges,
        },
        primary,
        intensity,
    })
}

struct RowOutputPlanWithMeta<Output, Meta> {
    output: Output,
    phases: OrderedPhasePair,
    meta: Meta,
}

impl<Output, Meta> RowOutputPlanWithMeta<Output, Meta> {
    fn new(output: Output, producer_phase: usize, rows_phase: usize, meta: Meta) -> Result<Self> {
        Ok(Self {
            output,
            phases: OrderedPhasePair::new(producer_phase, rows_phase)?,
            meta,
        })
    }

    fn rows_phase(&self) -> usize {
        self.phases.merge()
    }
}

impl<Output, Meta, K> RowPlan<K> for RowOutputPlanWithMeta<Output, Meta>
where
    Output: RowStreamToken,
{
    fn rows_handle(&self) -> MeasurementRows<K> {
        measurement_rows(&self.output, self.rows_phase())
    }
}

impl<Output, Meta> RowOutputPlanWithMeta<Output, Meta>
where
    Output: RowStreamToken,
    Meta: Clone,
{
    fn rows_with_contract<K>(&self) -> MeasurementRowsWithContract<K, Meta> {
        MeasurementRowsWithContract::new(self.rows_handle(), self.meta.clone())
    }
}

/// Validated GLCM texture request contract carried by planned row outputs.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct GlcmTextureContract {
    quantization: GlcmQuantization,
    offset: GlcmOffset,
}

impl GlcmTextureContract {
    pub fn new(quantization: GlcmQuantization, offset: GlcmOffset) -> Self {
        Self {
            quantization,
            offset,
        }
    }

    pub fn quantization(self) -> GlcmQuantization {
        self.quantization
    }

    pub fn offset(self) -> GlcmOffset {
        self.offset
    }

    pub fn parts(self) -> (GlcmQuantization, GlcmOffset) {
        (self.quantization, self.offset)
    }
}

struct OneProducerManyMergesPlan<Tally, Merge> {
    tally: Tally,
    merges: Vec<Merge>,
}

impl<Tally, Merge> OneProducerManyMergesPlan<Tally, Merge>
where
    Tally: FragmentOp,
    Merge: FragmentOp,
{
    fn phase_work(&self) -> Vec<PhaseWork<'_>> {
        let mut work = Vec::with_capacity(1 + self.merges.len());
        work.push(PhaseWork::Fragments(&self.tally));
        work.extend(
            self.merges
                .iter()
                .map(|merge| PhaseWork::Fragments(merge as &dyn FragmentOp)),
        );
        work
    }
}

type TextureOutputPlan = RowOutputPlanWithMeta<TextureOutputStream, GlcmTextureContract>;
type TextureScanPlan = OneProducerManyMergesPlan<MultiGlcmTextureOp, MergeGlcmTextureOp>;

struct TextureAppendPlan {
    plan: TextureScanPlan,
    outputs: Vec<(usize, TextureOutputPlan)>,
}

fn append_texture_scan(
    decomposition: &mut Decomposition,
    grid: &BlockGrid,
    tally: MultiGlcmTextureOp,
    entries: Vec<TextureGroupEntry>,
    quantization: GlcmQuantization,
    merge: impl Fn(&TextureGroupEntry, usize) -> Result<MergeGlcmTextureOp>,
) -> Result<TextureAppendPlan> {
    let partial_phase = push_measurement_fragment_phase(decomposition, grid, &tally)?;
    let mut merges = Vec::with_capacity(entries.len());
    let mut outputs = Vec::with_capacity(entries.len());
    for entry in entries {
        let merge = merge(&entry, partial_phase)?;
        let rows_phase = push_measurement_fragment_phase(decomposition, grid, &merge)?;
        outputs.push((
            entry.index,
            TextureOutputPlan::new(
                entry.output,
                partial_phase,
                rows_phase,
                GlcmTextureContract::new(quantization, entry.offset),
            )?,
        ));
        merges.push(merge);
    }
    Ok(TextureAppendPlan {
        plan: TextureScanPlan { tally, merges },
        outputs,
    })
}

