struct TextureGroupEntry {
    index: usize,
    offset: GlcmOffset,
    partial_stream: TexturePartialStream,
    output: TextureOutputStream,
}

struct TextureGroup {
    id: ImageId,
    dtype: Option<Dtype>,
    quantization: GlcmQuantization,
    entries: Vec<TextureGroupEntry>,
}

impl TextureGroup {
    fn accepts(&self, request: TextureRequest) -> bool {
        self.id == request.id
            && self.dtype == request.dtype
            && self.quantization == request.quantization
            && !self
                .entries
                .iter()
                .any(|entry| entry.offset == request.offset)
    }
}

struct TextureGroups {
    groups: Vec<TextureGroup>,
}

impl TextureGroups {
    fn from_requests(requests: Vec<TextureRequest>, rows: &str) -> Result<Self> {
        let mut groups: Vec<TextureGroup> = Vec::new();
        for (index, request) in requests.into_iter().enumerate() {
            let entry = TextureGroupEntry {
                index,
                offset: request.offset,
                partial_stream: TexturePartialStream::new(format!(
                    "{rows}.texture.{index}.partials"
                ))?,
                output: TextureOutputStream::new(format!("{rows}.texture.{index}"))?,
            };
            match groups.iter_mut().find(|group| group.accepts(request)) {
                Some(group) => group.entries.push(entry),
                None => groups.push(TextureGroup {
                    id: request.id,
                    dtype: request.dtype,
                    quantization: request.quantization,
                    entries: vec![entry],
                }),
            }
        }
        Ok(Self { groups })
    }
}

struct TwoPhaseMeasurementPlan<Output, Tally, Merge, Layout, Meta = ()> {
    output: Output,
    meta: Meta,
    pair: PhasePair<Tally, Merge, Layout>,
}

impl<Output, Tally, Merge, Layout, Meta> TwoPhaseMeasurementPlan<Output, Tally, Merge, Layout, Meta>
where
    Tally: FragmentOp,
    Merge: FragmentOp,
{
    fn rows_phase(&self) -> usize {
        self.pair.rows_phase()
    }

    fn phase_work(&self) -> [PhaseWork<'_>; 2] {
        self.pair.phase_work()
    }
}

impl<Output, Tally, Merge, Layout, Meta, K> RowPlan<K>
    for TwoPhaseMeasurementPlan<Output, Tally, Merge, Layout, Meta>
where
    Output: RowStreamToken,
{
    fn rows_handle(&self) -> MeasurementRows<K> {
        measurement_rows(&self.output, self.pair.rows_phase())
    }
}

impl<Output, Tally, Merge, Layout, Meta> TwoPhaseMeasurementPlan<Output, Tally, Merge, Layout, Meta>
where
    Output: RowStreamToken,
    Meta: Clone,
{
    fn rows_with_contract<K>(&self) -> MeasurementRowsWithContract<K, Meta> {
        MeasurementRowsWithContract::new(self.rows_handle(), self.meta.clone())
    }
}

fn append_two_phase_measurement<Output, Tally, Merge, Layout>(
    decomposition: &mut Decomposition,
    grid: &BlockGrid,
    output: Output,
    tally: Tally,
    merge: impl FnOnce(usize) -> Result<Merge>,
) -> Result<TwoPhaseMeasurementPlan<Output, Tally, Merge, Layout>>
where
    Tally: FragmentOp,
    Merge: FragmentOp,
{
    append_two_phase_measurement_with_meta(decomposition, grid, output, (), tally, merge)
}

fn append_two_phase_measurement_with_meta<Output, Meta, Tally, Merge, Layout>(
    decomposition: &mut Decomposition,
    grid: &BlockGrid,
    output: Output,
    meta: Meta,
    tally: Tally,
    merge: impl FnOnce(usize) -> Result<Merge>,
) -> Result<TwoPhaseMeasurementPlan<Output, Tally, Merge, Layout, Meta>>
where
    Tally: FragmentOp,
    Merge: FragmentOp,
{
    let pair = PhasePair::new(decomposition, grid, tally, merge)?;
    Ok(TwoPhaseMeasurementPlan { output, meta, pair })
}

