#[derive(Debug, Clone, PartialEq, Eq)]
struct BoundaryOutputStreams {
    boundary: Option<BoundaryOutputStream>,
    contacts: Option<ContactOutputStream>,
}

impl BoundaryOutputStreams {
    fn new(boundary: Option<String>, contacts: Option<String>) -> Result<Self> {
        if boundary.is_none() && contacts.is_none() {
            return Err(Error::invalid(
                "measure boundaries: a boundary pass needs boundary or contact rows",
            ));
        }
        Ok(Self {
            boundary: boundary.map(BoundaryOutputStream::new).transpose()?,
            contacts: contacts.map(ContactOutputStream::new).transpose()?,
        })
    }

    fn boundary(&self) -> Option<&str> {
        self.boundary.as_ref().map(BoundaryOutputStream::as_str)
    }

    fn contacts(&self) -> Option<&str> {
        self.contacts.as_ref().map(ContactOutputStream::as_str)
    }

    fn has_boundary(&self) -> bool {
        self.boundary.is_some()
    }

    fn has_contacts(&self) -> bool {
        self.contacts.is_some()
    }

    fn boundary_rows(&self, phase: usize) -> Option<MeasurementRows<BoundaryRows>> {
        self.boundary
            .as_ref()
            .map(|stream| measurement_rows(stream, phase))
    }

    fn contact_rows(&self, phase: usize) -> Option<MeasurementRows<ContactRows>> {
        self.contacts
            .as_ref()
            .map(|stream| measurement_rows(stream, phase))
    }
}

/// Derived shape measurements that do not need stored columns of their own.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct ShapeMeasurements {
    pub label: u64,
    pub count: u64,
    pub centroid: Option<[f64; 3]>,
    pub bbox_min: [u64; 3],
    pub bbox_max: [u64; 3],
    pub bbox_extent: [u64; 3],
    pub bbox_volume: u64,
    pub bbox_fill_fraction: Option<f64>,
    pub equivalent_sphere_radius: f64,
    pub equivalent_sphere_diameter: f64,
    pub principal_axis_lengths: Option<[f64; 3]>,
    pub orientation: Option<[f64; 3]>,
    /// Planar major-axis orientation in the Y/X plane, measured from +X toward +Y.
    pub orientation_yx: Option<f64>,
    pub eccentricity: Option<f64>,
}

/// Derived scalar that can be read from a stored shape row.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum ShapeFeature {
    Count,
    CentroidZ,
    CentroidY,
    CentroidX,
    BboxMinZ,
    BboxMinY,
    BboxMinX,
    BboxMaxZ,
    BboxMaxY,
    BboxMaxX,
    BboxExtentZ,
    BboxExtentY,
    BboxExtentX,
    BboxVolume,
    BboxFillFraction,
    EquivalentSphereRadius,
    EquivalentSphereDiameter,
    PrincipalAxisLength0,
    PrincipalAxisLength1,
    PrincipalAxisLength2,
    OrientationZ,
    OrientationY,
    OrientationX,
    OrientationYx,
    Eccentricity,
}

impl ShapeFeature {
    pub const ALL: [Self; 25] = [
        Self::Count,
        Self::CentroidZ,
        Self::CentroidY,
        Self::CentroidX,
        Self::BboxMinZ,
        Self::BboxMinY,
        Self::BboxMinX,
        Self::BboxMaxZ,
        Self::BboxMaxY,
        Self::BboxMaxX,
        Self::BboxExtentZ,
        Self::BboxExtentY,
        Self::BboxExtentX,
        Self::BboxVolume,
        Self::BboxFillFraction,
        Self::EquivalentSphereRadius,
        Self::EquivalentSphereDiameter,
        Self::PrincipalAxisLength0,
        Self::PrincipalAxisLength1,
        Self::PrincipalAxisLength2,
        Self::OrientationZ,
        Self::OrientationY,
        Self::OrientationX,
        Self::OrientationYx,
        Self::Eccentricity,
    ];

    pub fn column_name(self) -> &'static str {
        match self {
            Self::Count => "count",
            Self::CentroidZ => "centroid_z",
            Self::CentroidY => "centroid_y",
            Self::CentroidX => "centroid_x",
            Self::BboxMinZ => "bbox_min_z",
            Self::BboxMinY => "bbox_min_y",
            Self::BboxMinX => "bbox_min_x",
            Self::BboxMaxZ => "bbox_max_z",
            Self::BboxMaxY => "bbox_max_y",
            Self::BboxMaxX => "bbox_max_x",
            Self::BboxExtentZ => "bbox_extent_z",
            Self::BboxExtentY => "bbox_extent_y",
            Self::BboxExtentX => "bbox_extent_x",
            Self::BboxVolume => "bbox_volume",
            Self::BboxFillFraction => "bbox_fill_fraction",
            Self::EquivalentSphereRadius => "equivalent_sphere_radius",
            Self::EquivalentSphereDiameter => "equivalent_sphere_diameter",
            Self::PrincipalAxisLength0 => "principal_axis_length_0",
            Self::PrincipalAxisLength1 => "principal_axis_length_1",
            Self::PrincipalAxisLength2 => "principal_axis_length_2",
            Self::OrientationZ => "orientation_z",
            Self::OrientationY => "orientation_y",
            Self::OrientationX => "orientation_x",
            Self::OrientationYx => "orientation_yx",
            Self::Eccentricity => "eccentricity",
        }
    }
}

impl ShapeMeasurements {
    pub fn from_shape(shape: &RegionShape) -> Self {
        let radius = equivalent_sphere_radius(shape.count);
        let axes = shape.principal_axes();
        Self {
            label: shape.label,
            count: shape.count,
            centroid: shape.centroid(),
            bbox_min: shape.bbox_min,
            bbox_max: shape.bbox_max,
            bbox_extent: shape.bbox_extent(),
            bbox_volume: shape.bbox_volume(),
            bbox_fill_fraction: shape.bbox_fill_fraction(),
            equivalent_sphere_radius: radius,
            equivalent_sphere_diameter: equivalent_sphere_diameter(shape.count),
            principal_axis_lengths: axes.map(|axes| axes.length),
            orientation: shape.orientation(),
            orientation_yx: orientation_yx(shape),
            eccentricity: shape.eccentricity(),
        }
    }

    pub fn feature(&self, feature: ShapeFeature) -> Option<f64> {
        match feature {
            ShapeFeature::Count => exact_u64_feature(self.count),
            ShapeFeature::CentroidZ => self.centroid.map(|centroid| centroid[0]),
            ShapeFeature::CentroidY => self.centroid.map(|centroid| centroid[1]),
            ShapeFeature::CentroidX => self.centroid.map(|centroid| centroid[2]),
            ShapeFeature::BboxMinZ => exact_u64_feature(self.bbox_min[0]),
            ShapeFeature::BboxMinY => exact_u64_feature(self.bbox_min[1]),
            ShapeFeature::BboxMinX => exact_u64_feature(self.bbox_min[2]),
            ShapeFeature::BboxMaxZ => exact_u64_feature(self.bbox_max[0]),
            ShapeFeature::BboxMaxY => exact_u64_feature(self.bbox_max[1]),
            ShapeFeature::BboxMaxX => exact_u64_feature(self.bbox_max[2]),
            ShapeFeature::BboxExtentZ => exact_u64_feature(self.bbox_extent[0]),
            ShapeFeature::BboxExtentY => exact_u64_feature(self.bbox_extent[1]),
            ShapeFeature::BboxExtentX => exact_u64_feature(self.bbox_extent[2]),
            ShapeFeature::BboxVolume => exact_u64_feature(self.bbox_volume),
            ShapeFeature::BboxFillFraction => self.bbox_fill_fraction,
            ShapeFeature::EquivalentSphereRadius => Some(self.equivalent_sphere_radius),
            ShapeFeature::EquivalentSphereDiameter => Some(self.equivalent_sphere_diameter),
            ShapeFeature::PrincipalAxisLength0 => {
                self.principal_axis_lengths.map(|length| length[0])
            }
            ShapeFeature::PrincipalAxisLength1 => {
                self.principal_axis_lengths.map(|length| length[1])
            }
            ShapeFeature::PrincipalAxisLength2 => {
                self.principal_axis_lengths.map(|length| length[2])
            }
            ShapeFeature::OrientationZ => self.orientation.map(|orientation| orientation[0]),
            ShapeFeature::OrientationY => self.orientation.map(|orientation| orientation[1]),
            ShapeFeature::OrientationX => self.orientation.map(|orientation| orientation[2]),
            ShapeFeature::OrientationYx => self.orientation_yx,
            ShapeFeature::Eccentricity => self.eccentricity,
        }
    }
}

/// Derived intensity measurements from one tabulated value channel.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct IntensityMeasurements {
    pub label: u64,
    pub count: u64,
    pub finite_count: u64,
    pub nonfinite: u64,
    pub sum: f64,
    pub mean: Option<f64>,
    pub min: Option<f64>,
    pub max: Option<f64>,
    pub weighted_centroid: Option<[f64; 3]>,
}

/// Derived scalar that can be read from a stored intensity row.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum IntensityFeature {
    Count,
    FiniteCount,
    Nonfinite,
    Sum,
    Mean,
    Min,
    Max,
    WeightedCentroidZ,
    WeightedCentroidY,
    WeightedCentroidX,
}

impl IntensityFeature {
    pub const ALL: [Self; 10] = [
        Self::Count,
        Self::FiniteCount,
        Self::Nonfinite,
        Self::Sum,
        Self::Mean,
        Self::Min,
        Self::Max,
        Self::WeightedCentroidZ,
        Self::WeightedCentroidY,
        Self::WeightedCentroidX,
    ];

    pub fn column_name(self) -> &'static str {
        match self {
            Self::Count => "count",
            Self::FiniteCount => "finite_count",
            Self::Nonfinite => "nonfinite",
            Self::Sum => "sum",
            Self::Mean => "mean",
            Self::Min => "min",
            Self::Max => "max",
            Self::WeightedCentroidZ => "weighted_centroid_z",
            Self::WeightedCentroidY => "weighted_centroid_y",
            Self::WeightedCentroidX => "weighted_centroid_x",
        }
    }
}

impl IntensityMeasurements {
    pub fn from_values(values: &RegionValues) -> Self {
        let finite_count = values.count - values.nonfinite;
        Self {
            label: values.label,
            count: values.count,
            finite_count,
            nonfinite: values.nonfinite,
            sum: values.sum,
            mean: (finite_count != 0).then_some(values.sum / finite_count as f64),
            min: (!values.all_nonfinite()).then_some(values.min),
            max: (!values.all_nonfinite()).then_some(values.max),
            weighted_centroid: values.weighted_centroid,
        }
    }

    pub fn feature(&self, feature: IntensityFeature) -> Option<f64> {
        match feature {
            IntensityFeature::Count => exact_u64_feature(self.count),
            IntensityFeature::FiniteCount => exact_u64_feature(self.finite_count),
            IntensityFeature::Nonfinite => exact_u64_feature(self.nonfinite),
            IntensityFeature::Sum => Some(self.sum),
            IntensityFeature::Mean => self.mean,
            IntensityFeature::Min => self.min,
            IntensityFeature::Max => self.max,
            IntensityFeature::WeightedCentroidZ => {
                self.weighted_centroid.map(|centroid| centroid[0])
            }
            IntensityFeature::WeightedCentroidY => {
                self.weighted_centroid.map(|centroid| centroid[1])
            }
            IntensityFeature::WeightedCentroidX => {
                self.weighted_centroid.map(|centroid| centroid[2])
            }
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
struct HistogramPartialLayout {
    set: DistributionSet,
}

impl HistogramPartialLayout {
    const MAGIC: u64 = 0x6266_6d65_6869_7331;
    const VERSION: u64 = 1;
    const HEADER_WORDS: usize = 6;
    const TALLY_PREFIX_WORDS: usize = 8;

    fn new(set: DistributionSet) -> Self {
        Self { set }
    }

    fn row_words(self) -> Result<usize> {
        Self::TALLY_PREFIX_WORDS
            .checked_add(self.set.bins())
            .ok_or_else(|| Error::invalid("measure distributions: row width overflowed"))
    }

    fn total_words(self, rows: usize) -> Result<usize> {
        Self::HEADER_WORDS
            .checked_add(rows.checked_mul(self.row_words()?).ok_or_else(|| {
                Error::invalid("measure distributions: partial row count overflowed")
            })?)
            .ok_or_else(|| Error::invalid("measure distributions: partial length overflowed"))
    }

    fn capacity(self, rows: usize) -> Result<usize> {
        self.total_words(rows)
    }

    fn push_header(self, words: &mut Vec<u64>, rows: usize) -> Result<()> {
        words.push(Self::MAGIC);
        words.push(Self::VERSION);
        words.push(partial_usize_word(
            self.set.bins(),
            "measure distributions: histogram bin count",
        )?);
        words.push(self.set.min().to_bits());
        words.push(self.set.max().to_bits());
        words.push(partial_usize_word(
            rows,
            "measure distributions: partial row count",
        )?);
        Ok(())
    }

    fn validate_header(self, words: &[u64]) -> Result<usize> {
        Self::validate_prefix(words)?;
        let bins = partial_usize_word(
            self.set.bins(),
            "measure distributions: histogram bin count",
        )?;
        if words[2] != bins
            || words[3] != self.set.min().to_bits()
            || words[4] != self.set.max().to_bits()
        {
            return Err(Error::invalid(
                "measure distributions: partial fragment has the wrong histogram contract",
            ));
        }
        partial_word_usize(words[5], "measure distributions: row count")
    }

    fn encode(self, tallies: &BTreeMap<u64, HistogramTally>) -> Result<Vec<u8>> {
        let mut words = Vec::with_capacity(self.capacity(tallies.len())?);
        self.push_header(&mut words, tallies.len())?;
        for tally in tallies.values() {
            words.push(tally.label);
            words.push(tally.count);
            words.push(tally.nonfinite);
            words.push(tally.underflow);
            words.push(tally.overflow);
            words.extend_from_slice(&tally.position);
            words.extend_from_slice(&tally.bins);
        }
        Ok(pack_u64(&words))
    }

    fn decode(self, bytes: &[u8]) -> Result<Vec<HistogramTally>> {
        let words = unpack_u64(bytes)?;
        let n = self.validate_header(&words)?;
        let row_words = self.row_words()?;
        if words.len() != self.total_words(n)? {
            return Err(Error::invalid(
                "measure distributions: partial fragment length does not match its row count",
            ));
        }
        let mut out = Vec::with_capacity(n);
        for chunk in Self::payload_words(&words)?.chunks_exact(row_words) {
            out.push(HistogramTally {
                label: chunk[0],
                count: chunk[1],
                nonfinite: chunk[2],
                underflow: chunk[3],
                overflow: chunk[4],
                position: [chunk[5], chunk[6], chunk[7]],
                bins: chunk[8..].to_vec(),
            });
        }
        Ok(out)
    }
}

impl PartialLayoutContract for HistogramPartialLayout {
    const MAGIC: u64 = HistogramPartialLayout::MAGIC;
    const VERSION: u64 = HistogramPartialLayout::VERSION;
    const HEADER_WORDS: usize = HistogramPartialLayout::HEADER_WORDS;
    const FORMAT: &'static str = "measure distributions";
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct HistogramTally {
    label: u64,
    count: u64,
    nonfinite: u64,
    underflow: u64,
    overflow: u64,
    position: [u64; 3],
    bins: Vec<u64>,
}

impl HistogramTally {
    fn new(label: u64, bins: usize) -> Self {
        Self {
            label,
            count: 0,
            nonfinite: 0,
            underflow: 0,
            overflow: 0,
            position: [0; 3],
            bins: vec![0; bins],
        }
    }

    fn add(&mut self, at: [usize; 3], value: f64, set: DistributionSet) -> Result<()> {
        self.count = self.count.checked_add(1).ok_or_else(|| {
            Error::invalid("measure distributions: object voxel count overflowed")
        })?;
        for (axis, sum) in self.position.iter_mut().enumerate() {
            let coordinate = usize_coordinate(
                at[axis],
                "measure distributions: object coordinate component",
            )?;
            *sum = sum.checked_add(coordinate).ok_or_else(|| {
                Error::invalid("measure distributions: object coordinate sum overflowed")
            })?;
        }
        if !value.is_finite() {
            self.nonfinite = self.nonfinite.checked_add(1).ok_or_else(|| {
                Error::invalid("measure distributions: non-finite count overflowed")
            })?;
            return Ok(());
        }
        if value < set.min {
            self.underflow = self.underflow.checked_add(1).ok_or_else(|| {
                Error::invalid("measure distributions: underflow count overflowed")
            })?;
            return Ok(());
        }
        if value > set.max {
            self.overflow = self.overflow.checked_add(1).ok_or_else(|| {
                Error::invalid("measure distributions: overflow count overflowed")
            })?;
            return Ok(());
        }
        let bin = distribution_bin_index(value, set)?.ok_or_else(|| {
            Error::invalid("measure distributions: validated in-range value did not map to a bin")
        })?;
        self.bins[bin] = self.bins[bin]
            .checked_add(1)
            .ok_or_else(|| Error::invalid("measure distributions: bin count overflowed"))?;
        Ok(())
    }

    fn merge_exact(&mut self, other: ExactReduction<&Self>) -> Result<()> {
        let other = other.into_inner();
        if self.label != other.label || self.bins.len() != other.bins.len() {
            return Err(Error::invalid(
                "measure distributions: incompatible histogram partials were merged",
            ));
        }
        self.count = self.count.checked_add(other.count).ok_or_else(|| {
            Error::invalid("measure distributions: object voxel count overflowed")
        })?;
        self.nonfinite = self
            .nonfinite
            .checked_add(other.nonfinite)
            .ok_or_else(|| Error::invalid("measure distributions: non-finite count overflowed"))?;
        self.underflow = self
            .underflow
            .checked_add(other.underflow)
            .ok_or_else(|| Error::invalid("measure distributions: underflow count overflowed"))?;
        self.overflow = self
            .overflow
            .checked_add(other.overflow)
            .ok_or_else(|| Error::invalid("measure distributions: overflow count overflowed"))?;
        for axis in 0..3 {
            self.position[axis] = self.position[axis]
                .checked_add(other.position[axis])
                .ok_or_else(|| {
                    Error::invalid("measure distributions: object coordinate sum overflowed")
                })?;
        }
        for (mine, theirs) in self.bins.iter_mut().zip(&other.bins) {
            *mine = mine
                .checked_add(*theirs)
                .ok_or_else(|| Error::invalid("measure distributions: bin count overflowed"))?;
        }
        Ok(())
    }

    fn centroid(&self) -> Option<[usize; 3]> {
        rounded_centroid_coordinate(self.position, self.count)
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct DistributionMeasurements {
    pub label: u64,
    pub at: [usize; 3],
    pub count: u64,
    pub nonfinite: u64,
    pub underflow: u64,
    pub overflow: u64,
    pub set: DistributionSet,
    pub bins: Vec<u64>,
}

/// Validated percentile selector in the inclusive range `[0, 1]`.
#[derive(Debug, Clone, Copy, PartialEq, PartialOrd)]
pub struct DistributionPercentile {
    p: f64,
}

impl DistributionPercentile {
    pub const MIN: Self = Self { p: 0.0 };
    pub const QUARTILE_1: Self = Self { p: 0.25 };
    pub const MEDIAN: Self = Self { p: 0.5 };
    pub const QUARTILE_3: Self = Self { p: 0.75 };
    pub const MAX: Self = Self { p: 1.0 };

    pub fn new(p: f64) -> Result<Self> {
        validate_percentile(p)?;
        Ok(Self { p })
    }

    pub fn get(self) -> f64 {
        self.p
    }

    pub fn column_name(self) -> String {
        format!("percentile_{:.6}", self.p)
    }
}

fn validate_percentile(p: f64) -> Result<()> {
    if !(0.0..=1.0).contains(&p) || !p.is_finite() {
        return Err(Error::invalid(format!(
            "measure distributions: percentile must be finite and in [0, 1], got {p}"
        )));
    }
    Ok(())
}

fn percentile_rank_u64(count: u64, p: f64, what: &'static str) -> Result<u64> {
    validate_percentile(p)?;
    if count == 0 {
        return Err(Error::invalid(format!(
            "{what}: percentile rank needs at least one value"
        )));
    }
    let max_rank = count - 1;
    let rank = (max_rank as f64 * p).round();
    if !rank.is_finite() || rank < 0.0 || rank > max_rank as f64 {
        return Err(Error::invalid(format!(
            "{what}: percentile rank {rank} is outside [0, {max_rank}]"
        )));
    }
    Ok(IntegerF64U64::new(rank, format!("{what}: percentile rank {rank}"))?.get())
}

fn percentile_rank_usize(count: usize, p: f64, what: &'static str) -> Result<usize> {
    let count = usize_count(count, what)?;
    usize::try_from(percentile_rank_u64(count, p, what)?)
        .map_err(|_| Error::invalid(format!("{what}: percentile rank does not fit usize")))
}

/// Derived scalar that can be read from a distribution row.
#[derive(Debug, Clone, Copy, PartialEq, PartialOrd)]
pub enum DistributionFeature {
    InRangeCount,
    Percentile(DistributionPercentile),
    Median,
    Quartile1,
    Quartile3,
    Mean,
    StdDev,
    Mad,
}

impl DistributionFeature {
    pub const SUMMARIES: [Self; 7] = [
        Self::InRangeCount,
        Self::Median,
        Self::Quartile1,
        Self::Quartile3,
        Self::Mean,
        Self::StdDev,
        Self::Mad,
    ];

    pub fn percentile(p: f64) -> Result<Self> {
        Ok(Self::Percentile(DistributionPercentile::new(p)?))
    }

    pub fn column_name(self) -> String {
        match self {
            Self::InRangeCount => "in_range_count".to_string(),
            Self::Percentile(p) => p.column_name(),
            Self::Median => "median".to_string(),
            Self::Quartile1 => "quartile_1".to_string(),
            Self::Quartile3 => "quartile_3".to_string(),
            Self::Mean => "mean".to_string(),
            Self::StdDev => "std_dev".to_string(),
            Self::Mad => "mad".to_string(),
        }
    }
}

impl DistributionMeasurements {
    pub fn in_range_count(&self) -> u64 {
        self.bins.iter().sum()
    }

    pub fn percentile_key(&self, p: DistributionPercentile) -> Result<Option<f64>> {
        let total = self.in_range_count();
        if total == 0 {
            return Ok(None);
        }
        let rank = percentile_rank_u64(total, p.get(), "measure distributions")?;
        let mut seen = 0u64;
        for (bin, count) in self.bins.iter().copied().enumerate() {
            seen = seen
                .checked_add(count)
                .ok_or_else(|| Error::invalid("measure distributions: bin scan overflowed"))?;
            if seen > rank {
                return Ok(Some(self.set.bin_center(bin)));
            }
        }
        Ok(Some(self.set.bin_center(self.bins.len() - 1)))
    }

    pub fn percentile(&self, p: f64) -> Result<Option<f64>> {
        self.percentile_key(DistributionPercentile::new(p)?)
    }

    pub fn median(&self) -> Option<f64> {
        self.percentile_key(DistributionPercentile::MEDIAN)
            .ok()
            .flatten()
    }

    pub fn quartiles(&self) -> Option<[f64; 3]> {
        Some([
            self.percentile_key(DistributionPercentile::QUARTILE_1)
                .ok()
                .flatten()?,
            self.percentile_key(DistributionPercentile::MEDIAN)
                .ok()
                .flatten()?,
            self.percentile_key(DistributionPercentile::QUARTILE_3)
                .ok()
                .flatten()?,
        ])
    }

    pub fn mean(&self) -> Option<f64> {
        let total = self.in_range_count();
        if total == 0 {
            return None;
        }
        let sum = self
            .bins
            .iter()
            .enumerate()
            .map(|(bin, count)| self.set.bin_center(bin) * *count as f64)
            .sum::<f64>();
        Some(sum / total as f64)
    }

    pub fn std_dev(&self) -> Option<f64> {
        let total = self.in_range_count();
        if total == 0 {
            return None;
        }
        let mean = self.mean()?;
        let variance = self
            .bins
            .iter()
            .enumerate()
            .map(|(bin, count)| {
                let delta = self.set.bin_center(bin) - mean;
                delta * delta * *count as f64
            })
            .sum::<f64>()
            / total as f64;
        Some(variance.sqrt())
    }

    pub fn mad(&self) -> Option<f64> {
        let median = self.median()?;
        let total = self.in_range_count();
        if total == 0 {
            return None;
        }
        let mut deviations = self
            .bins
            .iter()
            .enumerate()
            .filter(|&(_, count)| *count > 0)
            .map(|(bin, count)| ((self.set.bin_center(bin) - median).abs(), *count))
            .collect::<Vec<_>>();
        deviations.sort_by(|a, b| a.0.total_cmp(&b.0));
        let rank = (total - 1) / 2;
        let mut seen = 0u64;
        for (deviation, count) in deviations {
            seen += count;
            if seen > rank {
                return Some(deviation);
            }
        }
        Some(0.0)
    }

    pub fn feature(&self, feature: DistributionFeature) -> Result<Option<f64>> {
        Ok(match feature {
            DistributionFeature::InRangeCount => exact_u64_feature(self.in_range_count()),
            DistributionFeature::Percentile(p) => self.percentile_key(p)?,
            DistributionFeature::Median => self.median(),
            DistributionFeature::Quartile1 => {
                self.percentile_key(DistributionPercentile::QUARTILE_1)?
            }
            DistributionFeature::Quartile3 => {
                self.percentile_key(DistributionPercentile::QUARTILE_3)?
            }
            DistributionFeature::Mean => self.mean(),
            DistributionFeature::StdDev => self.std_dev(),
            DistributionFeature::Mad => self.mad(),
        })
    }
}

/// Resident exact per-label distribution with sorted finite samples.
#[derive(Debug, Clone, PartialEq)]
pub struct ExactDistributionMeasurements {
    pub label: u64,
    pub at: [usize; 3],
    pub count: u64,
    pub nonfinite: u64,
    pub values: Vec<f64>,
}

impl ExactDistributionMeasurements {
    pub fn finite_count(&self) -> Result<u64> {
        usize_count(
            self.values.len(),
            "measure exact distributions: finite_count",
        )
    }

    pub fn percentile_key(&self, p: DistributionPercentile) -> Result<Option<f64>> {
        if self.values.is_empty() {
            return Ok(None);
        }
        let rank =
            percentile_rank_usize(self.values.len(), p.get(), "measure exact distributions")?;
        Ok(Some(self.values[rank]))
    }

    pub fn percentile(&self, p: f64) -> Result<Option<f64>> {
        self.percentile_key(DistributionPercentile::new(p)?)
    }

    pub fn median(&self) -> Option<f64> {
        self.percentile_key(DistributionPercentile::MEDIAN)
            .ok()
            .flatten()
    }

    pub fn quartiles(&self) -> Option<[f64; 3]> {
        Some([
            self.percentile_key(DistributionPercentile::QUARTILE_1)
                .ok()
                .flatten()?,
            self.percentile_key(DistributionPercentile::MEDIAN)
                .ok()
                .flatten()?,
            self.percentile_key(DistributionPercentile::QUARTILE_3)
                .ok()
                .flatten()?,
        ])
    }

    pub fn mean(&self) -> Option<f64> {
        if self.values.is_empty() {
            return None;
        }
        Some(self.values.iter().sum::<f64>() / self.values.len() as f64)
    }

    pub fn std_dev(&self) -> Option<f64> {
        if self.values.is_empty() {
            return None;
        }
        let mean = self.mean()?;
        let variance = self
            .values
            .iter()
            .map(|value| {
                let delta = *value - mean;
                delta * delta
            })
            .sum::<f64>()
            / self.values.len() as f64;
        Some(variance.sqrt())
    }

    pub fn mad(&self) -> Option<f64> {
        let median = self.median()?;
        let mut deviations: Vec<f64> = self
            .values
            .iter()
            .map(|value| (*value - median).abs())
            .collect();
        deviations.sort_by(f64::total_cmp);
        let rank =
            percentile_rank_usize(deviations.len(), 0.5, "measure exact distributions").ok()?;
        Some(deviations[rank])
    }

    pub fn feature(&self, feature: DistributionFeature) -> Result<Option<f64>> {
        Ok(match feature {
            DistributionFeature::InRangeCount => exact_u64_feature(self.finite_count()?),
            DistributionFeature::Percentile(p) => self.percentile_key(p)?,
            DistributionFeature::Median => self.median(),
            DistributionFeature::Quartile1 => {
                self.percentile_key(DistributionPercentile::QUARTILE_1)?
            }
            DistributionFeature::Quartile3 => {
                self.percentile_key(DistributionPercentile::QUARTILE_3)?
            }
            DistributionFeature::Mean => self.mean(),
            DistributionFeature::StdDev => self.std_dev(),
            DistributionFeature::Mad => self.mad(),
        })
    }
}

fn validate_exact_distribution_row(
    row: &ExactDistributionMeasurements,
    set: ExactDistributionSet,
) -> Result<()> {
    let max_values = set.max_values();
    if row.label == 0 {
        return Err(Error::invalid(
            "measure exact distributions: row has background label 0",
        ));
    }
    if row.count == 0 {
        return Err(Error::invalid(format!(
            "measure exact distributions: row for label {} has zero count",
            row.label
        )));
    }
    if row.values.len() > max_values {
        return Err(Error::invalid(format!(
            "measure exact distributions: row for label {} has {} finite values, maximum is {}",
            row.label,
            row.values.len(),
            max_values
        )));
    }
    let finite_count = u64::try_from(row.values.len()).map_err(|_| {
        Error::invalid("measure exact distributions: finite value count does not fit in u64")
    })?;
    if finite_count
        .checked_add(row.nonfinite)
        .ok_or_else(|| Error::invalid("measure exact distributions: row count overflowed"))?
        != row.count
    {
        return Err(Error::invalid(format!(
            "measure exact distributions: row for label {} has count {}, nonfinite {} and {} \
             finite values",
            row.label,
            row.count,
            row.nonfinite,
            row.values.len()
        )));
    }
    for (index, &value) in row.values.iter().enumerate() {
        if !value.is_finite() {
            return Err(Error::invalid(format!(
                "measure exact distributions: row for label {} has non-finite value at index \
                 {index}",
                row.label
            )));
        }
        if index > 0 && row.values[index - 1].total_cmp(&value).is_gt() {
            return Err(Error::invalid(format!(
                "measure exact distributions: row for label {} has unsorted finite values",
                row.label
            )));
        }
    }
    Ok(())
}

