#[derive(Debug, Clone, Copy, PartialEq)]
#[repr(transparent)]
struct PhysicalPoint3([f64; 3]);

#[derive(Debug, Clone, Copy, PartialEq)]
struct PhysicalVoxelFrame3 {
    spacing: PhysicalSpacing,
}

impl PhysicalVoxelFrame3 {
    fn new(spacing: PhysicalSpacing) -> Self {
        Self { spacing }
    }

    fn spacing_axes(self) -> [f64; 3] {
        self.spacing.axes()
    }

    fn voxel_center(self, point: VoxelIndex3) -> PhysicalPoint3 {
        let point = point.coords();
        let spacing = self.spacing_axes();
        PhysicalPoint3([
            point[0] as f64 * spacing[0],
            point[1] as f64 * spacing[1],
            point[2] as f64 * spacing[2],
        ])
    }

    fn fractional_voxel_center(self, point: [f64; 3]) -> PhysicalPoint3 {
        let spacing = self.spacing_axes();
        PhysicalPoint3([
            point[0] * spacing[0],
            point[1] * spacing[1],
            point[2] * spacing[2],
        ])
    }

    fn bbox_extent(self, min: VoxelIndex3, max: VoxelIndex3) -> PhysicalExtent3 {
        let min = min.coords();
        let max = max.coords();
        let spacing = self.spacing_axes();
        PhysicalExtent3([
            (max[0] - min[0]) as f64 * spacing[0],
            (max[1] - min[1]) as f64 * spacing[1],
            (max[2] - min[2]) as f64 * spacing[2],
        ])
    }

    fn delta(self, from: VoxelIndex3, to: VoxelIndex3) -> PhysicalVector3 {
        self.voxel_center(from).delta_to(self.voxel_center(to))
    }
}

impl PhysicalPoint3 {
    fn from_fractional_voxel_center(point: [f64; 3], spacing: PhysicalSpacing) -> Self {
        PhysicalVoxelFrame3::new(spacing).fractional_voxel_center(point)
    }

    fn delta_to(self, other: Self) -> PhysicalVector3 {
        PhysicalVector3::between(self, other)
    }

    fn midpoint(self, other: Self) -> Self {
        let a = self.coords();
        let b = other.coords();
        Self([
            0.5 * (a[0] + b[0]),
            0.5 * (a[1] + b[1]),
            0.5 * (a[2] + b[2]),
        ])
    }

    fn translate(self, vector: PhysicalVector3) -> Self {
        let point = self.coords();
        let vector = vector.coords();
        Self([
            point[0] + vector[0],
            point[1] + vector[1],
            point[2] + vector[2],
        ])
    }

    fn squared_distance(self, other: Self) -> f64 {
        self.delta_to(other).squared_norm()
    }

    fn dot_origin(self) -> f64 {
        let point = self.coords();
        point[0] * point[0] + point[1] * point[1] + point[2] * point[2]
    }

    fn centroid(points: NonEmptySlice<'_, Self>) -> Self {
        let mut sum = [0.0; 3];
        for point in points.slice() {
            let point = point.coords();
            for axis in 0..3 {
                sum[axis] += point[axis];
            }
        }
        let count = points.slice().len() as f64;
        Self([sum[0] / count, sum[1] / count, sum[2] / count])
    }

    fn coords(self) -> [f64; 3] {
        self.0
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
#[repr(transparent)]
struct PhysicalExtent3([f64; 3]);

impl PhysicalExtent3 {
    fn axes(self) -> [f64; 3] {
        self.0
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
#[repr(transparent)]
struct PhysicalVector3([f64; 3]);

impl PhysicalVector3 {
    fn unit_z() -> Self {
        Self([0.0, 0.0, 1.0])
    }

    fn between(a: PhysicalPoint3, b: PhysicalPoint3) -> Self {
        let a = a.coords();
        let b = b.coords();
        Self([b[0] - a[0], b[1] - a[1], b[2] - a[2]])
    }

    fn from_finite_coords(coords: [f64; 3], context: impl FnOnce() -> String) -> Result<Self> {
        for (axis, value) in coords.iter().enumerate() {
            if !value.is_finite() {
                return Err(Error::invalid(format!(
                    "{} has non-finite physical delta {value} on axis {axis}",
                    context()
                )));
            }
        }
        Ok(Self(coords))
    }

    fn coords(self) -> [f64; 3] {
        self.0
    }

    fn add(self, other: Self) -> Self {
        let a = self.coords();
        let b = other.coords();
        Self([a[0] + b[0], a[1] + b[1], a[2] + b[2]])
    }

    fn scale(self, factor: f64) -> Self {
        let a = self.coords();
        Self([a[0] * factor, a[1] * factor, a[2] * factor])
    }

    fn negate(self) -> Self {
        self.scale(-1.0)
    }

    fn cross(self, other: Self) -> Self {
        let a = self.coords();
        let b = other.coords();
        Self([
            a[1] * b[2] - a[2] * b[1],
            a[2] * b[0] - a[0] * b[2],
            a[0] * b[1] - a[1] * b[0],
        ])
    }

    fn dot(self, other: Self) -> f64 {
        let a = self.coords();
        let b = other.coords();
        a[0] * b[0] + a[1] * b[1] + a[2] * b[2]
    }

    fn squared_norm(self) -> f64 {
        self.dot(self)
    }

    fn norm(self) -> f64 {
        self.squared_norm().sqrt()
    }

    fn angle_to(self, other: Self) -> Option<f64> {
        let denom = self.norm() * other.norm();
        if denom == 0.0 {
            return None;
        }
        Some((self.dot(other) / denom).clamp(-1.0, 1.0).acos())
    }

    fn max_abs_axis(self) -> usize {
        let vector = self.coords();
        if vector[0].abs() >= vector[1].abs() && vector[0].abs() >= vector[2].abs() {
            0
        } else if vector[1].abs() >= vector[2].abs() {
            1
        } else {
            2
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
#[repr(transparent)]
struct PhysicalRadius(f64);

impl PhysicalRadius {
    fn new(radius: f64) -> Result<Self> {
        if !radius.is_finite() || radius < 0.0 {
            return Err(Error::invalid(format!(
                "measure geometry: physical radius must be finite and non-negative, got {radius}"
            )));
        }
        Ok(Self(radius))
    }

    fn from_squared_distance(squared: f64) -> Result<Self> {
        if !squared.is_finite() || squared < -1.0e-12 {
            return Err(Error::invalid(format!(
                "measure geometry: squared physical radius must be finite and non-negative, got \
                 {squared}"
            )));
        }
        Self::new(squared.max(0.0).sqrt())
    }

    fn from_sphere_volume(volume: PhysicalVolume) -> Self {
        if !volume.is_positive() {
            return Self(0.0);
        }
        Self((3.0 * volume.get() / (4.0 * std::f64::consts::PI)).cbrt())
    }

    fn diameter(self) -> f64 {
        2.0 * self.get()
    }

    fn get(self) -> f64 {
        self.0
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
#[repr(transparent)]
struct PhysicalPoint2([f64; 2]);

#[derive(Debug, Clone, Copy, PartialEq)]
#[repr(transparent)]
struct ProjectedSpacing2([f64; 2]);

impl ProjectedSpacing2 {
    fn unit() -> Self {
        Self([1.0; 2])
    }

    fn axes(self) -> [f64; 2] {
        self.0
    }

    fn pixel_area(self) -> f64 {
        let axes = self.axes();
        axes[0] * axes[1]
    }
}

impl PhysicalPoint2 {
    fn from_projected_voxel_center(
        point: ProjectedVoxelIndex2,
        spacing: ProjectedSpacing2,
    ) -> Self {
        let point = point.coords();
        let spacing = spacing.axes();
        Self([point[0] as f64 * spacing[0], point[1] as f64 * spacing[1]])
    }

    fn from_projected_footprint_corner(
        center: ProjectedVoxelIndex2,
        spacing: ProjectedSpacing2,
        signs: [f64; 2],
    ) -> Self {
        let center = Self::from_projected_voxel_center(center, spacing).coords();
        let spacing = spacing.axes();
        let half = [0.5 * spacing[0], 0.5 * spacing[1]];
        Self([
            center[0] + signs[0] * half[0],
            center[1] + signs[1] * half[1],
        ])
    }

    fn coords(self) -> [f64; 2] {
        self.0
    }

    fn centroid(points: NonEmptySlice<'_, Self>) -> Self {
        let mut sum = [0.0, 0.0];
        for point in points.slice() {
            let point = point.coords();
            sum[0] += point[0];
            sum[1] += point[1];
        }
        let count = points.slice().len() as f64;
        Self([sum[0] / count, sum[1] / count])
    }

    fn distance_to(self, other: Self) -> f64 {
        let [ay, ax] = self.coords();
        let [by, bx] = other.coords();
        (ay - by).hypot(ax - bx)
    }
}

#[derive(Debug, Clone, PartialEq)]
struct ObjectPointSet {
    label: u64,
    points: Vec<[usize; 3]>,
    bbox_min: [usize; 3],
    bbox_max: [usize; 3],
}

impl ObjectPointSet {
    fn new(label: u64) -> Self {
        Self {
            label,
            points: Vec::new(),
            bbox_min: [usize::MAX; 3],
            bbox_max: [0; 3],
        }
    }

    fn add(&mut self, at: [usize; 3]) {
        self.points.push(at);
        for (axis, coordinate) in at.into_iter().enumerate() {
            self.bbox_min[axis] = self.bbox_min[axis].min(coordinate);
            self.bbox_max[axis] = self.bbox_max[axis].max(coordinate + 1);
        }
    }

    fn merge_exact(&mut self, from: ExactReduction<Self>) -> Result<()> {
        let from = from.into_inner();
        if self.label != from.label {
            return Err(Error::invalid(format!(
                "measure object points: cannot merge label {} into label {}",
                from.label, self.label
            )));
        }
        self.points.extend(from.points);
        for axis in 0..3 {
            self.bbox_min[axis] = self.bbox_min[axis].min(from.bbox_min[axis]);
            self.bbox_max[axis] = self.bbox_max[axis].max(from.bbox_max[axis]);
        }
        Ok(())
    }

    fn is_owned_by(&self, grid: &BlockGrid, block: [usize; 3]) -> bool {
        !self.points.is_empty() && owner_of(grid, self.bbox_min) == block
    }

    fn physical_bbox_extent(&self, spacing: PhysicalSpacing) -> [f64; 3] {
        PhysicalVoxelFrame3::new(spacing)
            .bbox_extent(
                VoxelIndex3::new(self.bbox_min),
                VoxelIndex3::new(self.bbox_max),
            )
            .axes()
    }

    fn max_voxel_feret_diameter(&self, spacing: PhysicalSpacing) -> f64 {
        let frame = PhysicalVoxelFrame3::new(spacing);
        let mut max_squared = 0.0f64;
        for (index, a) in self.points.iter().enumerate() {
            let a = frame.voxel_center(VoxelIndex3::new(*a));
            for b in &self.points[index + 1..] {
                let b = frame.voxel_center(VoxelIndex3::new(*b));
                max_squared = max_squared.max(a.squared_distance(b));
            }
        }
        max_squared.sqrt()
    }

    fn physical_centroid(&self, spacing: PhysicalSpacing) -> PhysicalPoint3 {
        let count = self.points.len() as f64;
        let mut sum = [0.0; 3];
        let frame = PhysicalVoxelFrame3::new(spacing);
        for point in &self.points {
            let point = frame.voxel_center(VoxelIndex3::new(*point)).coords();
            for axis in 0..3 {
                sum[axis] += point[axis];
            }
        }
        PhysicalPoint3([sum[0] / count, sum[1] / count, sum[2] / count])
    }

    fn physical_points(&self, spacing: PhysicalSpacing) -> Vec<PhysicalPoint3> {
        let frame = PhysicalVoxelFrame3::new(spacing);
        self.points
            .iter()
            .map(|point| frame.voxel_center(VoxelIndex3::new(*point)))
            .collect()
    }

    fn physical_voxel_face_points(&self, spacing: PhysicalSpacing) -> Vec<PhysicalPoint3> {
        let axes = spacing.axes();
        let mut seen = BTreeSet::<[u64; 3]>::new();
        let mut points = Vec::new();
        for point in &self.points {
            for dz in [-0.5, 0.5] {
                for dy in [-0.5, 0.5] {
                    for dx in [-0.5, 0.5] {
                        let physical = [
                            (point[0] as f64 + dz) * axes[0],
                            (point[1] as f64 + dy) * axes[1],
                            (point[2] as f64 + dx) * axes[2],
                        ];
                        let key = physical.map(f64::to_bits);
                        if seen.insert(key) {
                            points.push(PhysicalPoint3(physical));
                        }
                    }
                }
            }
        }
        points
    }
}

#[derive(Debug, Clone, Copy)]
struct NonEmptySlice<'a, T> {
    values: &'a [T],
}

impl<'a, T> NonEmptySlice<'a, T> {
    fn new(values: &'a [T]) -> Option<Self> {
        (!values.is_empty()).then_some(Self { values })
    }

    fn slice(self) -> &'a [T] {
        self.values
    }
}

