#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct BoundaryContactFact {
    at: [usize; 3],
    label: u64,
    neighbour: u64,
    face_or_offset: [isize; 3],
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct BoundaryContactPartialLayout;

impl BoundaryContactPartialLayout {
    const MAGIC: u64 = 0x4246_4d45_4243_5431;
    const VERSION: u64 = 1;
    const HEADER_WORDS: usize = 3;
    const CONTACT_WORDS: usize = 8;

    fn encode(contacts: &[BoundaryContactFact]) -> Result<Vec<u8>> {
        let contact_words = contacts
            .len()
            .checked_mul(Self::CONTACT_WORDS)
            .ok_or_else(|| {
                Error::invalid("measure custom boundary: contact partial length overflow")
            })?;
        let capacity = Self::HEADER_WORDS
            .checked_add(contact_words)
            .ok_or_else(|| Error::invalid("measure custom boundary: contact partial overflow"))?;
        let mut words = Vec::with_capacity(capacity);
        words.push(Self::MAGIC);
        words.push(Self::VERSION);
        words.push(partial_usize_word(
            contacts.len(),
            "measure custom boundary: contact count",
        )?);
        for contact in contacts {
            words.push(contact.label);
            words.push(contact.neighbour);
            push_partial_point3(
                &mut words,
                contact.at,
                "measure custom boundary: contact coordinate",
            )?;
            for value in contact.face_or_offset {
                words.push(offset_word(value)?);
            }
        }
        Ok(pack_u64(&words))
    }

    fn decode(bytes: &[u8]) -> Result<Vec<BoundaryContactFact>> {
        let words = unpack_u64(bytes)?;
        Self::validate_prefix(&words)?;
        let count = partial_word_usize(words[2], "measure custom boundary: contact count")?;
        let expected = Self::HEADER_WORDS
            .checked_add(count.checked_mul(Self::CONTACT_WORDS).ok_or_else(|| {
                Error::invalid("measure custom boundary: contact partial length overflow")
            })?)
            .ok_or_else(|| Error::invalid("measure custom boundary: contact partial overflow"))?;
        if words.len() != expected {
            return Err(Error::invalid(
                "measure custom boundary: contact partial length does not match header",
            ));
        }
        let mut contacts = Vec::with_capacity(count);
        for chunk in words[Self::HEADER_WORDS..].chunks_exact(Self::CONTACT_WORDS) {
            let label = chunk[0];
            if label == 0 {
                return Err(Error::invalid(
                    "measure custom boundary: contact partial contains background label 0",
                ));
            }
            let at = partial_point3(&chunk[2..5], "measure custom boundary: contact coordinate")?;
            contacts.push(BoundaryContactFact {
                at,
                label,
                neighbour: chunk[1],
                face_or_offset: [
                    offset_from_word(chunk[5])?,
                    offset_from_word(chunk[6])?,
                    offset_from_word(chunk[7])?,
                ],
            });
        }
        Ok(contacts)
    }
}

impl PartialLayoutContract for BoundaryContactPartialLayout {
    const MAGIC: u64 = BoundaryContactPartialLayout::MAGIC;
    const VERSION: u64 = BoundaryContactPartialLayout::VERSION;
    const HEADER_WORDS: usize = BoundaryContactPartialLayout::HEADER_WORDS;
    const FORMAT: &'static str = "measure custom boundary contact partial";
}

fn offset_word(value: isize) -> Result<u64> {
    let value = i64::try_from(value)
        .map_err(|_| Error::invalid("measure custom boundary: offset does not fit i64"))?;
    Ok(u64::from_ne_bytes(value.to_ne_bytes()))
}

fn offset_from_word(value: u64) -> Result<isize> {
    let value = i64::from_ne_bytes(value.to_ne_bytes());
    isize::try_from(value)
        .map_err(|_| Error::invalid("measure custom boundary: offset does not fit isize"))
}

fn fold_boundary_contact_partials<'a>(
    partials: impl IntoIterator<Item = &'a [u8]>,
) -> Result<BTreeMap<u64, Vec<BoundaryContactFact>>> {
    let mut totals = BTreeMap::<u64, Vec<BoundaryContactFact>>::new();
    for bytes in partials {
        for contact in BoundaryContactPartialLayout::decode(bytes)? {
            totals.entry(contact.label).or_default().push(contact);
        }
    }
    Ok(totals)
}

fn stream_fragment_bytes(at: &BlockView<'_>, input: &str) -> Result<Vec<Vec<u8>>> {
    let mut partials = Vec::new();
    at.stream_fragments(input, &mut |_, bytes| {
        partials.push(bytes.to_vec());
        Ok(())
    })?;
    Ok(partials)
}

