/// Merge object-point partials into 3-D moment rows.
#[derive(Debug, Clone)]
pub struct MergeObjectMoment3dOp {
    name: &'static str,
    input: PartialPhaseInput,
    spacing: PhysicalSpacing,
    set: ObjectMoment3dSet,
    schema: Arc<Schema>,
    stream: String,
    lifecycle: Lifecycle,
}

impl MergeObjectMoment3dOp {
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        name: &'static str,
        input: impl Into<String>,
        input_phase: usize,
        lattice: [usize; 3],
        spacing: PhysicalSpacing,
        max_order: usize,
        stream: impl Into<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        Self::new_set(
            name,
            input,
            input_phase,
            lattice,
            spacing,
            ObjectMoment3dSet::new(max_order)?,
            stream,
            lifecycle,
        )
    }

    #[allow(clippy::too_many_arguments)]
    pub fn new_set(
        name: &'static str,
        input: impl Into<String>,
        input_phase: usize,
        lattice: [usize; 3],
        spacing: PhysicalSpacing,
        set: ObjectMoment3dSet,
        stream: impl Into<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        let input = ObjectPointPartialStream::new(input)?;
        let stream = ObjectMoment3dOutputStream::new(stream)?;
        let schema = Arc::new(object_3d_moment_measurement_schema_set(set)?);
        Ok(Self {
            name,
            input: PartialPhaseInput::try_new(&input, input_phase, lattice)?,
            spacing,
            set,
            schema,
            stream: stream.as_str().to_string(),
            lifecycle,
        })
    }

    fn encode_owned(
        &self,
        objects: &BTreeMap<u64, ObjectPointSet>,
        grid: &BlockGrid,
        block: [usize; 3],
    ) -> Result<Vec<u8>> {
        let max_order = self.set.max_order();
        let mut rows = RowBuilder::new(Arc::clone(&self.schema));
        let orders = moment_3d_orders(self.set);
        for object in objects.values() {
            if !object.is_owned_by(grid, block) {
                continue;
            }
            let points = object.physical_points(self.spacing);
            let centroid = object.physical_centroid(self.spacing);
            let mass = points.len() as f64;
            let moments = orders
                .iter()
                .copied()
                .map(|order| {
                    let central = central_moment_3d(&points, centroid, order);
                    let total_order = order.total_order();
                    let gamma = 1.0 + total_order as f64 / 3.0;
                    Moment3d {
                        order: order.get(),
                        central,
                        normalized: central / mass.powf(gamma),
                    }
                })
                .collect();
            let row = ObjectMoment3dMeasurements {
                label: object.label,
                count: usize_count(points.len(), "measure moments: count")?,
                centroid: centroid.coords(),
                max_order,
                moments,
            };
            validate_object_3d_moment_row(&row, self.set)?;
            rows.push(object.bbox_min, &Moment3dColumns::values(&row)?)?;
        }
        Ok(rows.encode())
    }
}

