/// Merge object-point partials into projected convex geometry rows.
#[derive(Debug, Clone)]
pub struct MergeObjectProjectedConvexOp {
    name: &'static str,
    input: PartialPhaseInput,
    spacing: PhysicalSpacing,
    projection_axis: ProjectionAxis,
    set: ProjectedConvexSet,
    schema: Arc<Schema>,
    stream: String,
    lifecycle: Lifecycle,
}

impl MergeObjectProjectedConvexOp {
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        name: &'static str,
        input: impl Into<String>,
        input_phase: usize,
        lattice: [usize; 3],
        spacing: PhysicalSpacing,
        projection_axis: ProjectionAxis,
        max_hull_vertices: usize,
        stream: impl Into<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        Self::new_set(
            name,
            input,
            input_phase,
            lattice,
            spacing,
            projection_axis,
            ProjectedConvexSet::new(max_hull_vertices)?,
            stream,
            lifecycle,
        )
    }

    #[allow(clippy::too_many_arguments)]
    pub fn new_set(
        name: &'static str,
        input: impl Into<String>,
        input_phase: usize,
        lattice: [usize; 3],
        spacing: PhysicalSpacing,
        projection_axis: ProjectionAxis,
        set: ProjectedConvexSet,
        stream: impl Into<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        let input = ObjectPointPartialStream::new(input)?;
        let stream = ProjectedConvexOutputStream::new(stream)?;
        let schema = Arc::new(object_projected_convex_measurement_schema_set(set));
        Ok(Self {
            name,
            input: PartialPhaseInput::try_new(&input, input_phase, lattice)?,
            spacing,
            projection_axis,
            set,
            schema,
            stream: stream.as_str().to_string(),
            lifecycle,
        })
    }

    fn encode_owned(
        &self,
        objects: &BTreeMap<u64, ObjectPointSet>,
        grid: &BlockGrid,
        block: [usize; 3],
    ) -> Result<Vec<u8>> {
        let mut rows = RowBuilder::new(Arc::clone(&self.schema));
        let projected_spacing = self.projection_axis.projected_spacing(self.spacing);
        let pixel_area = projected_spacing.pixel_area();
        for object in objects.values() {
            if !object.is_owned_by(grid, block) {
                continue;
            }
            let projected = projected_voxel_indices(&object.points, self.projection_axis);
            let centers = projected
                .iter()
                .map(|&point| PhysicalPoint2::from_projected_voxel_center(point, projected_spacing))
                .collect::<Vec<_>>();
            let footprint_points =
                projected_footprint_corners(projected.iter().copied(), projected_spacing);
            let hull_vertices = convex_hull_2d(footprint_points);
            let convex_hull_area = polygon_area(&hull_vertices);
            let max_projected_feret_diameter = max_pairwise_distance_2d(&hull_vertices);
            let projected_area = projected.len() as f64 * pixel_area;
            let solidity = (convex_hull_area > 0.0).then_some(projected_area / convex_hull_area);
            let centers = NonEmptySlice::new(&centers)
                .ok_or_else(|| Error::invalid("measure projected convex: object has no points"))?;
            let circle = minimum_enclosing_circle(centers);
            let radius = PhysicalRadius::from_squared_distance(circle.radius_squared)?.get();
            let row = ObjectProjectedConvexMeasurements {
                label: object.label,
                projected_count: usize_count(
                    projected.len(),
                    "measure projected convex: projected_count",
                )?,
                projection_axis: self.projection_axis,
                projected_area,
                convex_hull_area,
                solidity,
                hull_vertices: hull_vertices
                    .into_iter()
                    .map(PhysicalPoint2::coords)
                    .collect(),
                max_projected_feret_diameter,
                min_enclosing_circle_center: circle.center.coords(),
                min_enclosing_circle_radius: radius,
                min_enclosing_circle_support_points: circle.support_points,
            };
            validate_object_projected_convex_row(&row, self.set)?;
            rows.push(
                object.bbox_min,
                &ProjectedConvexColumns::values(&row, self.set)?,
            )?;
        }
        Ok(rows.encode())
    }
}

