/// Merge object-point partials into projected binary Zernike moment rows.
#[derive(Debug, Clone)]
pub struct MergeObjectZernikeMomentsOp {
    name: &'static str,
    input: PartialPhaseInput,
    projection_axis: ProjectionAxis,
    set: ObjectZernikeMomentSet,
    schema: Arc<Schema>,
    stream: String,
    lifecycle: Lifecycle,
}

impl MergeObjectZernikeMomentsOp {
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        name: &'static str,
        input: impl Into<String>,
        input_phase: usize,
        lattice: [usize; 3],
        projection_axis: ProjectionAxis,
        max_order: usize,
        stream: impl Into<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        Self::new_set(
            name,
            input,
            input_phase,
            lattice,
            projection_axis,
            ObjectZernikeMomentSet::new(max_order)?,
            stream,
            lifecycle,
        )
    }

    #[allow(clippy::too_many_arguments)]
    pub fn new_set(
        name: &'static str,
        input: impl Into<String>,
        input_phase: usize,
        lattice: [usize; 3],
        projection_axis: ProjectionAxis,
        set: ObjectZernikeMomentSet,
        stream: impl Into<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        let input = ObjectPointPartialStream::new(input)?;
        let stream = ZernikeMomentOutputStream::new(stream)?;
        let schema = Arc::new(object_zernike_moment_measurement_schema_set(set)?);
        Ok(Self {
            name,
            input: PartialPhaseInput::try_new(&input, input_phase, lattice)?,
            projection_axis,
            set,
            schema,
            stream: stream.as_str().to_string(),
            lifecycle,
        })
    }

    fn encode_owned(
        &self,
        objects: &BTreeMap<u64, ObjectPointSet>,
        grid: &BlockGrid,
        block: [usize; 3],
    ) -> Result<Vec<u8>> {
        let max_order = self.set.max_order();
        let mut rows = RowBuilder::new(Arc::clone(&self.schema));
        let orders = zernike_orders(max_order);
        for object in objects.values() {
            if !object.is_owned_by(grid, block) {
                continue;
            }
            let (points, centroid) = projected_voxel_centers_with_centroid(
                &object.points,
                self.projection_axis,
                "merge Zernike moments",
            )?;
            let radius = points
                .iter()
                .map(|point| point.distance_to(centroid))
                .fold(0.0, f64::max);
            let moments = orders
                .iter()
                .map(|&(order, repetition)| {
                    zernike_moment(&points, centroid, radius, order, repetition)
                })
                .collect::<Result<Vec<_>>>()?;
            let row = ObjectZernikeMomentsMeasurements {
                label: object.label,
                projected_count: usize_count(
                    points.len(),
                    "measure Zernike moments: projected_count",
                )?,
                projection_axis: self.projection_axis,
                max_order,
                centroid: centroid.coords(),
                radius,
                moments,
            };
            validate_object_zernike_moment_row(&row, self.set)?;
            rows.push(object.bbox_min, &ZernikeMomentColumns::values(&row)?)?;
        }
        Ok(rows.encode())
    }
}

