#[derive(Debug, Clone, Copy, PartialEq)]
struct WeightedHuSample {
    at: [usize; 3],
    weight: f64,
}

#[derive(Debug, Clone, Default, PartialEq)]
struct WeightedHuPointPartial {
    owner_at: Option<[usize; 3]>,
    finite_weight_count: u64,
    nonfinite_weight_count: u64,
    samples: Vec<WeightedHuSample>,
}

impl WeightedHuPointPartial {
    fn merge_exact(&mut self, from: ExactReduction<Self>) -> Result<()> {
        let from = from.into_inner();
        self.finite_weight_count = self
            .finite_weight_count
            .checked_add(from.finite_weight_count)
            .ok_or_else(|| {
                Error::invalid("measure weighted Hu moments: finite weight count overflow")
            })?;
        self.nonfinite_weight_count = self
            .nonfinite_weight_count
            .checked_add(from.nonfinite_weight_count)
            .ok_or_else(|| {
                Error::invalid("measure weighted Hu moments: nonfinite weight count overflow")
            })?;
        checked_partial_merged_len(
            self.samples.len(),
            from.samples.len(),
            "measure weighted Hu moments: point partial sample count",
        )?;
        self.samples.extend(from.samples);
        self.owner_at = match (self.owner_at, from.owner_at) {
            (Some(a), Some(b)) => Some(a.min(b)),
            (Some(a), None) => Some(a),
            (None, Some(b)) => Some(b),
            (None, None) => None,
        };
        Ok(())
    }
}

struct WeightedHuPointPartialLayout;

impl WeightedHuPointPartialLayout {
    const MAGIC: u64 = 0x4246_4d45_5748_5031;
    const VERSION: u64 = 1;
    const HEADER_WORDS: usize = 4;
    const FIXED_ROW_WORDS: usize = 8;
    const SAMPLE_WORDS: usize = 4;

    fn encode(points: &BTreeMap<u64, WeightedHuPointPartial>) -> Result<Vec<u8>> {
        let sample_count = checked_partial_item_count(
            points.values().map(|partial| partial.samples.len()),
            "measure weighted Hu moments: point partial",
        )?;
        let mut words = Vec::with_capacity(variable_partial_capacity(
            Self::HEADER_WORDS,
            points.len(),
            Self::FIXED_ROW_WORDS,
            sample_count,
            Self::SAMPLE_WORDS,
            "measure weighted Hu moments: point partial",
        )?);
        words.push(Self::MAGIC);
        words.push(Self::VERSION);
        words.push(partial_usize_word(
            points.len(),
            "measure weighted Hu moments: point partial label count",
        )?);
        words.push(partial_usize_word(
            sample_count,
            "measure weighted Hu moments: point partial sample count",
        )?);
        for (&label, partial) in points {
            words.push(label);
            match partial.owner_at {
                Some(owner_at) => {
                    words.push(1);
                    push_partial_point3(
                        &mut words,
                        owner_at,
                        "measure weighted Hu moments: point partial owner coordinate",
                    )?;
                }
                None => {
                    words.push(0);
                    words.extend([0; 3]);
                }
            }
            words.push(partial.finite_weight_count);
            words.push(partial.nonfinite_weight_count);
            words.push(partial_usize_word(
                partial.samples.len(),
                "measure weighted Hu moments: point partial label sample count",
            )?);
            for sample in &partial.samples {
                push_partial_point3(
                    &mut words,
                    sample.at,
                    "measure weighted Hu moments: point partial sample coordinate",
                )?;
                words.push(sample.weight.to_bits());
            }
        }
        Ok(pack_u64(&words))
    }

    fn decode(bytes: &[u8]) -> Result<Vec<(u64, WeightedHuPointPartial)>> {
        let words = unpack_u64(bytes)?;
        Self::validate_prefix(&words)?;
        let label_count = partial_word_usize(
            words[2],
            "measure weighted Hu moments: point partial label count",
        )?;
        let declared_sample_count = partial_word_usize(
            words[3],
            "measure weighted Hu moments: point partial sample count",
        )?;
        let mut offset = Self::HEADER_WORDS;
        let mut decoded = Vec::with_capacity(label_count);
        let mut seen_samples = 0usize;
        for _ in 0..label_count {
            if words.len().saturating_sub(offset) < Self::FIXED_ROW_WORDS {
                return Err(Error::invalid(
                    "measure weighted Hu moments: point partial label row is truncated",
                ));
            }
            let label = words[offset];
            if label == 0 {
                return Err(Error::invalid(
                    "measure weighted Hu moments: point partial contains background label 0",
                ));
            }
            let owner_at = match words[offset + 1] {
                0 => None,
                1 => Some(partial_point3(
                    &words[offset + 2..offset + 5],
                    "measure weighted Hu moments: point partial owner coordinate",
                )?),
                other => {
                    return Err(Error::invalid(format!(
                        "measure weighted Hu moments: point partial owner flag must be 0 or 1, got \
                         {other}"
                    )));
                }
            };
            let finite_weight_count = words[offset + 5];
            let nonfinite_weight_count = words[offset + 6];
            let sample_count = partial_word_usize(
                words[offset + 7],
                "measure weighted Hu moments: point partial sample count",
            )?;
            offset += Self::FIXED_ROW_WORDS;
            let sample_range = checked_variable_partial_section(
                &words,
                offset,
                sample_count,
                Self::SAMPLE_WORDS,
                "measure weighted Hu moments: point partial sample section",
            )?;
            let mut samples = Vec::with_capacity(sample_count);
            for sample in words[sample_range.clone()].chunks_exact(Self::SAMPLE_WORDS) {
                let weight = f64::from_bits(sample[3]);
                if !weight.is_finite() || weight <= 0.0 {
                    return Err(Error::invalid(
                        "measure weighted Hu moments: point partial stores a non-positive or \
                         non-finite sample weight",
                    ));
                }
                samples.push(WeightedHuSample {
                    at: partial_point3(
                        &sample[0..3],
                        "measure weighted Hu moments: point partial sample coordinate",
                    )?,
                    weight,
                });
            }
            offset = sample_range.end;
            seen_samples = seen_samples.checked_add(sample_count).ok_or_else(|| {
                Error::invalid("measure weighted Hu moments: point partial sample count overflow")
            })?;
            decoded.push((
                label,
                WeightedHuPointPartial {
                    owner_at,
                    finite_weight_count,
                    nonfinite_weight_count,
                    samples,
                },
            ));
        }
        if offset != words.len() {
            return Err(Error::invalid(
                "measure weighted Hu moments: point partial has trailing words",
            ));
        }
        if seen_samples != declared_sample_count {
            return Err(Error::invalid(
                "measure weighted Hu moments: point partial sample count does not match header",
            ));
        }
        Ok(decoded)
    }
}

impl PartialLayoutContract for WeightedHuPointPartialLayout {
    const MAGIC: u64 = WeightedHuPointPartialLayout::MAGIC;
    const VERSION: u64 = WeightedHuPointPartialLayout::VERSION;
    const HEADER_WORDS: usize = WeightedHuPointPartialLayout::HEADER_WORDS;
    const FORMAT: &'static str = "measure weighted Hu moments: point partial";
    const SHORT_ERROR: &'static str = "header is truncated";
    const MAGIC_ERROR: &'static str = "has the wrong format magic";
    const VERSION_ERROR: &'static str = "unsupported point partial version";
}

/// Block-local labelled weighted samples for projected weighted Hu moments.
#[derive(Debug, Clone)]
pub struct WeightedHuPointTallyOp {
    name: &'static str,
    labels: TypedSource,
    weights: TypedSource,
    stream: String,
    lifecycle: Lifecycle,
}

impl WeightedHuPointTallyOp {
    pub fn new(
        name: &'static str,
        labels: impl Into<ImageId>,
        weights: impl Into<ImageId>,
        _projection_axis: ProjectionAxis,
        stream: impl Into<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        let stream = WeightedHuSamplePartialStream::new(stream)?;
        Ok(Self {
            name,
            labels: TypedSource::new(labels),
            weights: TypedSource::new(weights),
            stream: stream.as_str().to_string(),
            lifecycle,
        })
    }

    pub fn holding_labels(mut self, labels: Dtype) -> Self {
        self.labels = self.labels.holding(labels);
        self
    }

    pub fn holding_weights(mut self, weights: Dtype) -> Self {
        self.weights = self.weights.holding(weights);
        self
    }

    fn tally_block(
        &self,
        labels: &BlockBuf,
        weights: &BlockBuf,
        read: &Region,
    ) -> Result<BTreeMap<u64, WeightedHuPointPartial>> {
        let mut partials = BTreeMap::<u64, WeightedHuPointPartial>::new();
        let (BlockBuf::Array(labels), BlockBuf::Array(weights)) = (labels, weights) else {
            return Ok(partials);
        };
        expect_extent(
            || {
                format!(
                    "measure weighted Hu moments: the label volume arrived as {:?} for a block \
                     read extent of {:?}",
                    labels.shape(),
                    read.shape3()
                )
            },
            read.shape3(),
            labels.shape(),
        )?;
        expect_extent(
            || {
                format!(
                    "measure weighted Hu moments: the weight volume arrived as {:?} for a block \
                     read extent of {:?}",
                    weights.shape(),
                    read.shape3()
                )
            },
            read.shape3(),
            weights.shape(),
        )?;
        let labels = labels.widened();
        let weights = weights.widened();
        for (index, raw_label) in labels.indexed_iter() {
            let at = [
                read.start[0] + index.0,
                read.start[1] + index.1,
                read.start[2] + index.2,
            ];
            let label = label_value(*raw_label, at)?;
            if label == 0 {
                continue;
            }
            let partial = partials.entry(label).or_default();
            partial.owner_at = Some(partial.owner_at.map_or(at, |owner| owner.min(at)));
            let weight = weights[index];
            if !weight.is_finite() {
                partial.nonfinite_weight_count += 1;
                continue;
            }
            if weight < 0.0 {
                return Err(Error::invalid(format!(
                    "measure weighted Hu moments: weight at {at:?} is negative ({weight})"
                )));
            }
            partial.finite_weight_count += 1;
            if weight > 0.0 {
                partial.samples.push(WeightedHuSample { at, weight });
            }
        }
        Ok(partials)
    }
}

impl FragmentOp for WeightedHuPointTallyOp {
    fn name(&self) -> &'static str {
        self.name
    }

    fn reach(&self, _axis: usize, _volume_len: usize) -> usize {
        0
    }

    fn source_inputs(&self, _volume: [usize; 3]) -> Vec<SourceInput> {
        vec![
            CoreBlockSourceRead::new(self.labels).source_input(),
            CoreBlockSourceRead::new(self.weights).source_input(),
        ]
    }

    fn outputs(&self) -> Vec<FragmentOutput> {
        vec![FragmentOutput::new(
            self.stream.clone(),
            self.lifecycle,
            Coverage::EveryBlock,
        )]
    }

    fn seam_fold(&self) -> Option<SeamFold> {
        MeasurementSeamLaw::per_block().seam_fold()
    }

    fn apply(&self, _at: &BlockView<'_>) -> Result<BlockOutput> {
        Err(Error::invalid(
            "measure weighted Hu moments: point partials read label and weight sources and are \
             applied through `apply_with`",
        ))
    }

    fn apply_with(&self, at: &BlockView<'_>, sources: SourceBlocks<'_>) -> Result<BlockOutput> {
        let partials = self.tally_block(
            self.labels
                .block_at_extent(self.name, "label volume", sources, at.read)?,
            self.weights
                .block_at_extent(self.name, "weight volume", sources, at.read)?,
            at.read,
        )?;
        Ok(BlockOutput::fragment(
            self.stream.clone(),
            WeightedHuPointPartialLayout::encode(&partials)?,
        ))
    }
}

/// Merge weighted sample partials into projected weighted Hu moment rows.
#[derive(Debug, Clone)]
pub struct MergeObjectWeightedHuMomentsOp {
    name: &'static str,
    input: PartialPhaseInput,
    projection_axis: ProjectionAxis,
    schema: Arc<Schema>,
    stream: String,
    lifecycle: Lifecycle,
}

impl MergeObjectWeightedHuMomentsOp {
    pub fn new(
        name: &'static str,
        input: impl Into<String>,
        input_phase: usize,
        lattice: [usize; 3],
        projection_axis: ProjectionAxis,
        stream: impl Into<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        let input = WeightedHuSamplePartialStream::new(input)?;
        let stream = WeightedHuMomentOutputStream::new(stream)?;
        Ok(Self {
            name,
            input: PartialPhaseInput::try_new(&input, input_phase, lattice)?,
            projection_axis,
            schema: Arc::new(object_weighted_hu_moment_measurement_schema()),
            stream: stream.as_str().to_string(),
            lifecycle,
        })
    }

    fn fold<'a>(
        &self,
        partials: impl IntoIterator<Item = &'a [u8]>,
    ) -> Result<BTreeMap<u64, WeightedHuPointPartial>> {
        let mut totals = BTreeMap::<u64, WeightedHuPointPartial>::new();
        for bytes in partials {
            for (label, partial) in WeightedHuPointPartialLayout::decode(bytes)? {
                totals
                    .entry(label)
                    .or_default()
                    .merge_exact(ExactReduction::new(partial))?;
            }
        }
        Ok(totals)
    }

    fn encode_owned(
        &self,
        totals: &BTreeMap<u64, WeightedHuPointPartial>,
        grid: &BlockGrid,
        block: [usize; 3],
    ) -> Result<Vec<u8>> {
        let mut rows = RowBuilder::new(Arc::clone(&self.schema));
        for (&label, partial) in totals {
            let Some(owner_point) = partial.owner_at else {
                continue;
            };
            if owner_of(grid, owner_point) != block {
                continue;
            }
            let mut samples = partial.samples.clone();
            samples.sort_by_key(|sample| sample.at);
            let mut weights_by_point = BTreeMap::<ProjectedVoxelIndex2, f64>::new();
            for sample in samples {
                let point = self.projection_axis.project(VoxelIndex3::new(sample.at));
                *weights_by_point.entry(point).or_default() += sample.weight;
            }
            let weighted_points = weights_by_point
                .iter()
                .map(|(&point, weight)| {
                    (
                        PhysicalPoint2::from_projected_voxel_center(
                            point,
                            ProjectedSpacing2::unit(),
                        ),
                        *weight,
                    )
                })
                .collect::<Vec<_>>();
            let weight_sum = weighted_points
                .iter()
                .map(|(_, weight)| *weight)
                .sum::<f64>();
            let centroid =
                (weight_sum > 0.0).then(|| weighted_centroid(&weighted_points, weight_sum));
            let hu = centroid
                .map(|centroid| weighted_hu_moments(&weighted_points, weight_sum, centroid));
            let row = ObjectWeightedHuMomentsMeasurements {
                label,
                projected_count: usize_count(
                    weighted_points.len(),
                    "measure weighted Hu moments: projected_count",
                )?,
                finite_weight_count: partial.finite_weight_count,
                nonfinite_weight_count: partial.nonfinite_weight_count,
                projection_axis: self.projection_axis,
                weight_sum,
                centroid: centroid.map(PhysicalPoint2::coords),
                hu,
            };
            validate_object_weighted_hu_moment_row(&row)?;
            rows.push(owner_point, &WeightedHuMomentColumns::values(&row))?;
        }
        Ok(rows.encode())
    }
}

impl FragmentOp for MergeObjectWeightedHuMomentsOp {
    fn name(&self) -> &'static str {
        self.name
    }

    fn reach(&self, _axis: usize, _volume_len: usize) -> usize {
        0
    }

    fn inputs(&self) -> Vec<FragmentInput> {
        vec![self.input.fragment_input()]
    }

    fn gathers(&self) -> bool {
        false
    }

    fn outputs(&self) -> Vec<FragmentOutput> {
        vec![
            FragmentOutput::new(self.stream.clone(), self.lifecycle, Coverage::EveryBlock)
                .sized(SidecarSize::row_table(self.schema.as_ref(), 1)),
        ]
    }

    fn seam_fold(&self) -> Option<SeamFold> {
        MeasurementSeamLaw::unordered_exact().seam_fold()
    }

    fn apply(&self, at: &BlockView<'_>) -> Result<BlockOutput> {
        let partials = self.input.stream_fragments(at)?;
        let totals = self.fold(partials.iter().map(Vec::as_slice))?;
        Ok(BlockOutput::fragment(
            self.stream.clone(),
            self.encode_owned(&totals, at.grid, at.index)?,
        ))
    }
}

