/// One 3D central moment and its scale-normalized value.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Moment3d {
    pub order: [usize; 3],
    pub central: f64,
    pub normalized: f64,
}

/// Resident full 3D moment family for one object-local point set.
#[derive(Debug, Clone, PartialEq)]
pub struct ObjectMoment3dMeasurements {
    pub label: u64,
    pub count: u64,
    pub centroid: [f64; 3],
    pub max_order: usize,
    pub moments: Vec<Moment3d>,
}

impl ObjectMoment3dMeasurements {
    pub fn central_key(&self, order: Moment3dKey) -> Option<f64> {
        let order = order.get();
        self.moments
            .iter()
            .find(|moment| moment.order == order)
            .map(|moment| moment.central)
    }

    pub fn central(&self, order: [usize; 3]) -> Option<f64> {
        self.central_key(Moment3dKey::new(order).ok()?)
    }

    pub fn normalized_key(&self, order: Moment3dKey) -> Option<f64> {
        let order = order.get();
        self.moments
            .iter()
            .find(|moment| moment.order == order)
            .map(|moment| moment.normalized)
    }

    pub fn normalized(&self, order: [usize; 3]) -> Option<f64> {
        self.normalized_key(Moment3dKey::new(order).ok()?)
    }

    pub fn feature(&self, feature: ObjectMoment3dFeature) -> Option<f64> {
        match feature {
            ObjectMoment3dFeature::Count => exact_u64_feature(self.count),
            ObjectMoment3dFeature::CentroidZ => Some(self.centroid[0]),
            ObjectMoment3dFeature::CentroidY => Some(self.centroid[1]),
            ObjectMoment3dFeature::CentroidX => Some(self.centroid[2]),
            ObjectMoment3dFeature::Central(order) => self.central_key(order),
            ObjectMoment3dFeature::Normalized(order) => self.normalized_key(order),
        }
    }
}

/// Validated 3-D moment exponent triple.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Moment3dKey {
    order: [u8; 3],
}

impl Moment3dKey {
    fn from_components(order: [u8; 3]) -> Self {
        Self { order }
    }

    pub fn new(order: [usize; 3]) -> Result<Self> {
        let total = order.iter().try_fold(0usize, |acc, &axis| {
            acc.checked_add(axis)
                .ok_or_else(|| Error::invalid("measure moments: moment order total overflowed"))
        })?;
        ObjectMoment3dSet::new(total)?;
        Ok(Self {
            order: [
                u8::try_from(order[0])
                    .map_err(|_| Error::invalid("measure moments: z order does not fit u8"))?,
                u8::try_from(order[1])
                    .map_err(|_| Error::invalid("measure moments: y order does not fit u8"))?,
                u8::try_from(order[2])
                    .map_err(|_| Error::invalid("measure moments: x order does not fit u8"))?,
            ],
        })
    }

    pub fn get(self) -> [usize; 3] {
        self.order.map(usize::from)
    }

    fn total_order(self) -> usize {
        self.get().iter().sum()
    }

    fn powi_exponents(self) -> [i32; 3] {
        self.order.map(i32::from)
    }
}

/// Derived scalar that can be read from a 3-D moment row.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum ObjectMoment3dFeature {
    Count,
    CentroidZ,
    CentroidY,
    CentroidX,
    Central(Moment3dKey),
    Normalized(Moment3dKey),
}

impl ObjectMoment3dFeature {
    pub fn central(order: [usize; 3]) -> Result<Self> {
        Ok(Self::Central(Moment3dKey::new(order)?))
    }

    pub fn normalized(order: [usize; 3]) -> Result<Self> {
        Ok(Self::Normalized(Moment3dKey::new(order)?))
    }

    pub fn column_name(self) -> String {
        match self {
            Self::Count => "count".to_string(),
            Self::CentroidZ => "centroid_z".to_string(),
            Self::CentroidY => "centroid_y".to_string(),
            Self::CentroidX => "centroid_x".to_string(),
            Self::Central(order) => {
                let [z, y, x] = order.get();
                format!("central_{z}_{y}_{x}")
            }
            Self::Normalized(order) => {
                let [z, y, x] = order.get();
                format!("normalized_{z}_{y}_{x}")
            }
        }
    }
}

/// Compute resident 3D central and normalized moments up to `max_order`.
///
/// Orders are expressed as `[z, y, x]` exponents in physical coordinates. The
/// normalized value uses the 3D scale-invariant form
/// `mu_pqr / m000^(1 + (p + q + r) / 3)`. This resident helper is intended for
/// exact object-local reference measurements; planned hot-loop partials still
/// store only the lower-order moment ingredients they can merge compactly.
pub fn object_3d_moment_measurements(
    labels: ArrayView3<'_, f64>,
    spacing: PhysicalSpacing,
    max_order: usize,
) -> Result<Vec<ObjectMoment3dMeasurements>> {
    object_3d_moment_measurements_set(labels, spacing, ObjectMoment3dSet::new(max_order)?)
}

/// Compute resident 3D central and normalized moments for a validated order set.
pub fn object_3d_moment_measurements_set(
    labels: ArrayView3<'_, f64>,
    spacing: PhysicalSpacing,
    set: ObjectMoment3dSet,
) -> Result<Vec<ObjectMoment3dMeasurements>> {
    let max_order = set.max_order();
    let objects = collect_object_point_sets(labels)?;
    let orders = moment_3d_orders(set);
    let mut out = Vec::with_capacity(objects.len());
    for object in objects.into_values() {
        let points = object.physical_points(spacing);
        let centroid = object.physical_centroid(spacing);
        let mass = points.len() as f64;
        let moments = orders
            .iter()
            .copied()
            .map(|order| {
                let central = central_moment_3d(&points, centroid, order);
                let total_order = order.total_order();
                let gamma = 1.0 + total_order as f64 / 3.0;
                Moment3d {
                    order: order.get(),
                    central,
                    normalized: central / mass.powf(gamma),
                }
            })
            .collect();
        out.push(ObjectMoment3dMeasurements {
            label: object.label,
            count: usize_count(points.len(), "measure moments: count")?,
            centroid: centroid.coords(),
            max_order,
            moments,
        });
    }
    Ok(out)
}

/// Planned full 3D central/normalized moment rows from a whole-volume label fetch.
///
/// This first planned path reuses the resident exact object-local helper and
/// emits canonical rows from one owner block. A future compact implementation
