/// Count connected components for each label under 6/18/26 foreground connectivity.
///
/// This is the component-only alternate-connectivity slice. For complementary
/// topology conventions that also report tunnels and cavities, use
/// [`object_topology_measurements_with`].
pub fn object_component_measurements(
    labels: ArrayView3<'_, f64>,
    connectivity: Connectivity,
) -> Result<Vec<ObjectComponentMeasurements>> {
    let objects = collect_object_point_sets(labels)?;
    let mut out = Vec::with_capacity(objects.len());
    for object in objects.into_values() {
        out.push(ObjectComponentMeasurements {
            label: object.label,
            count: usize_count(object.points.len(), "measure components: count")?,
            connectivity,
            components: object_components(&object.points, connectivity),
        });
    }
    Ok(out)
}

