fn validate_topology_row(row: &ObjectTopologyMeasurements) -> Result<()> {
    if row.label == 0 {
        return Err(Error::invalid(
            "measure topology: row has background label 0",
        ));
    }
    let expected = row.components as i128 - row.tunnels as i128 + row.cavities as i128;
    if expected != row.euler_number as i128 {
        return Err(Error::invalid(format!(
            "measure topology: row for label {} has components {}, tunnels {}, cavities {} and \
             inconsistent Euler number {}",
            row.label, row.components, row.tunnels, row.cavities, row.euler_number
        )));
    }
    Ok(())
}

fn validate_component_row(row: &ObjectComponentMeasurements) -> Result<()> {
    if row.label == 0 {
        return Err(Error::invalid(
            "measure components: row has background label 0",
        ));
    }
    if row.count == 0 {
        return Err(Error::invalid(format!(
            "measure components: row for label {} has zero count",
            row.label
        )));
    }
    let components = usize_count(row.components, "measure components: components")?;
    if row.components == 0 || components > row.count {
        return Err(Error::invalid(format!(
            "measure components: row for label {} has {} components for {} voxels",
            row.label, row.components, row.count
        )));
    }
    Ok(())
}

fn connectivity_code(connectivity: Connectivity) -> u64 {
    match connectivity {
        Connectivity::Faces => 6,
        Connectivity::FacesAndEdges => 18,
        Connectivity::FacesEdgesAndCorners => 26,
    }
}

fn connectivity_from_code(code: u64) -> Result<Connectivity> {
    match code {
        6 => Ok(Connectivity::Faces),
        18 => Ok(Connectivity::FacesAndEdges),
        26 => Ok(Connectivity::FacesEdgesAndCorners),
        other => Err(Error::invalid(format!(
            "measure components: connectivity must be 6, 18 or 26, got {other}"
        ))),
    }
}

fn topology_convention_code(convention: ObjectTopologyConvention) -> u64 {
    match convention {
        ObjectTopologyConvention::Foreground26Background6 => 26_006,
        ObjectTopologyConvention::Foreground6Background26 => 6_026,
    }
}

fn topology_convention_from_code(code: u64) -> Result<ObjectTopologyConvention> {
    match code {
        26_006 => Ok(ObjectTopologyConvention::Foreground26Background6),
        6_026 => Ok(ObjectTopologyConvention::Foreground6Background26),
        other => Err(Error::invalid(format!(
            "measure topology: convention must be 26006 or 6026, got {other}"
        ))),
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(transparent)]
struct TableU64(u64);

impl TableU64 {
    fn from_usize(value: usize, what: &str) -> Result<Self> {
        Ok(Self(u64::try_from(value).map_err(|_| {
            Error::invalid(format!("{what} does not fit in a u64 table field"))
        })?))
    }

    fn get(self) -> u64 {
        self.0
    }

    fn value(self) -> Value {
        Value::U64(self.get())
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
#[repr(transparent)]
struct IntegerF64U64(u64);

impl IntegerF64U64 {
    fn new(value: f64, what: impl std::fmt::Display) -> Result<Self> {
        const U64_EXCLUSIVE_MAX_AS_F64: f64 = 18_446_744_073_709_551_616.0;
        if !value.is_finite()
            || value < 0.0
            || value >= U64_EXCLUSIVE_MAX_AS_F64
            || value.fract() != 0.0
        {
            return Err(Error::invalid(format!(
                "{what} is not a non-negative whole number that fits in u64"
            )));
        }
        Ok(Self(value as u64))
    }

    fn get(self) -> u64 {
        self.0
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
#[repr(transparent)]
struct LabelValue(u64);

impl LabelValue {
    fn from_f64(raw: f64, at: [usize; 3]) -> Result<Self> {
        Ok(Self(
            IntegerF64U64::new(raw, format!("measurements: label value {raw} at {at:?}"))?.get(),
        ))
    }

    fn get(self) -> u64 {
        self.0
    }
}

fn usize_column(value: usize, what: &str) -> Result<Value> {
    Ok(TableU64::from_usize(value, what)?.value())
}

fn usize_count(value: usize, what: &str) -> Result<u64> {
    Ok(TableU64::from_usize(value, what)?.get())
}

fn usize_coordinate(value: usize, what: &str) -> Result<u64> {
    Ok(TableU64::from_usize(value, what)?.get())
}

fn rounded_centroid_coordinate(position: [u64; 3], count: u64) -> Option<[usize; 3]> {
    if count == 0 {
        return None;
    }
    let count = count as u128;
    let mut at = [0usize; 3];
    for (axis, coordinate) in at.iter_mut().enumerate() {
        let rounded = (2 * position[axis] as u128 + count) / (2 * count);
        *coordinate = usize::try_from(rounded).ok()?;
    }
    Some(at)
}

fn row_usize(row: &Row<'_>, column: usize, what: &str) -> Result<usize> {
    usize::try_from(row.u64(column)?)
        .map_err(|_| Error::invalid(format!("{what} does not fit in usize")))
}

fn row_point3(row: &Row<'_>, columns: [usize; 3], what: &str) -> Result<[usize; 3]> {
    Ok([
        row_usize(row, columns[0], what)?,
        row_usize(row, columns[1], what)?,
        row_usize(row, columns[2], what)?,
    ])
}

