/// Compute per-label minimum enclosing spheres over physical voxel centres.
///
/// This resident helper enumerates all support sets up to four points. It is
/// exact for the materialized point set but intentionally not yet the planned
/// high-throughput object-local backend.
pub fn object_enclosing_sphere_measurements(
    labels: ArrayView3<'_, f64>,
    spacing: PhysicalSpacing,
) -> Result<Vec<ObjectEnclosingSphereMeasurements>> {
    let objects = collect_object_point_sets(labels)?;
    let mut out = Vec::with_capacity(objects.len());
    for object in objects.into_values() {
        let points = object.physical_points(spacing);
        let points = NonEmptySlice::new(&points)
            .ok_or_else(|| Error::invalid("measure sphere: object has no points"))?;
        let sphere = minimum_enclosing_sphere(points);
        let radius = PhysicalRadius::from_squared_distance(sphere.radius_squared)?.get();
        out.push(ObjectEnclosingSphereMeasurements {
            label: object.label,
            count: usize_count(points.slice().len(), "measure sphere: count")?,
            center: sphere.center.coords(),
            radius,
            support_points: sphere.support_points,
        });
    }
    Ok(out)
}

/// Planned enclosing-sphere rows from a whole-volume label fetch.
#[derive(Debug, Clone)]
pub struct EnclosingSphereOp {
    name: &'static str,
    labels: TypedSource,
    spacing: PhysicalSpacing,
    schema: Arc<Schema>,
    stream: String,
    lifecycle: Lifecycle,
}

impl EnclosingSphereOp {
    pub fn new(
        name: &'static str,
        labels: impl Into<ImageId>,
        spacing: PhysicalSpacing,
        stream: impl Into<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        let stream = EnclosingSphereOutputStream::new(stream)?;
        Ok(Self {
            name,
            labels: TypedSource::new(labels),
            spacing,
            schema: Arc::new(enclosing_sphere_measurement_schema()),
            stream: stream.as_str().to_string(),
            lifecycle,
        })
    }

    pub fn holding(mut self, labels: Dtype) -> Self {
        self.labels = self.labels.holding(labels);
        self
    }

    pub fn stream(&self) -> &str {
        &self.stream
    }

    pub fn spacing(&self) -> PhysicalSpacing {
        self.spacing
    }
}

impl FragmentOp for EnclosingSphereOp {
    fn name(&self) -> &'static str {
        self.name
    }

    fn reach(&self, _axis: usize, _volume_len: usize) -> usize {
        0
    }

    fn reads_pixels(&self) -> bool {
        false
    }

    fn source_inputs(&self, _volume: [usize; 3]) -> Vec<SourceInput> {
        vec![FullVolumeSourceRead::new(self.labels).source_input()]
    }

    fn outputs(&self) -> Vec<FragmentOutput> {
        vec![
            FragmentOutput::new(self.stream.clone(), self.lifecycle, Coverage::EveryBlock)
                .sized(SidecarSize::row_table(self.schema.as_ref(), 1)),
        ]
    }

    fn seam_fold(&self) -> Option<SeamFold> {
        MeasurementSeamLaw::per_block().seam_fold()
    }

    fn apply(&self, _at: &BlockView<'_>) -> Result<BlockOutput> {
        Err(Error::invalid(
            "measure sphere: enclosing sphere reads the label source and is applied through \
             `apply_with`",
        ))
    }

    fn apply_with(&self, at: &BlockView<'_>, sources: SourceBlocks<'_>) -> Result<BlockOutput> {
        if at.index != [0, 0, 0] {
            return Ok(BlockOutput::fragment(
                self.stream.clone(),
                encode_enclosing_sphere_measurements_with_schema(&[], Arc::clone(&self.schema))?,
            ));
        }
        let labels = self
            .labels
            .block_at_extent(self.name, "label volume", sources, at.read)?;
        let BlockBuf::Array(labels) = labels else {
            return Ok(BlockOutput::fragment(
                self.stream.clone(),
                encode_enclosing_sphere_measurements_with_schema(&[], Arc::clone(&self.schema))?,
            ));
        };
        let labels = labels.widened();
        let rows = object_enclosing_sphere_measurements(labels.view(), self.spacing)?;
        Ok(BlockOutput::fragment(
            self.stream.clone(),
            encode_enclosing_sphere_measurements_with_schema(&rows, Arc::clone(&self.schema))?,
        ))
    }
}

fn validate_enclosing_sphere_row(row: &ObjectEnclosingSphereMeasurements) -> Result<()> {
    if row.label == 0 {
        return Err(Error::invalid("measure sphere: row has background label 0"));
    }
    if row.count == 0 {
        return Err(Error::invalid(format!(
            "measure sphere: row for label {} has zero count",
            row.label
        )));
    }
    for (axis, &center) in row.center.iter().enumerate() {
        if !center.is_finite() {
            return Err(Error::invalid(format!(
                "measure sphere: row for label {} has invalid center {center} on axis {axis}",
                row.label
            )));
        }
    }
    if PhysicalRadius::new(row.radius).is_err() {
        return Err(Error::invalid(format!(
            "measure sphere: row for label {} has invalid radius {}",
            row.label, row.radius
        )));
    }
    let support_points = usize_count(row.support_points, "measure sphere: support_points")?;
    if row.support_points == 0 || row.support_points > 4 || support_points > row.count {
        return Err(Error::invalid(format!(
            "measure sphere: row for label {} has {} support points for {} voxels",
            row.label, row.support_points, row.count
        )));
    }
    Ok(())
}

