/// Compute per-label 3-D convex hull measurements over physical voxel centres.
///
/// This is the resident reference for point-set hull geometry. It is exact for
/// the materialized voxel-centre coordinates, but it is not the future
/// continuous voxel-face convex hull promised by the planned object-local
/// executor.
pub fn object_convex_hull_measurements(
    labels: ArrayView3<'_, f64>,
    spacing: PhysicalSpacing,
) -> Result<Vec<ObjectConvexHullMeasurements>> {
    let objects = collect_object_point_sets(labels)?;
    let mut out = Vec::with_capacity(objects.len());
    for object in objects.into_values() {
        let points = object.physical_points(spacing);
        let hull = convex_hull_3d(&points);
        out.push(ObjectConvexHullMeasurements {
            label: object.label,
            count: usize_count(points.len(), "measure convex hull: count")?,
            hull_vertices: hull.vertices,
            hull_faces: hull.faces,
            surface_area: hull.surface_area,
            volume: hull.volume,
            max_hull_feret_diameter: hull.max_feret_diameter,
        });
    }
    Ok(out)
}

/// Compute per-label convex hull measurements over continuous voxel faces.
pub fn object_voxel_face_convex_hull_measurements(
    labels: ArrayView3<'_, f64>,
    spacing: PhysicalSpacing,
) -> Result<Vec<ObjectVoxelFaceConvexHullMeasurements>> {
    let objects = collect_object_point_sets(labels)?;
    let mut out = Vec::with_capacity(objects.len());
    for object in objects.into_values() {
        let points = object.physical_voxel_face_points(spacing);
        let hull = convex_hull_3d(&points);
        out.push(ObjectVoxelFaceConvexHullMeasurements {
            label: object.label,
            count: usize_count(object.points.len(), "measure voxel-face convex hull: count")?,
            hull_vertices: hull.vertices,
            hull_faces: hull.faces,
            surface_area: hull.surface_area,
            volume: hull.volume,
            max_feret_diameter: hull.max_feret_diameter,
        });
    }
    Ok(out)
}

