impl FragmentOp for ObjectProjectedConvexOp {
    fn name(&self) -> &'static str {
        self.name
    }

    fn reach(&self, _axis: usize, _volume_len: usize) -> usize {
        0
    }

    fn reads_pixels(&self) -> bool {
        false
    }

    fn source_inputs(&self, _volume: [usize; 3]) -> Vec<SourceInput> {
        vec![FullVolumeSourceRead::new(self.labels).source_input()]
    }

    fn outputs(&self) -> Vec<FragmentOutput> {
        vec![
            FragmentOutput::new(self.stream.clone(), self.lifecycle, Coverage::EveryBlock)
                .sized(SidecarSize::row_table(self.schema.as_ref(), 1)),
        ]
    }

    fn seam_fold(&self) -> Option<SeamFold> {
        MeasurementSeamLaw::per_block().seam_fold()
    }

    fn apply(&self, _at: &BlockView<'_>) -> Result<BlockOutput> {
        Err(Error::invalid(
            "measure projected convex: projected convex geometry reads the label source and is \
             applied through `apply_with`",
        ))
    }

    fn apply_with(&self, at: &BlockView<'_>, sources: SourceBlocks<'_>) -> Result<BlockOutput> {
        if at.index != [0, 0, 0] {
            return Ok(BlockOutput::fragment(
                self.stream.clone(),
                encode_object_projected_convex_measurements_set(&[], self.set)?,
            ));
        }
        let labels = self
            .labels
            .block_at_extent(self.name, "label volume", sources, at.read)?;
        let BlockBuf::Array(labels) = labels else {
            return Ok(BlockOutput::fragment(
                self.stream.clone(),
                encode_object_projected_convex_measurements_set(&[], self.set)?,
            ));
        };
        let labels = labels.widened();
        let rows = object_projected_convex_measurements_set(
            labels.view(),
            self.spacing,
            self.projection_axis,
            self.set,
        )?;
        Ok(BlockOutput::fragment(
            self.stream.clone(),
            encode_object_projected_convex_measurements_set(&rows, self.set)?,
        ))
    }
}

fn validate_object_projected_convex_row(
    row: &ObjectProjectedConvexMeasurements,
    set: ProjectedConvexSet,
) -> Result<()> {
    let max_hull_vertices = set.max_hull_vertices();
    if row.label == 0 {
        return Err(Error::invalid(
            "measure projected convex: row has background label 0",
        ));
    }
    if row.projected_count == 0 {
        return Err(Error::invalid(format!(
            "measure projected convex: row for label {} has zero projected count",
            row.label
        )));
    }
    if row.hull_vertices.is_empty() || row.hull_vertices.len() > max_hull_vertices {
        return Err(Error::invalid(format!(
            "measure projected convex: row for label {} has {} hull vertices, maximum is {}",
            row.label,
            row.hull_vertices.len(),
            max_hull_vertices
        )));
    }
    for (index, vertex) in row.hull_vertices.iter().enumerate() {
        for (axis, &coordinate) in vertex.iter().enumerate() {
            if !coordinate.is_finite() {
                return Err(Error::invalid(format!(
                    "measure projected convex: row for label {} has invalid hull vertex {index} \
                     coordinate {axis}: {coordinate}",
                    row.label
                )));
            }
        }
    }
    if !row.projected_area.is_finite() || row.projected_area <= 0.0 {
        return Err(Error::invalid(format!(
            "measure projected convex: row for label {} has invalid projected area {}",
            row.label, row.projected_area
        )));
    }
    if !row.convex_hull_area.is_finite() || row.convex_hull_area <= 0.0 {
        return Err(Error::invalid(format!(
            "measure projected convex: row for label {} has invalid convex hull area {}",
            row.label, row.convex_hull_area
        )));
    }
    match row.solidity {
        Some(solidity) if solidity.is_finite() && solidity >= 0.0 => {}
        _ => {
            return Err(Error::invalid(format!(
                "measure projected convex: row for label {} has invalid solidity {:?}",
                row.label, row.solidity
            )));
        }
    }
    if !row.max_projected_feret_diameter.is_finite() || row.max_projected_feret_diameter < 0.0 {
        return Err(Error::invalid(format!(
            "measure projected convex: row for label {} has invalid Feret diameter {}",
            row.label, row.max_projected_feret_diameter
        )));
    }
    for (axis, &coordinate) in row.min_enclosing_circle_center.iter().enumerate() {
        if !coordinate.is_finite() {
            return Err(Error::invalid(format!(
                "measure projected convex: row for label {} has invalid enclosing-circle center \
                 {coordinate} on axis {axis}",
                row.label
            )));
        }
    }
    if PhysicalRadius::new(row.min_enclosing_circle_radius).is_err() {
        return Err(Error::invalid(format!(
            "measure projected convex: row for label {} has invalid enclosing-circle radius {}",
            row.label, row.min_enclosing_circle_radius
        )));
    }
    let support_points = usize_count(
        row.min_enclosing_circle_support_points,
        "measure projected convex: enclosing-circle support_points",
    )?;
    if row.min_enclosing_circle_support_points == 0
        || row.min_enclosing_circle_support_points > 3
        || support_points > row.projected_count
    {
        return Err(Error::invalid(format!(
            "measure projected convex: row for label {} has {} enclosing-circle support points \
             for {} projected points",
            row.label, row.min_enclosing_circle_support_points, row.projected_count
        )));
    }
    Ok(())
}

/// Projected binary Hu moments for a resident object-local point set.
