/// Compute per-label Hu invariant moments on a binary voxel-centre projection.
///
/// Each object is projected along `projection_axis`, duplicate projected pixels
/// are collapsed, and the seven Hu invariants are computed from central moments
/// of the remaining binary point set. This is intentionally a point-set
/// projection, not a continuous-face or intensity-weighted moment integral.
pub fn object_hu_moments_measurements(
    labels: ArrayView3<'_, f64>,
    projection_axis: ProjectionAxis,
) -> Result<Vec<ObjectHuMomentsMeasurements>> {
    let objects = collect_object_point_sets(labels)?;
    let mut out = Vec::with_capacity(objects.len());
    for object in objects.into_values() {
        let (points, centroid) = projected_voxel_centers_with_centroid(
            &object.points,
            projection_axis,
            "measure Hu moments",
        )?;
        let hu = hu_moments(&points, centroid);
        out.push(ObjectHuMomentsMeasurements {
            label: object.label,
            projected_count: usize_count(points.len(), "measure Hu moments: projected_count")?,
            projection_axis,
            centroid: centroid.coords(),
            hu,
        });
    }
    Ok(out)
}

