/// One complex projected binary Zernike moment.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct ObjectZernikeMoment {
    pub order: usize,
    pub repetition: usize,
    pub real: f64,
    pub imag: f64,
    pub magnitude: f64,
}

/// Projected binary Zernike moments for one labelled object.
#[derive(Debug, Clone, PartialEq)]
pub struct ObjectZernikeMomentsMeasurements {
    pub label: u64,
    pub projected_count: u64,
    pub projection_axis: ProjectionAxis,
    pub max_order: usize,
    pub centroid: [f64; 2],
    pub radius: f64,
    pub moments: Vec<ObjectZernikeMoment>,
}

/// Validated projected Zernike moment order/repetition selector.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct ZernikeMomentKey {
    order: u8,
    repetition: u8,
}

impl ZernikeMomentKey {
    pub fn new(order: usize, repetition: usize) -> Result<Self> {
        ObjectZernikeMomentSet::new(order)?;
        if repetition > order {
            return Err(Error::invalid(format!(
                "measure Zernike moments: repetition {repetition} exceeds order {order}"
            )));
        }
        if (order - repetition) % 2 != 0 {
            return Err(Error::invalid(format!(
                "measure Zernike moments: order {order} and repetition {repetition} have \
                incompatible parity"
            )));
        }
        Ok(Self {
            order: u8::try_from(order)
                .map_err(|_| Error::invalid("measure Zernike moments: order does not fit u8"))?,
            repetition: u8::try_from(repetition).map_err(|_| {
                Error::invalid("measure Zernike moments: repetition does not fit u8")
            })?,
        })
    }

    pub fn order(self) -> usize {
        usize::from(self.order)
    }

    pub fn repetition(self) -> usize {
        usize::from(self.repetition)
    }
}

/// Derived scalar that can be read from a projected Zernike row.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum ObjectZernikeMomentFeature {
    ProjectedCount,
    Centroid0,
    Centroid1,
    Radius,
    Real(ZernikeMomentKey),
    Imag(ZernikeMomentKey),
    Magnitude(ZernikeMomentKey),
}

impl ObjectZernikeMomentFeature {
    pub fn real(order: usize, repetition: usize) -> Result<Self> {
        Ok(Self::Real(ZernikeMomentKey::new(order, repetition)?))
    }

    pub fn imag(order: usize, repetition: usize) -> Result<Self> {
        Ok(Self::Imag(ZernikeMomentKey::new(order, repetition)?))
    }

    pub fn magnitude(order: usize, repetition: usize) -> Result<Self> {
        Ok(Self::Magnitude(ZernikeMomentKey::new(order, repetition)?))
    }

    pub fn column_name(self) -> String {
        match self {
            Self::ProjectedCount => "projected_count".to_string(),
            Self::Centroid0 => "centroid_0".to_string(),
            Self::Centroid1 => "centroid_1".to_string(),
            Self::Radius => "radius".to_string(),
            Self::Real(moment) => {
                format!("zernike_{}_{}_real", moment.order(), moment.repetition())
            }
            Self::Imag(moment) => {
                format!("zernike_{}_{}_imag", moment.order(), moment.repetition())
            }
            Self::Magnitude(moment) => {
                format!(
                    "zernike_{}_{}_magnitude",
                    moment.order(),
                    moment.repetition()
                )
            }
        }
    }
}

impl ObjectZernikeMomentsMeasurements {
    pub fn moment_key(&self, key: ZernikeMomentKey) -> Option<ObjectZernikeMoment> {
        self.moments
            .iter()
            .copied()
            .find(|moment| moment.order == key.order() && moment.repetition == key.repetition())
    }

    pub fn moment(&self, order: usize, repetition: usize) -> Option<ObjectZernikeMoment> {
        self.moment_key(ZernikeMomentKey::new(order, repetition).ok()?)
    }

    pub fn feature(&self, feature: ObjectZernikeMomentFeature) -> Option<f64> {
        match feature {
            ObjectZernikeMomentFeature::ProjectedCount => exact_u64_feature(self.projected_count),
            ObjectZernikeMomentFeature::Centroid0 => Some(self.centroid[0]),
            ObjectZernikeMomentFeature::Centroid1 => Some(self.centroid[1]),
            ObjectZernikeMomentFeature::Radius => Some(self.radius),
            ObjectZernikeMomentFeature::Real(key) => self.moment_key(key).map(|moment| moment.real),
            ObjectZernikeMomentFeature::Imag(key) => self.moment_key(key).map(|moment| moment.imag),
            ObjectZernikeMomentFeature::Magnitude(key) => {
                self.moment_key(key).map(|moment| moment.magnitude)
            }
        }
    }
}

