/// Opt-in custom object-local measurement.
pub trait ObjectMeasure: Send + Sync + 'static {
    fn key(&self) -> MeasurementKey;
    fn schema(&self) -> Schema;
    fn wants(&self) -> ObjectInputs;
    fn cost_per_object(&self) -> f64 {
        1.0
    }
    fn apply(&self, object: ObjectView<'_>, out: &mut RowBuilder) -> Result<()>;
}

impl std::fmt::Debug for dyn ObjectMeasure {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ObjectMeasure")
            .field("key", &self.key().as_str())
            .finish_non_exhaustive()
    }
}

/// Run one object-local extension over resident labels.
pub fn run_object_measure(
    labels: ArrayView3<'_, f64>,
    measure: &dyn ObjectMeasure,
) -> Result<Vec<u8>> {
    let request = ValidatedResidentObjectRequest::new(measure)?;
    let mut rows = RowBuilder::new(request.schema.clone_arc());
    let objects = collect_object_point_sets(labels)?;
    for object in objects.values() {
        let boundary_points = request
            .wants
            .wants_boundary_points()
            .then(|| object_boundary_points(&object.points));
        let projected_hull_vertices = request
            .wants
            .projected_hull_axis()
            .map(|axis| projected_object_hull_vertices(&object.points, axis));
        let convex_hull = request.wants.convex_hull_spacing().map(|spacing| {
            ObjectConvexHullView::new(convex_hull_3d(&object.physical_points(spacing)))
        });
        request.measure.apply(
            ObjectView::new(
                object,
                boundary_points.as_deref(),
                projected_hull_vertices.as_deref(),
                convex_hull,
            ),
            &mut rows,
        )?;
    }
    Ok(rows.encode())
}

/// Resident decomposition-invariance harness for object-local extensions.
///
/// The current resident object-extension path materializes whole objects, so the
/// invariant is that repeated runs produce the same encoded rows and invalid
/// labels are refused before the extension sees an object.
pub fn assert_object_measurement_invariant(
    labels: ArrayView3<'_, f64>,
    measure: &dyn ObjectMeasure,
) -> Result<()> {
    let first = run_object_measure(labels, measure)?;
    let second = run_object_measure(labels, measure)?;
    if first != second {
        return Err(Error::invalid(format!(
            "measure extensions: object measure {:?} produced non-deterministic rows",
            measure.key().as_str()
        )));
    }
    Ok(())
}

