/// Per-object nearest-neighbor summary derived from relationship rows.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct ObjectNeighborMeasurements {
    pub label: u64,
    pub within_distance_neighbors: u64,
    pub closest_label: Option<u64>,
    pub closest_distance: Option<f64>,
    pub second_closest_label: Option<u64>,
    pub second_closest_distance: Option<f64>,
    pub angle_between_closest: Option<f64>,
}

/// Derived scalar that can be read from a centroid-neighbor summary row.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum ObjectNeighborFeature {
    WithinDistanceNeighbors,
    ClosestLabel,
    ClosestDistance,
    SecondClosestLabel,
    SecondClosestDistance,
    AngleBetweenClosest,
}

impl ObjectNeighborFeature {
    pub const ALL: [Self; 6] = [
        Self::WithinDistanceNeighbors,
        Self::ClosestLabel,
        Self::ClosestDistance,
        Self::SecondClosestLabel,
        Self::SecondClosestDistance,
        Self::AngleBetweenClosest,
    ];

    pub fn column_name(self) -> &'static str {
        match self {
            Self::WithinDistanceNeighbors => "within_distance_neighbors",
            Self::ClosestLabel => "closest_label",
            Self::ClosestDistance => "closest_distance",
            Self::SecondClosestLabel => "second_closest_label",
            Self::SecondClosestDistance => "second_closest_distance",
            Self::AngleBetweenClosest => "angle_between_closest",
        }
    }
}

impl ObjectNeighborMeasurements {
    pub fn feature(&self, feature: ObjectNeighborFeature) -> Option<f64> {
        match feature {
            ObjectNeighborFeature::WithinDistanceNeighbors => {
                exact_u64_feature(self.within_distance_neighbors)
            }
            ObjectNeighborFeature::ClosestLabel => self.closest_label.and_then(exact_u64_feature),
            ObjectNeighborFeature::ClosestDistance => self.closest_distance,
            ObjectNeighborFeature::SecondClosestLabel => {
                self.second_closest_label.and_then(exact_u64_feature)
            }
            ObjectNeighborFeature::SecondClosestDistance => self.second_closest_distance,
            ObjectNeighborFeature::AngleBetweenClosest => self.angle_between_closest,
        }
    }
}

fn nonzero_label_option(label: u64) -> Option<u64> {
    (label != 0).then_some(label)
}

fn optional_distance(label: Option<u64>, distance: f64) -> Option<f64> {
    label.map(|_| distance)
}

fn optional_angle(second_label: Option<u64>, angle: f64) -> Option<f64> {
    second_label.map(|_| angle)
}

fn validate_optional_non_negative_finite(
    value: Option<f64>,
    what: impl FnOnce() -> String,
) -> Result<()> {
    if let Some(value) = value {
        if !value.is_finite() || value < 0.0 {
            return Err(Error::invalid(format!("{} is {value}", what())));
        }
    }
    Ok(())
}

fn validate_centroid_neighbor_row(row: &ObjectNeighborMeasurements) -> Result<()> {
    if row.label == 0 {
        return Err(Error::invalid(
            "measure relationships: centroid neighbor row has background label 0",
        ));
    }
    if matches!(
        (row.closest_label, row.closest_distance),
        (Some(_), None) | (None, Some(_))
    ) {
        return Err(Error::invalid(format!(
            "measure relationships: centroid neighbor row for label {} has inconsistent closest neighbor fields",
            row.label
        )));
    }
    if matches!(
        (row.second_closest_label, row.second_closest_distance),
        (Some(_), None) | (None, Some(_))
    ) {
        return Err(Error::invalid(format!(
            "measure relationships: centroid neighbor row for label {} has inconsistent second-closest neighbor fields",
            row.label
        )));
    }
    if row.angle_between_closest.is_some() && row.second_closest_label.is_none() {
        return Err(Error::invalid(format!(
            "measure relationships: centroid neighbor row for label {} has an angle without two neighbors",
            row.label
        )));
    }
    validate_optional_non_negative_finite(row.closest_distance, || {
        format!(
            "measure relationships: centroid neighbor row for label {} closest distance",
            row.label
        )
    })?;
    validate_optional_non_negative_finite(row.second_closest_distance, || {
        format!(
            "measure relationships: centroid neighbor row for label {} second-closest distance",
            row.label
        )
    })?;
    if let Some(angle) = row.angle_between_closest {
        if !angle.is_finite() || !(0.0..=std::f64::consts::PI).contains(&angle) {
            return Err(Error::invalid(format!(
                "measure relationships: centroid neighbor row for label {} angle is {angle}",
                row.label
            )));
        }
    }
    Ok(())
}

/// Validated non-negative physical-distance threshold for neighbor summaries.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct WithinDistanceThreshold(f64);

impl WithinDistanceThreshold {
    pub fn new(distance: f64) -> Result<Self> {
        if !distance.is_finite() || distance < 0.0 {
            return Err(Error::invalid(format!(
                "measure relationships: within-distance threshold must be finite and non-negative, \
                 got {distance}"
            )));
        }
        Ok(Self(distance))
    }

    pub fn get(self) -> f64 {
        self.0
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
struct NeighborCandidate {
    label: u64,
    distance: f64,
    vector: PhysicalVector3,
}

/// Resident Class F relationship rows for all unordered object centroid pairs.
pub fn object_centroid_relationships(
    labels: ArrayView3<'_, f64>,
    spacing: PhysicalSpacing,
) -> Result<Vec<ObjectRelationshipMeasurements>> {
    let objects = collect_object_point_sets(labels)?;
    let centroids = objects
        .values()
        .map(|object| (object.label, object.physical_centroid(spacing)))
        .collect::<Vec<_>>();
    let mut out = Vec::new();
    for (index, &(a_label, a_centroid)) in centroids.iter().enumerate() {
        for &(b_label, b_centroid) in &centroids[index + 1..] {
            let delta = a_centroid.delta_to(b_centroid);
            out.push(ObjectRelationshipMeasurements {
                labels: [a_label, b_label],
                centroid_distance: delta.norm(),
                centroid_delta: delta.coords(),
            });
        }
    }
    Ok(out)
}

/// Class F centroid-distance relationship rows derived from merged shape rows.
///
/// This is the planned path for centroid relationships: the label image is
/// scanned once by Class A tabulation, and this stage derives pair rows from the
/// resulting centroids instead of walking labels again.
pub fn object_centroid_relationships_from_shapes(
    shapes: &[RegionShape],
    spacing: PhysicalSpacing,
) -> Result<Vec<ObjectRelationshipMeasurements>> {
    let mut centroids = Vec::with_capacity(shapes.len());
    for shape in shapes {
        if shape.label == 0 {
            return Err(Error::invalid(
                "measure relationships: shape row has background label 0",
            ));
        }
        let centroid = shape.centroid().ok_or_else(|| {
            Error::invalid(format!(
                "measure relationships: shape row for label {} has no centroid",
                shape.label
            ))
        })?;
        centroids.push((
            shape.label,
            PhysicalPoint3::from_fractional_voxel_center(centroid, spacing),
        ));
    }
    centroids.sort_by_key(|&(label, _)| label);
    for pair in centroids.windows(2) {
        if pair[0].0 == pair[1].0 {
            return Err(Error::invalid(format!(
                "measure relationships: duplicate shape row for label {}",
                pair[0].0
            )));
        }
    }
    let mut out = Vec::new();
    for (index, &(a_label, a_centroid)) in centroids.iter().enumerate() {
        for &(b_label, b_centroid) in &centroids[index + 1..] {
            let delta = a_centroid.delta_to(b_centroid);
            out.push(ObjectRelationshipMeasurements {
                labels: [a_label, b_label],
                centroid_distance: delta.norm(),
                centroid_delta: delta.coords(),
            });
        }
    }
    Ok(out)
}

/// Resident Class F closest-boundary rows for all unordered object pairs.
///
/// Distances are measured between boundary voxel centres in physical units.
/// Touching face-neighbour objects therefore have a distance of one voxel
/// spacing along the contact axis, not zero continuous surface separation.
pub fn object_boundary_distance_relationships(
    labels: ArrayView3<'_, f64>,
    spacing: PhysicalSpacing,
) -> Result<Vec<ObjectBoundaryDistanceMeasurements>> {
    let objects = collect_object_point_sets(labels)?;
    let boundaries = objects
        .values()
        .map(|object| (object.label, object_boundary_points(&object.points)))
        .collect::<Vec<_>>();
    let mut out = Vec::new();
    for (index, (a_label, a_points)) in boundaries.iter().enumerate() {
        for (b_label, b_points) in &boundaries[index + 1..] {
            let a_points = NonEmptySlice::new(a_points).ok_or_else(|| {
                Error::invalid(format!(
                    "measure boundary distances: label {a_label} has no boundary points"
                ))
            })?;
            let b_points = NonEmptySlice::new(b_points).ok_or_else(|| {
                Error::invalid(format!(
                    "measure boundary distances: label {b_label} has no boundary points"
                ))
            })?;
            let (nearest_points, boundary_delta, boundary_distance) =
                closest_point_set_distance(a_points, b_points, spacing);
            out.push(ObjectBoundaryDistanceMeasurements {
                labels: [*a_label, *b_label],
                boundary_distance,
                boundary_delta,
                nearest_points,
            });
        }
    }
    Ok(out)
}

/// Resident Class F expansion-until-adjacent rows for all unordered object pairs.
///
/// This derives the equal expansion radius from exact closest boundary-centre
/// rows. With the current voxel-centre contract, two objects become adjacent
/// when both expand by half of the closest boundary-centre distance. Touching
/// face-neighbour objects therefore report half a voxel spacing along the
/// contact axis.
pub fn object_expansion_until_adjacent_relationships(
    labels: ArrayView3<'_, f64>,
    spacing: PhysicalSpacing,
) -> Result<Vec<ObjectExpansionMeasurements>> {
    let distances = object_boundary_distance_relationships(labels, spacing)?;
    expansion_until_adjacent_relationships_from_boundary_distances(&distances)
}

pub fn expansion_until_adjacent_relationships_from_boundary_distances(
    distances: &[ObjectBoundaryDistanceMeasurements],
) -> Result<Vec<ObjectExpansionMeasurements>> {
    let mut out = Vec::with_capacity(distances.len());
    for distance in distances {
        validate_boundary_distance_relationship_row(distance)?;
        out.push(ObjectExpansionMeasurements {
            labels: distance.labels,
            expansion_distance: distance.boundary_distance / 2.0,
            boundary_distance: distance.boundary_distance,
            nearest_points: distance.nearest_points,
        });
    }
    Ok(out)
}

fn boundary_distance_relationships_from_boundary_points(
    boundaries: &BTreeMap<u64, BTreeSet<[usize; 3]>>,
    spacing: PhysicalSpacing,
) -> Result<Vec<ObjectBoundaryDistanceMeasurements>> {
    let boundary_vec = boundaries
        .iter()
        .map(|(&label, points)| (label, points.iter().copied().collect::<Vec<_>>()))
        .collect::<Vec<_>>();
    let mut out = Vec::new();
    for (index, (a_label, a_points)) in boundary_vec.iter().enumerate() {
        for (b_label, b_points) in &boundary_vec[index + 1..] {
            let a_points = NonEmptySlice::new(a_points).ok_or_else(|| {
                Error::invalid(format!(
                    "measure boundary distances: label {a_label} has no boundary points"
                ))
            })?;
            let b_points = NonEmptySlice::new(b_points).ok_or_else(|| {
                Error::invalid(format!(
                    "measure boundary distances: label {b_label} has no boundary points"
                ))
            })?;
            let (nearest_points, boundary_delta, boundary_distance) =
                closest_point_set_distance(a_points, b_points, spacing);
            out.push(ObjectBoundaryDistanceMeasurements {
                labels: [*a_label, *b_label],
                boundary_distance,
                boundary_delta,
                nearest_points,
            });
        }
    }
    Ok(out)
}

struct LabelPointPartialLayout;

impl LabelPointPartialLayout {
    const MAGIC: u64 = 0x4246_4d45_4c50_5431;
    const VERSION: u64 = 1;
    const HEADER_WORDS: usize = 4;
    const LABEL_WORDS: usize = 2;
    const POINT_WORDS: usize = 3;

    fn encode(points: &BTreeMap<u64, Vec<[usize; 3]>>) -> Result<Vec<u8>> {
        let point_count = checked_partial_item_count(
            points.values().map(Vec::len),
            "measure label-point partial",
        )?;
        let mut words = Vec::with_capacity(variable_partial_capacity(
            Self::HEADER_WORDS,
            points.len(),
            Self::LABEL_WORDS,
            point_count,
            Self::POINT_WORDS,
            "measure label-point partial",
        )?);
        words.push(Self::MAGIC);
        words.push(Self::VERSION);
        words.push(partial_usize_word(
            points.len(),
            "measure label-point partial: label count",
        )?);
        words.push(partial_usize_word(
            point_count,
            "measure label-point partial: point count",
        )?);
        for (&label, label_points) in points {
            words.push(label);
            words.push(partial_usize_word(
                label_points.len(),
                "measure label-point partial: label point count",
            )?);
            for point in label_points {
                push_partial_point3(
                    &mut words,
                    *point,
                    "measure label-point partial: coordinate",
                )?;
            }
        }
        Ok(pack_u64(&words))
    }

    fn decode(bytes: &[u8]) -> Result<Vec<(u64, Vec<[usize; 3]>)>> {
        let words = unpack_u64(bytes)?;
        Self::validate_prefix(&words)?;
        let label_count = partial_word_usize(words[2], "measure label-point partial: label count")?;
        let declared_point_count =
            partial_word_usize(words[3], "measure label-point partial: point count")?;
        let mut offset = Self::HEADER_WORDS;
        let mut decoded = Vec::with_capacity(label_count);
        let mut seen_points = 0usize;
        for _ in 0..label_count {
            if words.len().saturating_sub(offset) < Self::LABEL_WORDS {
                return Err(Error::invalid(
                    "measure label-point partial: label row is truncated",
                ));
            }
            let label = words[offset];
            if label == 0 {
                return Err(Error::invalid(
                    "measure label-point partial: contains background label 0",
                ));
            }
            let point_count = partial_word_usize(
                words[offset + 1],
                "measure label-point partial: label point count",
            )?;
            offset += Self::LABEL_WORDS;
            let point_range = checked_variable_partial_section(
                &words,
                offset,
                point_count,
                Self::POINT_WORDS,
                "measure label-point partial: point section",
            )?;
            let mut points = Vec::with_capacity(point_count);
            for point in words[point_range.clone()].chunks_exact(Self::POINT_WORDS) {
                points.push(partial_point3(
                    point,
                    "measure label-point partial: coordinate",
                )?);
            }
            offset = point_range.end;
            seen_points = seen_points.checked_add(point_count).ok_or_else(|| {
                Error::invalid("measure label-point partial: point count overflow")
            })?;
            decoded.push((label, points));
        }
        if offset != words.len() {
            return Err(Error::invalid(
                "measure label-point partial: trailing words",
            ));
        }
        if seen_points != declared_point_count {
            return Err(Error::invalid(
                "measure label-point partial: point count does not match header",
            ));
        }
        Ok(decoded)
    }
}

impl PartialLayoutContract for LabelPointPartialLayout {
    const MAGIC: u64 = LabelPointPartialLayout::MAGIC;
    const VERSION: u64 = LabelPointPartialLayout::VERSION;
    const HEADER_WORDS: usize = LabelPointPartialLayout::HEADER_WORDS;
    const FORMAT: &'static str = "measure label-point partial";
    const SHORT_ERROR: &'static str = "header is truncated";
    const MAGIC_ERROR: &'static str = "wrong format magic";
    const VERSION_ERROR: &'static str = "unsupported version";
}

struct ObjectGeometryBasicPartialLayout;

impl ObjectGeometryBasicPartialLayout {
    const MAGIC: u64 = 0x4246_4d45_4742_5431;
    const VERSION: u64 = 1;
    const HEADER_WORDS: usize = 3;
    const ROW_WORDS: usize = 8;

    fn encode(tallies: &BTreeMap<u64, ObjectGeometryBasicTally>) -> Result<Vec<u8>> {
        let mut words = Vec::with_capacity(
            Self::HEADER_WORDS
                .checked_add(tallies.len().checked_mul(Self::ROW_WORDS).ok_or_else(|| {
                    Error::invalid("measure geometry basic partial: row section is too large")
                })?)
                .ok_or_else(|| {
                    Error::invalid("measure geometry basic partial: capacity overflowed")
                })?,
        );
        words.push(Self::MAGIC);
        words.push(Self::VERSION);
        words.push(partial_usize_word(
            tallies.len(),
            "measure geometry basic partial: row count",
        )?);
        for tally in tallies.values() {
            if tally.label == 0 {
                return Err(Error::invalid(
                    "measure geometry basic partial: contains background label 0",
                ));
            }
            if tally.count == 0 {
                return Err(Error::invalid(format!(
                    "measure geometry basic partial: row for label {} has zero count",
                    tally.label
                )));
            }
            words.push(tally.label);
            words.push(tally.count);
            push_partial_point3(
                &mut words,
                tally.bbox_min,
                "measure geometry basic partial: bbox_min",
            )?;
            push_partial_point3(
                &mut words,
                tally.bbox_max,
                "measure geometry basic partial: bbox_max",
            )?;
        }
        Ok(pack_u64(&words))
    }

    fn decode(bytes: &[u8]) -> Result<Vec<ObjectGeometryBasicTally>> {
        let words = unpack_u64(bytes)?;
        Self::validate_prefix(&words)?;
        let row_count = partial_word_usize(words[2], "measure geometry basic partial: row count")?;
        let expected_words = Self::HEADER_WORDS
            .checked_add(row_count.checked_mul(Self::ROW_WORDS).ok_or_else(|| {
                Error::invalid("measure geometry basic partial: row section is too large")
            })?)
            .ok_or_else(|| Error::invalid("measure geometry basic partial: length overflowed"))?;
        if words.len() != expected_words {
            return Err(Error::invalid(format!(
                "measure geometry basic partial: expected {expected_words} words, got {}",
                words.len()
            )));
        }
        let mut out = Vec::with_capacity(row_count);
        let mut offset = Self::HEADER_WORDS;
        for _ in 0..row_count {
            let label = words[offset];
            let count = words[offset + 1];
            let bbox_min = partial_point3(
                &words[offset + 2..offset + 5],
                "measure geometry basic partial: bbox_min",
            )?;
            let bbox_max = partial_point3(
                &words[offset + 5..offset + 8],
                "measure geometry basic partial: bbox_max",
            )?;
            offset += Self::ROW_WORDS;
            if label == 0 {
                return Err(Error::invalid(
                    "measure geometry basic partial: contains background label 0",
                ));
            }
            if count == 0 {
                return Err(Error::invalid(format!(
                    "measure geometry basic partial: row for label {label} has zero count"
                )));
            }
            let tally = ObjectGeometryBasicTally {
                label,
                count,
                bbox_min,
                bbox_max,
            };
            validate_object_geometry_basic_row(&tally.into_measurements(PhysicalSpacing::unit()))?;
            out.push(tally);
        }
        Ok(out)
    }
}

impl PartialLayoutContract for ObjectGeometryBasicPartialLayout {
    const MAGIC: u64 = ObjectGeometryBasicPartialLayout::MAGIC;
    const VERSION: u64 = ObjectGeometryBasicPartialLayout::VERSION;
    const HEADER_WORDS: usize = ObjectGeometryBasicPartialLayout::HEADER_WORDS;
    const FORMAT: &'static str = "measure geometry basic partial";
    const SHORT_ERROR: &'static str = "header is truncated";
    const MAGIC_ERROR: &'static str = "wrong format magic";
    const VERSION_ERROR: &'static str = "unsupported version";
}

struct ObjectDirectionalFeretPartialLayout;

impl ObjectDirectionalFeretPartialLayout {
    const MAGIC: u64 = 0x4246_4d45_4446_5431;
    const VERSION: u64 = 1;
    const HEADER_WORDS: usize = 4;
    const ROW_FIXED_WORDS: usize = 8;

    fn row_words(directions: usize) -> Result<usize> {
        Self::ROW_FIXED_WORDS
            .checked_add(directions.checked_mul(2).ok_or_else(|| {
                Error::invalid("measure directional Feret partial: direction section is too large")
            })?)
            .ok_or_else(|| Error::invalid("measure directional Feret partial: row is too large"))
    }

    fn encode(tallies: &BTreeMap<u64, ObjectDirectionalFeretTally>) -> Result<Vec<u8>> {
        let directions = tallies
            .values()
            .next()
            .map(|tally| tally.min_dot.len())
            .unwrap_or(0);
        let row_words = Self::row_words(directions)?;
        let mut words = Vec::with_capacity(
            Self::HEADER_WORDS
                .checked_add(tallies.len().checked_mul(row_words).ok_or_else(|| {
                    Error::invalid("measure directional Feret partial: row section is too large")
                })?)
                .ok_or_else(|| {
                    Error::invalid("measure directional Feret partial: capacity overflowed")
                })?,
        );
        words.push(Self::MAGIC);
        words.push(Self::VERSION);
        words.push(partial_usize_word(
            tallies.len(),
            "measure directional Feret partial: row count",
        )?);
        words.push(partial_usize_word(
            directions,
            "measure directional Feret partial: direction count",
        )?);
        for tally in tallies.values() {
            if tally.label == 0 {
                return Err(Error::invalid(
                    "measure directional Feret partial: contains background label 0",
                ));
            }
            if tally.count == 0 {
                return Err(Error::invalid(format!(
                    "measure directional Feret partial: row for label {} has zero count",
                    tally.label
                )));
            }
            if tally.min_dot.len() != directions || tally.max_dot.len() != directions {
                return Err(Error::invalid(format!(
                    "measure directional Feret partial: row for label {} has wrong direction count",
                    tally.label
                )));
            }
            words.push(tally.label);
            words.push(tally.count);
            push_partial_point3(
                &mut words,
                tally.bbox_min,
                "measure directional Feret partial: bbox_min",
            )?;
            push_partial_point3(
                &mut words,
                tally.bbox_max,
                "measure directional Feret partial: bbox_max",
            )?;
            for index in 0..directions {
                let min = tally.min_dot[index];
                let max = tally.max_dot[index];
                if !min.is_finite() || !max.is_finite() || min > max {
                    return Err(Error::invalid(format!(
                        "measure directional Feret partial: row for label {} has invalid dot range",
                        tally.label
                    )));
                }
                words.push(min.to_bits());
                words.push(max.to_bits());
            }
        }
        Ok(pack_u64(&words))
    }

    fn decode(
        bytes: &[u8],
        expected_directions: usize,
    ) -> Result<Vec<ObjectDirectionalFeretTally>> {
        let words = unpack_u64(bytes)?;
        Self::validate_prefix(&words)?;
        let row_count =
            partial_word_usize(words[2], "measure directional Feret partial: row count")?;
        let directions = partial_word_usize(
            words[3],
            "measure directional Feret partial: direction count",
        )?;
        if directions != expected_directions {
            return Err(Error::invalid(format!(
                "measure directional Feret partial: direction count {directions} does not match expected {expected_directions}"
            )));
        }
        let row_words = Self::row_words(directions)?;
        let expected_words = Self::HEADER_WORDS
            .checked_add(row_count.checked_mul(row_words).ok_or_else(|| {
                Error::invalid("measure directional Feret partial: row section is too large")
            })?)
            .ok_or_else(|| {
                Error::invalid("measure directional Feret partial: length overflowed")
            })?;
        if words.len() != expected_words {
            return Err(Error::invalid(format!(
                "measure directional Feret partial: expected {expected_words} words, got {}",
                words.len()
            )));
        }
        let mut out = Vec::with_capacity(row_count);
        let mut offset = Self::HEADER_WORDS;
        for _ in 0..row_count {
            let label = words[offset];
            let count = words[offset + 1];
            let bbox_min = partial_point3(
                &words[offset + 2..offset + 5],
                "measure directional Feret partial: bbox_min",
            )?;
            let bbox_max = partial_point3(
                &words[offset + 5..offset + 8],
                "measure directional Feret partial: bbox_max",
            )?;
            offset += Self::ROW_FIXED_WORDS;
            if label == 0 {
                return Err(Error::invalid(
                    "measure directional Feret partial: contains background label 0",
                ));
            }
            if count == 0 {
                return Err(Error::invalid(format!(
                    "measure directional Feret partial: row for label {label} has zero count"
                )));
            }
            let mut min_dot = Vec::with_capacity(directions);
            let mut max_dot = Vec::with_capacity(directions);
            for _ in 0..directions {
                let min = f64::from_bits(words[offset]);
                let max = f64::from_bits(words[offset + 1]);
                offset += 2;
                if !min.is_finite() || !max.is_finite() || min > max {
                    return Err(Error::invalid(format!(
                        "measure directional Feret partial: row for label {label} has invalid dot range"
                    )));
                }
                min_dot.push(min);
                max_dot.push(max);
            }
            out.push(ObjectDirectionalFeretTally {
                label,
                count,
                bbox_min,
                bbox_max,
                min_dot,
                max_dot,
            });
        }
        Ok(out)
    }
}

impl PartialLayoutContract for ObjectDirectionalFeretPartialLayout {
    const MAGIC: u64 = ObjectDirectionalFeretPartialLayout::MAGIC;
    const VERSION: u64 = ObjectDirectionalFeretPartialLayout::VERSION;
    const HEADER_WORDS: usize = ObjectDirectionalFeretPartialLayout::HEADER_WORDS;
    const FORMAT: &'static str = "measure directional Feret partial";
    const SHORT_ERROR: &'static str = "header is truncated";
    const MAGIC_ERROR: &'static str = "wrong format magic";
    const VERSION_ERROR: &'static str = "unsupported version";
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
struct OverlapRelationshipTallies {
    pairs: BTreeMap<[u64; 2], u64>,
    label_a: BTreeMap<u64, u64>,
    label_b: BTreeMap<u64, u64>,
}

impl OverlapRelationshipTallies {
    fn add_pair(&mut self, labels: [u64; 2], count: u64) -> Result<()> {
        if labels[0] == 0 || labels[1] == 0 {
            return Err(Error::invalid(
                "measure overlap relationships: overlap pair contains background label 0",
            ));
        }
        checked_add_to_map_count(
            &mut self.pairs,
            labels,
            count,
            "measure overlap relationships: pair count",
        )
    }

    fn add_label_a(&mut self, label: u64, count: u64) -> Result<()> {
        if label == 0 {
            return Err(Error::invalid(
                "measure overlap relationships: source A count contains background label 0",
            ));
        }
        checked_add_to_map_count(
            &mut self.label_a,
            label,
            count,
            "measure overlap relationships: source A count",
        )
    }

    fn add_label_b(&mut self, label: u64, count: u64) -> Result<()> {
        if label == 0 {
            return Err(Error::invalid(
                "measure overlap relationships: source B count contains background label 0",
            ));
        }
        checked_add_to_map_count(
            &mut self.label_b,
            label,
            count,
            "measure overlap relationships: source B count",
        )
    }

    fn merge(&mut self, other: Self) -> Result<()> {
        for (labels, count) in other.pairs {
            self.add_pair(labels, count)?;
        }
        for (label, count) in other.label_a {
            self.add_label_a(label, count)?;
        }
        for (label, count) in other.label_b {
            self.add_label_b(label, count)?;
        }
        Ok(())
    }
}

struct OverlapRelationshipPartialLayout;

impl OverlapRelationshipPartialLayout {
    const MAGIC: u64 = 0x4f56_4c50_5245_4c31;
    const VERSION: u64 = 1;
    const HEADER_WORDS: usize = 5;
    const PAIR_WORDS: usize = 3;
    const LABEL_WORDS: usize = 2;

    fn encode(tallies: &OverlapRelationshipTallies) -> Result<Vec<u8>> {
        let mut words = Vec::with_capacity(variable_partial_capacity(
            Self::HEADER_WORDS,
            tallies.pairs.len(),
            Self::PAIR_WORDS,
            tallies.label_a.len() + tallies.label_b.len(),
            Self::LABEL_WORDS,
            "measure overlap relationships partial",
        )?);
        words.push(Self::MAGIC);
        words.push(Self::VERSION);
        words.push(partial_usize_word(
            tallies.pairs.len(),
            "measure overlap relationships partial: pair count",
        )?);
        words.push(partial_usize_word(
            tallies.label_a.len(),
            "measure overlap relationships partial: source A label count",
        )?);
        words.push(partial_usize_word(
            tallies.label_b.len(),
            "measure overlap relationships partial: source B label count",
        )?);
        for (&labels, &count) in &tallies.pairs {
            if labels[0] == 0 || labels[1] == 0 {
                return Err(Error::invalid(
                    "measure overlap relationships partial: pair contains background label 0",
                ));
            }
            words.push(labels[0]);
            words.push(labels[1]);
            words.push(count);
        }
        for (&label, &count) in &tallies.label_a {
            if label == 0 {
                return Err(Error::invalid(
                    "measure overlap relationships partial: source A contains background label 0",
                ));
            }
            words.push(label);
            words.push(count);
        }
        for (&label, &count) in &tallies.label_b {
            if label == 0 {
                return Err(Error::invalid(
                    "measure overlap relationships partial: source B contains background label 0",
                ));
            }
            words.push(label);
            words.push(count);
        }
        Ok(pack_u64(&words))
    }

    fn decode(bytes: &[u8]) -> Result<OverlapRelationshipTallies> {
        let words = unpack_u64(bytes)?;
        Self::validate_prefix(&words)?;
        let pair_count = partial_word_usize(
            words[2],
            "measure overlap relationships partial: pair count",
        )?;
        let label_a_count = partial_word_usize(
            words[3],
            "measure overlap relationships partial: source A label count",
        )?;
        let label_b_count = partial_word_usize(
            words[4],
            "measure overlap relationships partial: source B label count",
        )?;
        let mut offset = Self::HEADER_WORDS;
        let pair_range = checked_variable_partial_section(
            &words,
            offset,
            pair_count,
            Self::PAIR_WORDS,
            "measure overlap relationships partial: pair section",
        )?;
        offset = pair_range.end;
        let label_a_range = checked_variable_partial_section(
            &words,
            offset,
            label_a_count,
            Self::LABEL_WORDS,
            "measure overlap relationships partial: source A section",
        )?;
        offset = label_a_range.end;
        let label_b_range = checked_variable_partial_section(
            &words,
            offset,
            label_b_count,
            Self::LABEL_WORDS,
            "measure overlap relationships partial: source B section",
        )?;
        if label_b_range.end != words.len() {
            return Err(Error::invalid(
                "measure overlap relationships partial: trailing words",
            ));
        }
        let mut tallies = OverlapRelationshipTallies::default();
        for row in words[pair_range].chunks_exact(Self::PAIR_WORDS) {
            tallies.add_pair([row[0], row[1]], row[2])?;
        }
        for row in words[label_a_range].chunks_exact(Self::LABEL_WORDS) {
            tallies.add_label_a(row[0], row[1])?;
        }
        for row in words[label_b_range].chunks_exact(Self::LABEL_WORDS) {
            tallies.add_label_b(row[0], row[1])?;
        }
        Ok(tallies)
    }
}

impl PartialLayoutContract for OverlapRelationshipPartialLayout {
    const MAGIC: u64 = OverlapRelationshipPartialLayout::MAGIC;
    const VERSION: u64 = OverlapRelationshipPartialLayout::VERSION;
    const HEADER_WORDS: usize = OverlapRelationshipPartialLayout::HEADER_WORDS;
    const FORMAT: &'static str = "measure overlap relationships partial";
}

/// Block-local directed overlap partials between two label sources.
#[derive(Debug, Clone)]
pub struct OverlapRelationshipTallyOp {
    name: &'static str,
    labels_a: TypedSource,
    labels_b: TypedSource,
    stream: String,
    lifecycle: Lifecycle,
}

impl OverlapRelationshipTallyOp {
    pub fn new(
        name: &'static str,
        labels_a: impl Into<ImageId>,
        labels_b: impl Into<ImageId>,
        stream: impl Into<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        let stream = OverlapRelationshipPartialStream::new(stream)?;
        Ok(Self {
            name,
            labels_a: TypedSource::new(labels_a),
            labels_b: TypedSource::new(labels_b),
            stream: stream.as_str().to_string(),
            lifecycle,
        })
    }

    fn tally_block(
        &self,
        labels_a: &BlockBuf,
        labels_b: &BlockBuf,
        read: &Region,
        core: &Region,
    ) -> Result<OverlapRelationshipTallies> {
        let mut tallies = OverlapRelationshipTallies::default();
        let BlockBuf::Array(labels_a) = labels_a else {
            return Ok(tallies);
        };
        let BlockBuf::Array(labels_b) = labels_b else {
            return Ok(tallies);
        };
        expect_extent(
            || {
                format!(
                    "measure overlap relationships: source A labels arrived as {:?} for a block \
                     read extent of {:?}",
                    labels_a.shape(),
                    read.shape3()
                )
            },
            read.shape3(),
            labels_a.shape(),
        )?;
        expect_extent(
            || {
                format!(
                    "measure overlap relationships: source B labels arrived as {:?} for a block \
                     read extent of {:?}",
                    labels_b.shape(),
                    read.shape3()
                )
            },
            read.shape3(),
            labels_b.shape(),
        )?;
        let labels_a = labels_a.widened();
        let labels_b = labels_b.widened();
        for (index, raw_a) in labels_a.indexed_iter() {
            let at = [
                read.start[0] + index.0,
                read.start[1] + index.1,
                read.start[2] + index.2,
            ];
            if !in_region(core, at) {
                continue;
            }
            let label_a = label_value(*raw_a, at)?;
            let label_b = label_value(labels_b[index], at)?;
            if label_a != 0 {
                tallies.add_label_a(label_a, 1)?;
            }
            if label_b != 0 {
                tallies.add_label_b(label_b, 1)?;
            }
            if label_a != 0 && label_b != 0 {
                tallies.add_pair([label_a, label_b], 1)?;
            }
        }
        Ok(tallies)
    }
}

impl FragmentOp for OverlapRelationshipTallyOp {
    fn name(&self) -> &'static str {
        self.name
    }

    fn reach(&self, _axis: usize, _volume_len: usize) -> usize {
        0
    }

    fn source_inputs(&self, _volume: [usize; 3]) -> Vec<SourceInput> {
        vec![
            CoreBlockSourceRead::new(self.labels_a).source_input(),
            CoreBlockSourceRead::new(self.labels_b).source_input(),
        ]
    }

    fn outputs(&self) -> Vec<FragmentOutput> {
        vec![FragmentOutput::new(
            self.stream.clone(),
            self.lifecycle,
            Coverage::EveryBlock,
        )]
    }

    fn seam_fold(&self) -> Option<SeamFold> {
        MeasurementSeamLaw::per_block().seam_fold()
    }

    fn apply(&self, _at: &BlockView<'_>) -> Result<BlockOutput> {
        Err(Error::invalid(
            "measure overlap relationships: overlap partials read label sources and are applied \
             through `apply_with`",
        ))
    }

    fn apply_with(&self, at: &BlockView<'_>, sources: SourceBlocks<'_>) -> Result<BlockOutput> {
        let tallies = self.tally_block(
            self.labels_a
                .block_at_extent(self.name, "source A label volume", sources, at.read)?,
            self.labels_b
                .block_at_extent(self.name, "source B label volume", sources, at.read)?,
            at.read,
            at.core,
        )?;
        Ok(BlockOutput::fragment(
            self.stream.clone(),
            OverlapRelationshipPartialLayout::encode(&tallies)?,
        ))
    }
}

/// Merge directed overlap partials into relationship rows.
#[derive(Debug, Clone)]
pub struct MergeOverlapRelationshipsOp {
    name: &'static str,
    input: PartialPhaseInput,
    schema: Arc<Schema>,
    stream: String,
    lifecycle: Lifecycle,
}

impl MergeOverlapRelationshipsOp {
    pub fn new(
        name: &'static str,
        input: impl Into<String>,
        input_phase: usize,
        lattice: [usize; 3],
        stream: impl Into<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        let input = OverlapRelationshipPartialStream::new(input)?;
        let stream = OverlapRelationshipOutputStream::new(stream)?;
        Ok(Self {
            name,
            input: PartialPhaseInput::try_new(&input, input_phase, lattice)?,
            schema: Arc::new(overlap_relationship_measurement_schema()),
            stream: stream.as_str().to_string(),
            lifecycle,
        })
    }

    fn merge_partials(&self, partials: &[Vec<u8>]) -> Result<OverlapRelationshipTallies> {
        let mut merged = OverlapRelationshipTallies::default();
        for bytes in partials {
            merged.merge(OverlapRelationshipPartialLayout::decode(bytes)?)?;
        }
        Ok(merged)
    }

    fn relationships(
        &self,
        tallies: &OverlapRelationshipTallies,
    ) -> Result<Vec<ObjectOverlapMeasurements>> {
        overlap_relationships_from_tallies(tallies)
    }

    fn encode_owned(
        &self,
        relationships: &[ObjectOverlapMeasurements],
        blocks: BlockLattice,
        block: [usize; 3],
    ) -> Result<Vec<u8>> {
        let mut rows = RowBuilder::new(Arc::clone(&self.schema));
        for relationship in relationships {
            let owner = directed_relationship_pair_owner(blocks, relationship.labels)?;
            if owner != block {
                continue;
            }
            rows.push(
                [0, 0, 0],
                &OverlapRelationshipColumns::values(relationship)?,
            )?;
        }
        Ok(rows.encode())
    }
}

impl FragmentOp for MergeOverlapRelationshipsOp {
    fn name(&self) -> &'static str {
        self.name
    }

    fn reach(&self, _axis: usize, _volume_len: usize) -> usize {
        0
    }

    fn inputs(&self) -> Vec<FragmentInput> {
        vec![self.input.fragment_input()]
    }

    fn gathers(&self) -> bool {
        false
    }

    fn outputs(&self) -> Vec<FragmentOutput> {
        vec![
            FragmentOutput::new(self.stream.clone(), self.lifecycle, Coverage::EveryBlock)
                .sized(SidecarSize::row_table(self.schema.as_ref(), 1)),
        ]
    }

    fn seam_fold(&self) -> Option<SeamFold> {
        MeasurementSeamLaw::unordered_exact().seam_fold()
    }

    fn apply(&self, at: &BlockView<'_>) -> Result<BlockOutput> {
        let partials = self.input.stream_fragments(at)?;
        let tallies = self.merge_partials(&partials)?;
        let relationships = self.relationships(&tallies)?;
        Ok(BlockOutput::fragment(
            self.stream.clone(),
            self.encode_owned(
                &relationships,
                BlockLattice::new(at.grid.blocks_per_axis())?,
                at.index,
            )?,
        ))
    }
}

/// Block-local object boundary point partials for relationship measurements.
#[derive(Debug, Clone)]
pub struct BoundaryPointTallyOp {
    name: &'static str,
    labels: TypedSource,
    stream: String,
    lifecycle: Lifecycle,
}

impl BoundaryPointTallyOp {
    pub fn new(
        name: &'static str,
        labels: impl Into<ImageId>,
        stream: impl Into<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        let stream = BoundaryPointPartialStream::new(stream)?;
        Ok(Self {
            name,
            labels: TypedSource::new(labels),
            stream: stream.as_str().to_string(),
            lifecycle,
        })
    }

    pub fn holding(mut self, labels: Dtype) -> Self {
        self.labels = self.labels.holding(labels);
        self
    }

    pub fn stream(&self) -> &str {
        &self.stream
    }

    fn tally_block(
        &self,
        labels: &BlockBuf,
        read: &Region,
        core: &Region,
        volume: [usize; 3],
    ) -> Result<BTreeMap<u64, Vec<[usize; 3]>>> {
        let mut boundary_points = BTreeMap::<u64, Vec<[usize; 3]>>::new();
        let BlockBuf::Array(labels) = labels else {
            return Ok(boundary_points);
        };
        expect_extent(
            || {
                format!(
                    "measure relationships: the label volume arrived as {:?} for a block read \
                     extent of {:?}",
                    labels.shape(),
                    read.shape3()
                )
            },
            read.shape3(),
            labels.shape(),
        )?;
        let labels = labels.widened();
        let offsets = connectivity_offsets(Connectivity::Faces);
        for (index, raw) in labels.indexed_iter() {
            let at = [
                read.start[0] + index.0,
                read.start[1] + index.1,
                read.start[2] + index.2,
            ];
            if !in_region(core, at) {
                continue;
            }
            let label = label_value(*raw, at)?;
            if label == 0 {
                continue;
            }
            let mut boundary = false;
            for &offset in &offsets {
                let Some(neighbour) = offset_point(at, offset) else {
                    boundary = true;
                    break;
                };
                if (0..3).any(|axis| neighbour[axis] >= volume[axis]) {
                    boundary = true;
                    break;
                }
                let local = [
                    neighbour[0] - read.start[0],
                    neighbour[1] - read.start[1],
                    neighbour[2] - read.start[2],
                ];
                let other = label_value(labels[local], neighbour)?;
                if other != label {
                    boundary = true;
                    break;
                }
            }
            if boundary {
                boundary_points.entry(label).or_default().push(at);
            }
        }
        Ok(boundary_points)
    }
}

impl FragmentOp for BoundaryPointTallyOp {
    fn name(&self) -> &'static str {
        self.name
    }

    fn reach(&self, _axis: usize, _volume_len: usize) -> usize {
        0
    }

    fn source_inputs(&self, _volume: [usize; 3]) -> Vec<SourceInput> {
        vec![OneVoxelLabelHalo::new(self.labels).source_input()]
    }

    fn outputs(&self) -> Vec<FragmentOutput> {
        vec![FragmentOutput::new(
            self.stream.clone(),
            self.lifecycle,
            Coverage::EveryBlock,
        )]
    }

    fn seam_fold(&self) -> Option<SeamFold> {
        MeasurementSeamLaw::per_block().seam_fold()
    }

    fn apply(&self, _at: &BlockView<'_>) -> Result<BlockOutput> {
        Err(Error::invalid(
            "measure relationships: boundary-point partials read the label source and are applied \
             through `apply_with`",
        ))
    }

    fn apply_with(&self, at: &BlockView<'_>, sources: SourceBlocks<'_>) -> Result<BlockOutput> {
        let points = self.tally_block(
            self.labels
                .block_at_extent(self.name, "label volume", sources, at.read)?,
            at.read,
            at.core,
            at.grid.volume(),
        )?;
        Ok(BlockOutput::fragment(
            self.stream.clone(),
            LabelPointPartialLayout::encode(&points)?,
        ))
    }
}

/// Merge boundary-point partials into closest-boundary relationship rows.
#[derive(Debug, Clone)]
pub struct MergeBoundaryDistanceRelationshipsOp {
    name: &'static str,
    input: PartialPhaseInput,
    spacing: PhysicalSpacing,
    schema: Arc<Schema>,
    stream: String,
    lifecycle: Lifecycle,
}

impl MergeBoundaryDistanceRelationshipsOp {
    pub fn new(
        name: &'static str,
        input: impl Into<String>,
        input_phase: usize,
        lattice: [usize; 3],
        spacing: PhysicalSpacing,
        stream: impl Into<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        let input = BoundaryPointPartialStream::new(input)?;
        let stream = BoundaryDistanceRelationshipOutputStream::new(stream)?;
        Ok(Self {
            name,
            input: PartialPhaseInput::try_new(&input, input_phase, lattice)?,
            spacing,
            schema: Arc::new(boundary_distance_relationship_measurement_schema()),
            stream: stream.as_str().to_string(),
            lifecycle,
        })
    }

    fn encode_owned(
        &self,
        boundaries: &BTreeMap<u64, BTreeSet<[usize; 3]>>,
        blocks: BlockLattice,
        block: [usize; 3],
    ) -> Result<Vec<u8>> {
        let relationships =
            boundary_distance_relationships_from_boundary_points(boundaries, self.spacing)?;
        let mut rows = RowBuilder::new(Arc::clone(&self.schema));
        for relationship in relationships {
            let labels = CanonicalRelationshipPair::new(
                relationship.labels,
                "measure relationships: boundary-distance row",
            )?;
            if relationship_pair_owner(blocks, labels)? != block {
                continue;
            }
            validate_boundary_distance_relationship_row(&relationship)?;
            rows.push(
                [0, 0, 0],
                &BoundaryDistanceRelationshipColumns::values(&relationship)?,
            )?;
        }
        Ok(rows.encode())
    }
}

