impl GlcmTextureMeasurements {
    fn matrix_shape(&self) -> Option<GlcmMatrixShape> {
        GlcmMatrixShape::new(self.levels, self.matrix.len())
    }

    fn probability_sum(&self, f: impl Fn(usize, usize) -> f64) -> Option<f64> {
        if self.pairs == 0 {
            return None;
        }
        let shape = self.matrix_shape()?;
        let levels = shape.levels();
        let total = self.pairs as f64;
        Some(
            self.matrix
                .iter()
                .copied()
                .enumerate()
                .filter(|&(_, count)| count != 0)
                .map(|(index, count)| {
                    let i = index / levels;
                    let j = index % levels;
                    count as f64 / total * f(i, j)
                })
                .sum(),
        )
    }

    fn means(&self) -> Option<(f64, f64)> {
        if self.pairs == 0 {
            return None;
        }
        let shape = self.matrix_shape()?;
        let levels = shape.levels();
        let total = self.pairs as f64;
        let mut mean_i = 0.0;
        let mut mean_j = 0.0;
        for (index, &count) in self.matrix.iter().enumerate() {
            let p = count as f64 / total;
            mean_i += (index / levels) as f64 * p;
            mean_j += (index % levels) as f64 * p;
        }
        Some((mean_i, mean_j))
    }

    pub fn contrast(&self) -> Option<f64> {
        self.probability_sum(|i, j| {
            let delta = i as f64 - j as f64;
            delta * delta
        })
    }

    pub fn dissimilarity(&self) -> Option<f64> {
        self.probability_sum(|i, j| i.abs_diff(j) as f64)
    }

    pub fn homogeneity(&self) -> Option<f64> {
        self.probability_sum(|i, j| 1.0 / (1.0 + i.abs_diff(j) as f64))
    }

    pub fn inverse_difference_moment(&self) -> Option<f64> {
        self.probability_sum(|i, j| {
            let delta = i.abs_diff(j) as f64;
            1.0 / (1.0 + delta * delta)
        })
    }

    pub fn inverse_difference_normalized(&self) -> Option<f64> {
        let levels = self.matrix_shape()?.levels() as f64;
        self.probability_sum(|i, j| 1.0 / (1.0 + i.abs_diff(j) as f64 / levels))
    }

    pub fn inverse_difference_moment_normalized(&self) -> Option<f64> {
        let levels = self.matrix_shape()?.levels() as f64;
        self.probability_sum(|i, j| {
            let scaled = i.abs_diff(j) as f64 / levels;
            1.0 / (1.0 + scaled * scaled)
        })
    }

    pub fn angular_second_moment(&self) -> Option<f64> {
        if self.pairs == 0 {
            return None;
        }
        self.matrix_shape()?;
        let total = self.pairs as f64;
        Some(
            self.matrix
                .iter()
                .map(|&count| {
                    let p = count as f64 / total;
                    p * p
                })
                .sum(),
        )
    }

    pub fn energy(&self) -> Option<f64> {
        self.angular_second_moment().map(f64::sqrt)
    }

    pub fn max_probability(&self) -> Option<f64> {
        if self.pairs == 0 {
            return None;
        }
        self.matrix_shape()?;
        let total = self.pairs as f64;
        self.matrix
            .iter()
            .copied()
            .max()
            .map(|count| count as f64 / total)
    }

    pub fn entropy(&self) -> Option<f64> {
        if self.pairs == 0 {
            return None;
        }
        self.matrix_shape()?;
        let total = self.pairs as f64;
        Some(
            self.matrix
                .iter()
                .copied()
                .filter(|&count| count != 0)
                .map(|count| {
                    let p = count as f64 / total;
                    -p * p.log2()
                })
                .sum(),
        )
    }

    pub fn variance(&self) -> Option<f64> {
        let (mean_i, _) = self.means()?;
        self.probability_sum(|i, _| {
            let delta = i as f64 - mean_i;
            delta * delta
        })
    }

    pub fn autocorrelation(&self) -> Option<f64> {
        self.probability_sum(|i, j| i as f64 * j as f64)
    }

    pub fn cluster_shade(&self) -> Option<f64> {
        let (mean_i, mean_j) = self.means()?;
        self.probability_sum(|i, j| (i as f64 + j as f64 - mean_i - mean_j).powi(3))
    }

    pub fn cluster_tendency(&self) -> Option<f64> {
        let (mean_i, mean_j) = self.means()?;
        self.probability_sum(|i, j| (i as f64 + j as f64 - mean_i - mean_j).powi(2))
    }

    pub fn cluster_prominence(&self) -> Option<f64> {
        let (mean_i, mean_j) = self.means()?;
        self.probability_sum(|i, j| (i as f64 + j as f64 - mean_i - mean_j).powi(4))
    }

    pub fn sum_average(&self) -> Option<f64> {
        let sum_probs = self.sum_probabilities()?;
        Some(
            sum_probs
                .iter()
                .enumerate()
                .map(|(sum, &p)| sum as f64 * p)
                .sum(),
        )
    }

    pub fn sum_variance(&self) -> Option<f64> {
        let average = self.sum_average()?;
        let sum_probs = self.sum_probabilities()?;
        Some(
            sum_probs
                .iter()
                .enumerate()
                .map(|(sum, &p)| {
                    let delta = sum as f64 - average;
                    delta * delta * p
                })
                .sum(),
        )
    }

    pub fn sum_entropy(&self) -> Option<f64> {
        let sum_probs = self.sum_probabilities()?;
        Some(entropy_from_probabilities(&sum_probs))
    }

    pub fn difference_average(&self) -> Option<f64> {
        let diff_probs = self.difference_probabilities()?;
        Some(
            diff_probs
                .iter()
                .enumerate()
                .map(|(diff, &p)| diff as f64 * p)
                .sum(),
        )
    }

    pub fn difference_variance(&self) -> Option<f64> {
        let diff_probs = self.difference_probabilities()?;
        let mean = self.difference_average()?;
        Some(
            diff_probs
                .iter()
                .enumerate()
                .map(|(diff, &p)| {
                    let delta = diff as f64 - mean;
                    delta * delta * p
                })
                .sum(),
        )
    }

    pub fn difference_entropy(&self) -> Option<f64> {
        let diff_probs = self.difference_probabilities()?;
        Some(entropy_from_probabilities(&diff_probs))
    }

    fn sum_probabilities(&self) -> Option<Vec<f64>> {
        if self.pairs == 0 {
            return None;
        }
        let shape = self.matrix_shape()?;
        let levels = shape.levels();
        let mut out = vec![0.0; shape.doubled_level_sums_len()?];
        let total = self.pairs as f64;
        for (index, &count) in self.matrix.iter().enumerate() {
            if count == 0 {
                continue;
            }
            out[index / levels + index % levels] += count as f64 / total;
        }
        Some(out)
    }

    fn difference_probabilities(&self) -> Option<Vec<f64>> {
        if self.pairs == 0 {
            return None;
        }
        let shape = self.matrix_shape()?;
        let levels = shape.levels();
        let mut out = vec![0.0; levels];
        let total = self.pairs as f64;
        for (index, &count) in self.matrix.iter().enumerate() {
            if count == 0 {
                continue;
            }
            out[(index / levels).abs_diff(index % levels)] += count as f64 / total;
        }
        Some(out)
    }

    pub fn correlation(&self) -> Option<f64> {
        let (mean_i, mean_j) = self.means()?;
        let shape = self.matrix_shape()?;
        let levels = shape.levels();
        let total = self.pairs as f64;
        let mut cov = 0.0;
        let mut var_i = 0.0;
        let mut var_j = 0.0;
        for (index, &count) in self.matrix.iter().enumerate() {
            let p = count as f64 / total;
            let di = (index / levels) as f64 - mean_i;
            let dj = (index % levels) as f64 - mean_j;
            cov += di * dj * p;
            var_i += di * di * p;
            var_j += dj * dj * p;
        }
        let denom = (var_i * var_j).sqrt();
        (denom > 0.0).then_some(cov / denom)
    }

    pub fn information_measure_correlation_1(&self) -> Option<f64> {
        let (px, py) = self.marginal_probabilities()?;
        let hx = entropy_from_probabilities(&px);
        let hy = entropy_from_probabilities(&py);
        let hxy = self.entropy()?;
        let hxy1 = self.cross_entropy_from_marginals(&px, &py)?;
        let denom = hx.max(hy);
        (denom > 0.0).then_some((hxy - hxy1) / denom)
    }

    pub fn information_measure_correlation_2(&self) -> Option<f64> {
        let (px, py) = self.marginal_probabilities()?;
        let hxy = self.entropy()?;
        let hxy2 = joint_entropy_from_marginals(&px, &py);
        Some((1.0 - 2.0f64.powf(-2.0 * (hxy2 - hxy))).max(0.0).sqrt())
    }

    pub fn maximal_correlation_coefficient(&self) -> Option<f64> {
        let shape = self.matrix_shape()?;
        let levels = shape.levels();
        let (px, py) = self.marginal_probabilities()?;
        let active_x: Vec<_> = px
            .iter()
            .copied()
            .enumerate()
            .filter_map(|(level, p)| (p > 0.0).then_some((level, p)))
            .collect();
        if active_x.len() < 2 {
            return None;
        }

        let total = self.pairs as f64;
        let normalized_len = active_x.len().checked_mul(active_x.len())?;
        let mut normalized = vec![0.0; normalized_len];
        for (row, &(i, px_i)) in active_x.iter().enumerate() {
            for (col, &(j, px_j)) in active_x.iter().enumerate() {
                let mut value = 0.0;
                for (k, &py_k) in py.iter().enumerate() {
                    if py_k == 0.0 {
                        continue;
                    }
                    let p_ik = self.matrix[i * levels + k] as f64 / total;
                    let p_jk = self.matrix[j * levels + k] as f64 / total;
                    value += p_ik * p_jk / (py_k * (px_i * px_j).sqrt());
                }
                normalized[row * active_x.len() + col] = value;
            }
        }

        let mut eigenvalues = symmetric_eigenvalues_jacobi(normalized, active_x.len())?;
        eigenvalues.sort_by(|a, b| b.total_cmp(a));
        eigenvalues
            .get(1)
            .copied()
            .map(|lambda| lambda.max(0.0).sqrt())
    }

    pub fn feature(&self, feature: GlcmTextureFeature) -> Option<f64> {
        match feature {
            GlcmTextureFeature::Contrast => self.contrast(),
            GlcmTextureFeature::Dissimilarity => self.dissimilarity(),
            GlcmTextureFeature::Homogeneity => self.homogeneity(),
            GlcmTextureFeature::InverseDifferenceMoment => self.inverse_difference_moment(),
            GlcmTextureFeature::InverseDifferenceNormalized => self.inverse_difference_normalized(),
            GlcmTextureFeature::InverseDifferenceMomentNormalized => {
                self.inverse_difference_moment_normalized()
            }
            GlcmTextureFeature::AngularSecondMoment => self.angular_second_moment(),
            GlcmTextureFeature::Energy => self.energy(),
            GlcmTextureFeature::MaxProbability => self.max_probability(),
            GlcmTextureFeature::Entropy => self.entropy(),
            GlcmTextureFeature::Variance => self.variance(),
            GlcmTextureFeature::Autocorrelation => self.autocorrelation(),
            GlcmTextureFeature::ClusterShade => self.cluster_shade(),
            GlcmTextureFeature::ClusterTendency => self.cluster_tendency(),
            GlcmTextureFeature::ClusterProminence => self.cluster_prominence(),
            GlcmTextureFeature::SumAverage => self.sum_average(),
            GlcmTextureFeature::SumVariance => self.sum_variance(),
            GlcmTextureFeature::SumEntropy => self.sum_entropy(),
            GlcmTextureFeature::DifferenceAverage => self.difference_average(),
            GlcmTextureFeature::DifferenceVariance => self.difference_variance(),
            GlcmTextureFeature::DifferenceEntropy => self.difference_entropy(),
            GlcmTextureFeature::Correlation => self.correlation(),
            GlcmTextureFeature::InformationMeasureCorrelation1 => {
                self.information_measure_correlation_1()
            }
            GlcmTextureFeature::InformationMeasureCorrelation2 => {
                self.information_measure_correlation_2()
            }
            GlcmTextureFeature::MaximalCorrelationCoefficient => {
                self.maximal_correlation_coefficient()
            }
        }
    }

    fn marginal_probabilities(&self) -> Option<(Vec<f64>, Vec<f64>)> {
        if self.pairs == 0 {
            return None;
        }
        let shape = self.matrix_shape()?;
        let levels = shape.levels();
        let total = self.pairs as f64;
        let mut px = vec![0.0; levels];
        let mut py = vec![0.0; levels];
        for (index, &count) in self.matrix.iter().enumerate() {
            if count == 0 {
                continue;
            }
            let p = count as f64 / total;
            px[index / levels] += p;
            py[index % levels] += p;
        }
        Some((px, py))
    }

    fn cross_entropy_from_marginals(&self, px: &[f64], py: &[f64]) -> Option<f64> {
        if self.pairs == 0 {
            return None;
        }
        let shape = self.matrix_shape()?;
        let levels = shape.levels();
        let total = self.pairs as f64;
        Some(
            self.matrix
                .iter()
                .copied()
                .enumerate()
                .filter(|&(_, count)| count != 0)
                .map(|(index, count)| {
                    let joint = count as f64 / total;
                    let marginal = px[index / levels] * py[index % levels];
                    -joint * marginal.log2()
                })
                .sum(),
        )
    }
}

fn symmetric_eigenvalues_jacobi(mut matrix: Vec<f64>, n: usize) -> Option<Vec<f64>> {
    if n.checked_mul(n)? != matrix.len() {
        return None;
    }
    if n == 0 {
        return Some(Vec::new());
    }
    let max_sweeps = n.checked_mul(n)?.checked_mul(16)?;
    for _ in 0..max_sweeps {
        let mut pivot = None;
        let mut pivot_abs = 0.0;
        for row in 0..n {
            for col in (row + 1)..n {
                let value = matrix[row * n + col].abs();
                if value > pivot_abs {
                    pivot = Some((row, col));
                    pivot_abs = value;
                }
            }
        }
        let Some((p, q)) = pivot else {
            break;
        };
        if pivot_abs <= 1.0e-14 {
            break;
        }

        let app = matrix[p * n + p];
        let aqq = matrix[q * n + q];
        let apq = matrix[p * n + q];
        let tau = (aqq - app) / (2.0 * apq);
        let sign = if tau >= 0.0 { 1.0 } else { -1.0 };
        let t = sign / (tau.abs() + (1.0 + tau * tau).sqrt());
        let c = 1.0 / (1.0 + t * t).sqrt();
        let s = t * c;

        for k in 0..n {
            if k == p || k == q {
                continue;
            }
            let akp = matrix[k * n + p];
            let akq = matrix[k * n + q];
            let next_kp = c * akp - s * akq;
            let next_kq = s * akp + c * akq;
            matrix[k * n + p] = next_kp;
            matrix[p * n + k] = next_kp;
            matrix[k * n + q] = next_kq;
            matrix[q * n + k] = next_kq;
        }

        matrix[p * n + p] = c * c * app - 2.0 * s * c * apq + s * s * aqq;
        matrix[q * n + q] = s * s * app + 2.0 * s * c * apq + c * c * aqq;
        matrix[p * n + q] = 0.0;
        matrix[q * n + p] = 0.0;
    }

    Some((0..n).map(|i| matrix[i * n + i]).collect())
}

fn entropy_from_probabilities(probabilities: &[f64]) -> f64 {
    probabilities
        .iter()
        .copied()
        .filter(|&p| p > 0.0)
        .map(|p| -p * p.log2())
        .sum()
}

fn joint_entropy_from_marginals(px: &[f64], py: &[f64]) -> f64 {
    px.iter()
        .copied()
        .filter(|&x| x > 0.0)
        .flat_map(|x| py.iter().copied().filter(|&y| y > 0.0).map(move |y| x * y))
        .map(|p| -p * p.log2())
        .sum()
}

/// Resident directed-offset GLCM texture measurement inside each label.
///
/// Candidate pairs are counted only when both voxels have the same non-zero
/// label. The offset is directed; callers that need a symmetric GLCM can request
/// both directions and combine the matrices explicitly.
pub fn glcm_texture_measurements(
    labels: ArrayView3<'_, f64>,
    values: ArrayView3<'_, f64>,
    quantization: GlcmQuantization,
    offset: GlcmOffset,
) -> Result<Vec<GlcmTextureMeasurements>> {
    if labels.shape() != values.shape() {
        return Err(Error::invalid(format!(
            "measure texture: label and value volumes must have the same shape, got {:?} and {:?}",
            labels.shape(),
            values.shape()
        )));
    }
    let shape = labels.shape();
    let shape = [shape[0], shape[1], shape[2]];
    let offset_axes = offset.axes();
    let mut tallies = BTreeMap::<u64, GlcmTally>::new();
    for ((z, y, x), &raw_label) in labels.indexed_iter() {
        let at = [z, y, x];
        let Some(neighbour) = offset_position(at, offset_axes, shape) else {
            continue;
        };
        let label = label_value(raw_label, at)?;
        if label == 0 {
            continue;
        }
        let neighbour_label = label_value(labels[neighbour], neighbour)?;
        if neighbour_label != label {
            continue;
        }
        let entry = tallies
            .entry(label)
            .or_insert_with(|| GlcmTally::new(label, quantization));
        match (
            quantization.quantize(values[[z, y, x]])?,
            quantization.quantize(values[neighbour])?,
        ) {
            (Some(a), Some(b)) => entry.add_pair(a, b, quantization.levels())?,
            _ => entry.add_excluded()?,
        }
    }
    Ok(tallies
        .into_values()
        .map(|tally| GlcmTextureMeasurements {
            label: tally.label,
            levels: quantization.levels(),
            offset: offset_axes,
            pairs: tally.pairs,
            excluded: tally.excluded,
            matrix: tally.matrix,
        })
        .collect())
}

/// Fuse compatible resident GLCM rows for the same label across offsets.
///
/// This is the resident multi-distance texture slice: callers can compute rows
/// for several directed offsets and combine their primitive matrices before
/// deriving Haralick-style scalars. Rows are validated so level counts, matrix
/// dimensions, pair counts and duplicate offsets cannot silently corrupt the
/// fused distribution.
pub fn fuse_glcm_texture_measurements(
    rows: &[GlcmTextureMeasurements],
) -> Result<Vec<FusedGlcmTextureMeasurements>> {
    let mut fused = BTreeMap::<u64, FusedGlcmTextureMeasurements>::new();
    for row in rows {
        validate_glcm_row(row)?;
        let entry = fused
            .entry(row.label)
            .or_insert_with(|| FusedGlcmTextureMeasurements {
                label: row.label,
                levels: row.levels,
                offsets: Vec::new(),
                pairs: 0,
                excluded: 0,
                matrix: vec![0; row.matrix.len()],
            });
        if entry.levels != row.levels || entry.matrix.len() != row.matrix.len() {
            return Err(Error::invalid(format!(
                "measure texture: label {} has incompatible GLCM levels {} and {}",
                row.label, entry.levels, row.levels
            )));
        }
        if entry.offsets.contains(&row.offset) {
            return Err(Error::invalid(format!(
                "measure texture: label {} has duplicate GLCM offset {:?}",
                row.label, row.offset
            )));
        }
        entry.offsets.push(row.offset);
        entry.pairs = entry
            .pairs
            .checked_add(row.pairs)
            .ok_or_else(|| Error::invalid("measure texture: fused GLCM pair count overflowed"))?;
        entry.excluded = entry.excluded.checked_add(row.excluded).ok_or_else(|| {
            Error::invalid("measure texture: fused GLCM exclusion count overflowed")
        })?;
        for (mine, theirs) in entry.matrix.iter_mut().zip(&row.matrix) {
            *mine = mine.checked_add(*theirs).ok_or_else(|| {
                Error::invalid("measure texture: fused GLCM matrix count overflowed")
            })?;
        }
    }
    Ok(fused.into_values().collect())
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct PlannedGlcmTally {
    label: u64,
    candidates: u64,
    position: [u64; 3],
    pairs: u64,
    excluded: u64,
    matrix: Vec<u64>,
}

impl PlannedGlcmTally {
    fn new(label: u64, quantization: GlcmQuantization) -> Self {
        Self {
            label,
            candidates: 0,
            position: [0; 3],
            pairs: 0,
            excluded: 0,
            matrix: vec![0; quantization.matrix_len()],
        }
    }

    fn add_candidate(&mut self, at: [usize; 3]) -> Result<()> {
        self.candidates = self
            .candidates
            .checked_add(1)
            .ok_or_else(|| Error::invalid("measure texture: GLCM candidate count overflowed"))?;
        for (axis, coordinate) in at.into_iter().enumerate() {
            let coordinate =
                usize_coordinate(coordinate, "measure texture: GLCM coordinate component")?;
            self.position[axis] = self.position[axis]
                .checked_add(coordinate)
                .ok_or_else(|| Error::invalid("measure texture: GLCM coordinate sum overflowed"))?;
        }
        Ok(())
    }

    fn add_pair(&mut self, a: usize, b: usize, levels: usize) -> Result<()> {
        let index = a
            .checked_mul(levels)
            .and_then(|base| base.checked_add(b))
            .ok_or_else(|| Error::invalid("measure texture: GLCM matrix index overflowed"))?;
        self.matrix[index] = self.matrix[index]
            .checked_add(1)
            .ok_or_else(|| Error::invalid("measure texture: GLCM bin count overflowed"))?;
        self.pairs = self
            .pairs
            .checked_add(1)
            .ok_or_else(|| Error::invalid("measure texture: GLCM pair count overflowed"))?;
        Ok(())
    }

    fn add_excluded(&mut self) -> Result<()> {
        self.excluded = self
            .excluded
            .checked_add(1)
            .ok_or_else(|| Error::invalid("measure texture: GLCM exclusion count overflowed"))?;
        Ok(())
    }

    fn merge_exact(&mut self, other: ExactReduction<&Self>) -> Result<()> {
        let other = other.into_inner();
        if self.label != other.label {
            return Err(Error::invalid(format!(
                "measure texture: cannot merge GLCM labels {} and {}",
                self.label, other.label
            )));
        }
        if self.matrix.len() != other.matrix.len() {
            return Err(Error::invalid(format!(
                "measure texture: GLCM matrix length mismatch for label {}",
                self.label
            )));
        }
        self.candidates = self
            .candidates
            .checked_add(other.candidates)
            .ok_or_else(|| Error::invalid("measure texture: GLCM candidate count overflowed"))?;
        self.pairs = self
            .pairs
            .checked_add(other.pairs)
            .ok_or_else(|| Error::invalid("measure texture: GLCM pair count overflowed"))?;
        self.excluded = self
            .excluded
            .checked_add(other.excluded)
            .ok_or_else(|| Error::invalid("measure texture: GLCM exclusion count overflowed"))?;
        for axis in 0..3 {
            self.position[axis] = self.position[axis]
                .checked_add(other.position[axis])
                .ok_or_else(|| Error::invalid("measure texture: GLCM coordinate sum overflowed"))?;
        }
        for (mine, theirs) in self.matrix.iter_mut().zip(&other.matrix) {
            *mine = mine
                .checked_add(*theirs)
                .ok_or_else(|| Error::invalid("measure texture: GLCM bin count overflowed"))?;
        }
        Ok(())
    }

    fn centroid(&self) -> Option<[usize; 3]> {
        rounded_centroid_coordinate(self.position, self.candidates)
    }
}

struct GlcmColumns;

impl GlcmColumns {
    const LABEL: usize = 0;
    const PAIRS: usize = 1;
    const EXCLUDED: usize = 2;
    const BINS: usize = 3;
    const FIXED_WIDTH: usize = Self::BINS;

    fn width(quantization: GlcmQuantization) -> usize {
        Self::FIXED_WIDTH + quantization.matrix_len()
    }

    fn schema(quantization: GlcmQuantization) -> Schema {
        let mut columns = Vec::with_capacity(Self::width(quantization));
        columns.extend([
            Column::u64("label"),
            Column::u64("pairs"),
            Column::u64("excluded"),
        ]);
        columns
            .extend((0..quantization.matrix_len()).map(|bin| Column::u64(format!("glcm_{bin}"))));
        trusted_measurement_schema_from_layout_columns(columns, "GLCM")
    }

    fn values(tally: &PlannedGlcmTally) -> Vec<Value> {
        let mut values = Vec::with_capacity(Self::FIXED_WIDTH + tally.matrix.len());
        values.push(Value::U64(tally.label));
        values.push(Value::U64(tally.pairs));
        values.push(Value::U64(tally.excluded));
        values.extend(tally.matrix.iter().copied().map(Value::U64));
        values
    }

    fn decode(
        row: &Row<'_>,
        quantization: GlcmQuantization,
        offset: GlcmOffset,
    ) -> Result<GlcmTextureMeasurements> {
        let mut matrix = Vec::with_capacity(quantization.matrix_len());
        for index in 0..quantization.matrix_len() {
            matrix.push(row.u64(Self::BINS + index)?);
        }
        let out = GlcmTextureMeasurements {
            label: row.u64(Self::LABEL)?,
            levels: quantization.levels(),
            offset: offset.axes(),
            pairs: row.u64(Self::PAIRS)?,
            excluded: row.u64(Self::EXCLUDED)?,
            matrix,
        };
        validate_glcm_row(&out)?;
        Ok(out)
    }
}

pub fn glcm_texture_measurement_schema(quantization: GlcmQuantization) -> Schema {
    GlcmColumns::schema(quantization)
}

struct GlcmPartialLayout {
    quantization: GlcmQuantization,
    offset: GlcmOffset,
}

impl GlcmPartialLayout {
    const MAGIC: u64 = 0x4246_4d45_4153_4754;
    const VERSION: u64 = 1;
    const HEADER_WORDS: usize = 9;
    const FIXED_ROW_WORDS: usize = 7;
    const POSITION: Range<usize> = 2..5;

    fn new(quantization: GlcmQuantization, offset: GlcmOffset) -> Self {
        Self {
            quantization,
            offset,
        }
    }

    fn row_words(&self) -> Result<usize> {
        Self::FIXED_ROW_WORDS
            .checked_add(self.quantization.matrix_len())
            .ok_or_else(|| Error::invalid("measure texture: GLCM row width overflowed"))
    }

    fn total_words(&self, rows: usize) -> Result<usize> {
        Self::HEADER_WORDS
            .checked_add(rows.checked_mul(self.row_words()?).ok_or_else(|| {
                Error::invalid("measure texture: GLCM partial row section overflowed")
            })?)
            .ok_or_else(|| Error::invalid("measure texture: GLCM partial length overflowed"))
    }

    fn capacity(&self, rows: usize) -> Result<usize> {
        self.total_words(rows)
    }

    fn offset_word(value: isize) -> Result<u64> {
        let shifted = (value as i128)
            .checked_add(1i128 << 63)
            .ok_or_else(|| Error::invalid("measure texture: GLCM offset word overflowed"))?;
        u64::try_from(shifted)
            .map_err(|_| Error::invalid("measure texture: GLCM offset word does not fit in u64"))
    }

    fn push_header(&self, words: &mut Vec<u64>, rows: usize) -> Result<()> {
        words.push(Self::MAGIC);
        words.push(Self::VERSION);
        words.push(partial_usize_word(
            rows,
            "measure texture: GLCM partial row count",
        )?);
        words.push(partial_usize_word(
            self.quantization.levels(),
            "measure texture: GLCM level count",
        )?);
        words.push(self.quantization.min().to_bits());
        words.push(self.quantization.max().to_bits());
        for offset in self.offset.axes() {
            words.push(Self::offset_word(offset)?);
        }
        Ok(())
    }

    fn validate_header(&self, words: &[u64]) -> Result<usize> {
        Self::validate_prefix(words)?;
        let offset = self.offset.axes();
        let offset_words = [
            Self::offset_word(offset[0])?,
            Self::offset_word(offset[1])?,
            Self::offset_word(offset[2])?,
        ];
        let levels = partial_usize_word(
            self.quantization.levels(),
            "measure texture: GLCM level count",
        )?;
        if words[3] != levels
            || words[4] != self.quantization.min().to_bits()
            || words[5] != self.quantization.max().to_bits()
            || words[6] != offset_words[0]
            || words[7] != offset_words[1]
            || words[8] != offset_words[2]
        {
            return Err(Error::invalid(
                "measure texture: GLCM partial was written for a different quantization or offset",
            ));
        }
        let rows = partial_word_usize(words[2], "measure texture: GLCM partial row count")?;
        let expected = self.total_words(rows)?;
        if words.len() != expected {
            return Err(Error::invalid(format!(
                "measure texture: GLCM partial has {} word(s), expected {expected}",
                words.len()
            )));
        }
        Ok(rows)
    }

    fn encode(&self, tallies: &BTreeMap<u64, PlannedGlcmTally>) -> Result<Vec<u8>> {
        let mut words = Vec::with_capacity(self.capacity(tallies.len())?);
        self.push_header(&mut words, tallies.len())?;
        for tally in tallies.values() {
            words.push(tally.label);
            words.push(tally.candidates);
            words.extend_from_slice(&tally.position);
            words.push(tally.pairs);
            words.push(tally.excluded);
            words.extend_from_slice(&tally.matrix);
        }
        Ok(pack_u64(&words))
    }

    fn decode(&self, bytes: &[u8]) -> Result<Vec<PlannedGlcmTally>> {
        let words = unpack_u64(bytes)?;
        let rows = self.validate_header(&words)?;
        let mut out = Vec::with_capacity(rows);
        for row in Self::payload_words(&words)?.chunks_exact(self.row_words()?) {
            let mut tally = PlannedGlcmTally::new(row[0], self.quantization);
            tally.candidates = row[1];
            tally.position.copy_from_slice(&row[Self::POSITION]);
            tally.pairs = row[5];
            tally.excluded = row[6];
            tally.matrix.copy_from_slice(&row[Self::FIXED_ROW_WORDS..]);
            out.push(tally);
        }
        Ok(out)
    }
}

impl PartialLayoutContract for GlcmPartialLayout {
    const MAGIC: u64 = GlcmPartialLayout::MAGIC;
    const VERSION: u64 = GlcmPartialLayout::VERSION;
    const HEADER_WORDS: usize = GlcmPartialLayout::HEADER_WORDS;
    const FORMAT: &'static str = "measure texture: GLCM";
}

fn glcm_source_reach(offset: GlcmOffset) -> Reach {
    let mut reach = [(0usize, 0usize); 3];
    for (axis, value) in offset.axes().into_iter().enumerate() {
        if value < 0 {
            reach[axis].0 = value.unsigned_abs();
        } else {
            reach[axis].1 = value.unsigned_abs();
        }
    }
    Reach::asymmetric(reach)
}

fn glcm_source_reach_many(offsets: &[GlcmOffset]) -> Reach {
    let mut reach = [(0usize, 0usize); 3];
    for offset in offsets {
        for (axis, value) in offset.axes().into_iter().enumerate() {
            if value < 0 {
                reach[axis].0 = reach[axis].0.max(value.unsigned_abs());
            } else {
                reach[axis].1 = reach[axis].1.max(value.unsigned_abs());
            }
        }
    }
    Reach::asymmetric(reach)
}

fn tally_glcm_block(
    name: &str,
    quantization: GlcmQuantization,
    offset: GlcmOffset,
    labels: &BlockBuf,
    values: &BlockBuf,
    volume: [usize; 3],
    read: &Region,
    core: &Region,
) -> Result<BTreeMap<u64, PlannedGlcmTally>> {
    let mut tallies = BTreeMap::<u64, PlannedGlcmTally>::new();
    let (BlockBuf::Array(labels), BlockBuf::Array(values)) = (labels, values) else {
        return Ok(tallies);
    };
    let read_shape = read.shape3();
    for (what, array) in [("label volume", labels), ("value array", values)] {
        expect_extent(
            || {
                format!(
                    "{name}: the {what} arrived as {:?} for a block read extent of \
                     {read_shape:?}",
                    array.shape()
                )
            },
            read_shape,
            array.shape(),
        )?;
    }
    let labels = labels.widened();
    let values = values.widened();
    let offset = offset.axes();
    for (index, raw) in labels.indexed_iter() {
        let at = [
            read.start[0] + index.0,
            read.start[1] + index.1,
            read.start[2] + index.2,
        ];
        if !in_region(core, at) {
            continue;
        }
        let Some(neighbour) = offset_position(at, offset, volume) else {
            continue;
        };
        let mut neighbour_index = [0usize; 3];
        for axis in 0..3 {
            let Some(local) = neighbour[axis].checked_sub(read.start[axis]) else {
                return Err(Error::invalid(format!(
                    "{name}: GLCM neighbour {neighbour:?} for {at:?} is outside the fetched read \
                     region {read:?}"
                )));
            };
            if local >= read_shape[axis] {
                return Err(Error::invalid(format!(
                    "{name}: GLCM neighbour {neighbour:?} for {at:?} is outside the fetched read \
                     region {read:?}"
                )));
            }
            neighbour_index[axis] = local;
        }
        let label = label_value(*raw, at)?;
        if label == 0 {
            continue;
        }
        let neighbour_label = label_value(
            labels[[neighbour_index[0], neighbour_index[1], neighbour_index[2]]],
            neighbour,
        )?;
        if neighbour_label != label {
            continue;
        }
        let entry = tallies
            .entry(label)
            .or_insert_with(|| PlannedGlcmTally::new(label, quantization));
        entry.add_candidate(at)?;
        match (
            quantization.quantize(values[[index.0, index.1, index.2]])?,
            quantization
                .quantize(values[[neighbour_index[0], neighbour_index[1], neighbour_index[2]]])?,
        ) {
            (Some(a), Some(b)) => entry.add_pair(a, b, quantization.levels())?,
            _ => entry.add_excluded()?,
        }
    }
    Ok(tallies)
}

/// Planned directed-offset per-label GLCM texture matrix partials.
pub struct GlcmTextureOp {
    name: &'static str,
    labels: TypedSource,
    values: TypedSource,
    quantization: GlcmQuantization,
    offset: GlcmOffset,
    schema: Arc<Schema>,
    stream: String,
    lifecycle: Lifecycle,
}

impl GlcmTextureOp {
    pub fn new(
        name: &'static str,
        labels: impl Into<ImageId>,
        values: impl Into<ImageId>,
        quantization: GlcmQuantization,
        offset: GlcmOffset,
        stream: impl Into<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        let stream = TexturePartialStream::new(stream)?;
        Ok(Self {
            name,
            labels: TypedSource::new(labels),
            values: TypedSource::new(values),
            quantization,
            offset,
            schema: Arc::new(glcm_texture_measurement_schema(quantization)),
            stream: stream.as_str().to_string(),
            lifecycle,
        })
    }

    pub fn holding(mut self, labels: Dtype, values: Dtype) -> Self {
        self.labels = self.labels.holding(labels);
        self.values = self.values.holding(values);
        self
    }

    fn tally_block(
        &self,
        labels: &BlockBuf,
        values: &BlockBuf,
        volume: [usize; 3],
        read: &Region,
        core: &Region,
    ) -> Result<BTreeMap<u64, PlannedGlcmTally>> {
        tally_glcm_block(
            self.name,
            self.quantization,
            self.offset,
            labels,
            values,
            volume,
            read,
            core,
        )
    }
}

impl FragmentOp for GlcmTextureOp {
    fn name(&self) -> &'static str {
        self.name
    }

    fn reach(&self, _axis: usize, _volume_len: usize) -> usize {
        0
    }

    fn source_inputs(&self, _volume: [usize; 3]) -> Vec<SourceInput> {
        let reach = glcm_source_reach(self.offset);
        vec![
            self.labels.source_input(reach.clone()),
            self.values.source_input(reach),
        ]
    }

    fn outputs(&self) -> Vec<FragmentOutput> {
        vec![
            FragmentOutput::new(self.stream.clone(), self.lifecycle, Coverage::EveryBlock)
                .sized(SidecarSize::row_table(self.schema.as_ref(), 1)),
        ]
    }

    fn seam_fold(&self) -> Option<SeamFold> {
        MeasurementSeamLaw::per_block().seam_fold()
    }

    fn apply(&self, _at: &BlockView<'_>) -> Result<BlockOutput> {
        Err(Error::invalid(
            "measure texture: GLCM texture reads label and value sources and is applied through \
             `apply_with`",
        ))
    }

    fn apply_with(&self, at: &BlockView<'_>, sources: SourceBlocks<'_>) -> Result<BlockOutput> {
        let tallies = self.tally_block(
            self.labels
                .block_at_extent(self.name, "label volume", sources, at.read)?,
            self.values
                .block_at_extent(self.name, "value array", sources, at.read)?,
            at.grid.volume(),
            at.read,
            at.core,
        )?;
        Ok(BlockOutput::fragment(
            self.stream.clone(),
            GlcmPartialLayout::new(self.quantization, self.offset).encode(&tallies)?,
        ))
    }
}

/// Planned multi-offset GLCM texture scan sharing one label/value source read.
pub struct MultiGlcmTextureOp {
    name: &'static str,
    labels: TypedSource,
    values: TypedSource,
    quantization: GlcmQuantization,
    offsets: Vec<GlcmOffset>,
    schema: Arc<Schema>,
    streams: Vec<String>,
    lifecycle: Lifecycle,
}

impl MultiGlcmTextureOp {
    pub fn new(
        name: &'static str,
        labels: impl Into<ImageId>,
        values: impl Into<ImageId>,
        quantization: GlcmQuantization,
        offsets: Vec<GlcmOffset>,
        streams: Vec<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        if offsets.is_empty() {
            return Err(Error::invalid(
                "measure texture: multi-offset GLCM needs at least one offset",
            ));
        }
        if offsets.len() != streams.len() {
            return Err(Error::invalid(format!(
                "measure texture: multi-offset GLCM got {} offset(s) but {} stream(s)",
                offsets.len(),
                streams.len()
            )));
        }
        let streams = streams
            .into_iter()
            .map(TexturePartialStream::new)
            .collect::<Result<Vec<_>>>()?;
        let mut seen = BTreeSet::new();
        for offset in &offsets {
            if !seen.insert(offset.axes()) {
                return Err(Error::invalid(format!(
                    "measure texture: duplicate GLCM offset {:?}",
                    offset.axes()
                )));
            }
        }
        Ok(Self {
            name,
            labels: TypedSource::new(labels),
            values: TypedSource::new(values),
            quantization,
            offsets,
            schema: Arc::new(glcm_texture_measurement_schema(quantization)),
            streams: streams
                .iter()
                .map(|stream| stream.as_str().to_string())
                .collect(),
            lifecycle,
        })
    }

    pub fn holding(mut self, labels: Dtype, values: Dtype) -> Self {
        self.labels = self.labels.holding(labels);
        self.values = self.values.holding(values);
        self
    }
}

impl FragmentOp for MultiGlcmTextureOp {
    fn name(&self) -> &'static str {
        self.name
    }

    fn reach(&self, _axis: usize, _volume_len: usize) -> usize {
        0
    }

    fn source_inputs(&self, _volume: [usize; 3]) -> Vec<SourceInput> {
        let reach = glcm_source_reach_many(&self.offsets);
        vec![
            self.labels.source_input(reach.clone()),
            self.values.source_input(reach),
        ]
    }

    fn outputs(&self) -> Vec<FragmentOutput> {
        self.streams
            .iter()
            .map(|stream| {
                FragmentOutput::new(stream.clone(), self.lifecycle, Coverage::EveryBlock)
                    .sized(SidecarSize::row_table(self.schema.as_ref(), 1))
            })
            .collect()
    }

    fn seam_fold(&self) -> Option<SeamFold> {
        MeasurementSeamLaw::per_block().seam_fold()
    }

    fn apply(&self, _at: &BlockView<'_>) -> Result<BlockOutput> {
        Err(Error::invalid(
            "measure texture: multi-offset GLCM texture reads label and value sources and is \
             applied through `apply_with`",
        ))
    }

    fn apply_with(&self, at: &BlockView<'_>, sources: SourceBlocks<'_>) -> Result<BlockOutput> {
        let labels = self
            .labels
            .block_at_extent(self.name, "label volume", sources, at.read)?;
        let values = self
            .values
            .block_at_extent(self.name, "value array", sources, at.read)?;
        let mut output = BlockOutput::nothing();
        for (&offset, stream) in self.offsets.iter().zip(&self.streams) {
            let tallies = tally_glcm_block(
                self.name,
                self.quantization,
                offset,
                labels,
                values,
                at.grid.volume(),
                at.read,
                at.core,
            )?;
            output = output.with_fragment(
                stream.clone(),
                GlcmPartialLayout::new(self.quantization, offset).encode(&tallies)?,
            );
        }
        Ok(output)
    }
}

/// Merge planned directed-offset GLCM texture partials into owned rows.
pub struct MergeGlcmTextureOp {
    name: &'static str,
    input: PartialPhaseInput,
    quantization: GlcmQuantization,
    offset: GlcmOffset,
    schema: Arc<Schema>,
    stream: String,
    lifecycle: Lifecycle,
}

impl MergeGlcmTextureOp {
    pub fn new(
        name: &'static str,
        input: impl Into<String>,
        input_phase: usize,
        lattice: [usize; 3],
        quantization: GlcmQuantization,
        offset: GlcmOffset,
        stream: impl Into<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        let input = TexturePartialStream::new(input)?;
        let stream = TextureOutputStream::new(stream)?;
        Ok(Self {
            name,
            input: PartialPhaseInput::try_new(&input, input_phase, lattice)?,
            quantization,
            offset,
            schema: Arc::new(glcm_texture_measurement_schema(quantization)),
            stream: stream.as_str().to_string(),
            lifecycle,
        })
    }

    fn fold<'a>(
        &self,
        partials: impl IntoIterator<Item = &'a [u8]>,
    ) -> Result<BTreeMap<u64, PlannedGlcmTally>> {
        let mut totals = BTreeMap::<u64, PlannedGlcmTally>::new();
        for bytes in partials {
            for tally in GlcmPartialLayout::new(self.quantization, self.offset).decode(bytes)? {
                match totals.get_mut(&tally.label) {
                    Some(seen) => seen.merge_exact(ExactReduction::new(&tally))?,
                    None => {
                        totals.insert(tally.label, tally);
                    }
                }
            }
        }
        Ok(totals)
    }

    fn encode_owned(
        &self,
        totals: &BTreeMap<u64, PlannedGlcmTally>,
        grid: &BlockGrid,
        block: [usize; 3],
    ) -> Result<Vec<u8>> {
        let mut rows = RowBuilder::new(Arc::clone(&self.schema));
        for tally in totals.values() {
            let Some(at) = tally.centroid() else {
                continue;
            };
            if owner_of(grid, at) != block {
                continue;
            }
            rows.push(at, &GlcmColumns::values(tally))?;
        }
        Ok(rows.encode())
    }
}

impl FragmentOp for MergeGlcmTextureOp {
    fn name(&self) -> &'static str {
        self.name
    }

    fn reach(&self, _axis: usize, _volume_len: usize) -> usize {
        0
    }

    fn inputs(&self) -> Vec<FragmentInput> {
        vec![self.input.fragment_input()]
    }

    fn gathers(&self) -> bool {
        false
    }

    fn outputs(&self) -> Vec<FragmentOutput> {
        vec![
            FragmentOutput::new(self.stream.clone(), self.lifecycle, Coverage::EveryBlock)
                .sized(SidecarSize::row_table(self.schema.as_ref(), 1)),
        ]
    }

    fn seam_fold(&self) -> Option<SeamFold> {
        MeasurementSeamLaw::unordered_exact().seam_fold()
    }

    fn apply(&self, at: &BlockView<'_>) -> Result<BlockOutput> {
        let partials = self.input.stream_fragments(at)?;
        let totals = self.fold(partials.iter().map(Vec::as_slice))?;
        Ok(BlockOutput::fragment(
            self.stream.clone(),
            self.encode_owned(&totals, at.grid, at.index)?,
        ))
    }
}

pub fn collect_glcm_texture_measurements(
    env: &dyn Environment,
    stream: &str,
    phase: usize,
    volume: [usize; 3],
    quantization: GlcmQuantization,
    offset: GlcmOffset,
) -> Result<Vec<GlcmTextureMeasurements>> {
    let rows = MeasurementRows::<TextureRows>::from_legacy_collector(stream, phase)?;
    collect_glcm_texture_rows(
        env,
        &rows,
        volume,
        GlcmTextureContract::new(quantization, offset),
    )
}

pub fn collect_glcm_texture_rows(
    env: &dyn Environment,
    rows: &MeasurementRows<TextureRows>,
    volume: [usize; 3],
    contract: GlcmTextureContract,
) -> Result<Vec<GlcmTextureMeasurements>> {
    collect_measurement_rows_table(
        env,
        rows,
        volume,
        glcm_texture_measurement_schema(contract.quantization()),
        |row| GlcmColumns::decode(row, contract.quantization(), contract.offset()),
    )
}

pub fn collect_glcm_texture_rows_with_contract(
    env: &dyn Environment,
    rows: &MeasurementRowsWithContract<TextureRows, GlcmTextureContract>,
    volume: [usize; 3],
) -> Result<Vec<GlcmTextureMeasurements>> {
    collect_glcm_texture_rows(env, rows.rows(), volume, rows.contract())
}

fn validate_glcm_row(row: &GlcmTextureMeasurements) -> Result<()> {
    if row.label == 0 {
        return Err(Error::invalid(
            "measure texture: GLCM row has background label 0",
        ));
    }
    if row.levels < 2 {
        return Err(Error::invalid(format!(
            "measure texture: GLCM row for label {} has invalid level count {}",
            row.label, row.levels
        )));
    }
    let expected_len = row
        .levels
        .checked_mul(row.levels)
        .ok_or_else(|| Error::invalid("measure texture: GLCM level count overflows matrix size"))?;
    if row.matrix.len() != expected_len {
        return Err(Error::invalid(format!(
            "measure texture: GLCM row for label {} has matrix length {}, expected {}",
            row.label,
            row.matrix.len(),
            expected_len
        )));
    }
    if row.offset == [0, 0, 0] {
        return Err(Error::invalid(format!(
            "measure texture: GLCM row for label {} has zero offset",
            row.label
        )));
    }
    let matrix_pairs: u64 = row.matrix.iter().sum();
    if matrix_pairs != row.pairs {
        return Err(Error::invalid(format!(
            "measure texture: GLCM row for label {} has pair count {} but matrix sums to {}",
            row.label, row.pairs, matrix_pairs
        )));
    }
    Ok(())
}

#[derive(Debug, Clone, Copy, PartialEq)]
struct ColocalizationTally {
    label: u64,
    count: u64,
    position: [u64; 3],
    finite_count: u64,
    sum_a: f64,
    sum_b: f64,
    sum_a2: f64,
    sum_b2: f64,
    sum_ab: f64,
    positive_a: f64,
    positive_b: f64,
    positive_a_where_b: f64,
    positive_b_where_a: f64,
}

impl ColocalizationTally {
    fn new(label: u64) -> Self {
        Self {
            label,
            count: 0,
            position: [0; 3],
            finite_count: 0,
            sum_a: 0.0,
            sum_b: 0.0,
            sum_a2: 0.0,
            sum_b2: 0.0,
            sum_ab: 0.0,
            positive_a: 0.0,
            positive_b: 0.0,
            positive_a_where_b: 0.0,
            positive_b_where_a: 0.0,
        }
    }

    fn add(&mut self, at: [usize; 3], a: f64, b: f64) -> Result<()> {
        self.count = self
            .count
            .checked_add(1)
            .ok_or_else(|| Error::invalid("measure colocalization: pair count overflowed"))?;
        for (axis, coordinate) in at.into_iter().enumerate() {
            let coordinate =
                usize_coordinate(coordinate, "measure colocalization: coordinate component")?;
            self.position[axis] = self.position[axis].checked_add(coordinate).ok_or_else(|| {
                Error::invalid(
                    "measure colocalization: coordinate sum overflowed while locating row",
                )
            })?;
        }
        if !a.is_finite() || !b.is_finite() {
            return Ok(());
        }
        self.finite_count = self.finite_count.checked_add(1).ok_or_else(|| {
            Error::invalid("measure colocalization: finite pair count overflowed")
        })?;
        self.sum_a += a;
        self.sum_b += b;
        self.sum_a2 += a * a;
        self.sum_b2 += b * b;
        self.sum_ab += a * b;
        if a > 0.0 {
            self.positive_a += a;
            if b > 0.0 {
                self.positive_a_where_b += a;
            }
        }
        if b > 0.0 {
            self.positive_b += b;
            if a > 0.0 {
                self.positive_b_where_a += b;
            }
        }
        Ok(())
    }
}

/// Resident per-label channel-pair colocalization primitive sums.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct ColocalizationMeasurements {
    pub label: u64,
    pub count: u64,
    pub finite_count: u64,
    pub sum_a: f64,
    pub sum_b: f64,
    pub sum_a2: f64,
    pub sum_b2: f64,
    pub sum_ab: f64,
    pub positive_a: f64,
    pub positive_b: f64,
    pub positive_a_where_b: f64,
    pub positive_b_where_a: f64,
}

/// Derived scalar features available from [`ColocalizationMeasurements`].
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ColocalizationFeature {
    Pearson,
    SlopeBOnA,
    OverlapCoefficient,
    MandersM1,
    MandersM2,
}

impl ColocalizationFeature {
    pub const ALL: [Self; 5] = [
        Self::Pearson,
        Self::SlopeBOnA,
        Self::OverlapCoefficient,
        Self::MandersM1,
        Self::MandersM2,
    ];

    pub fn column_name(self) -> &'static str {
        match self {
            Self::Pearson => "pearson",
            Self::SlopeBOnA => "slope_b_on_a",
            Self::OverlapCoefficient => "overlap_coefficient",
            Self::MandersM1 => "manders_m1",
            Self::MandersM2 => "manders_m2",
        }
    }
}

impl ColocalizationMeasurements {
    pub fn feature(&self, feature: ColocalizationFeature) -> Option<f64> {
        match feature {
            ColocalizationFeature::Pearson => self.pearson(),
            ColocalizationFeature::SlopeBOnA => self.slope_b_on_a(),
            ColocalizationFeature::OverlapCoefficient => self.overlap_coefficient(),
            ColocalizationFeature::MandersM1 => self.manders_m1(),
            ColocalizationFeature::MandersM2 => self.manders_m2(),
        }
    }

    pub fn pearson(&self) -> Option<f64> {
        if self.finite_count == 0 {
            return None;
        }
        let n = self.finite_count as f64;
        let cov = self.sum_ab - self.sum_a * self.sum_b / n;
        let var_a = self.sum_a2 - self.sum_a * self.sum_a / n;
        let var_b = self.sum_b2 - self.sum_b * self.sum_b / n;
        let denom = (var_a * var_b).sqrt();
        (denom > 0.0).then_some(cov / denom)
    }

    /// Least-squares slope for channel B as a function of channel A.
    pub fn slope_b_on_a(&self) -> Option<f64> {
        if self.finite_count == 0 {
            return None;
        }
        let n = self.finite_count as f64;
        let var_a = self.sum_a2 - self.sum_a * self.sum_a / n;
        if var_a <= 0.0 {
            return None;
        }
        Some((self.sum_ab - self.sum_a * self.sum_b / n) / var_a)
    }

    pub fn overlap_coefficient(&self) -> Option<f64> {
        let denom = (self.sum_a2 * self.sum_b2).sqrt();
        (denom > 0.0).then_some(self.sum_ab / denom)
    }

    /// Basic Manders M1 using zero as the positive-intensity threshold.
    pub fn manders_m1(&self) -> Option<f64> {
        (self.positive_a > 0.0).then_some(self.positive_a_where_b / self.positive_a)
    }

    /// Basic Manders M2 using zero as the positive-intensity threshold.
    pub fn manders_m2(&self) -> Option<f64> {
        (self.positive_b > 0.0).then_some(self.positive_b_where_a / self.positive_b)
    }
}

/// Resident labelled channel-pair colocalization measurements.
///
/// Non-finite channel pairs are counted in `count` but excluded from primitive
/// sums and derived ratios. Basic Manders coefficients use zero as the
/// positive-intensity threshold; Costes and rank-weighted variants need
/// additional threshold/rank passes.
pub fn colocalization_measurements(
    labels: ArrayView3<'_, f64>,
    channel_a: ArrayView3<'_, f64>,
    channel_b: ArrayView3<'_, f64>,
) -> Result<Vec<ColocalizationMeasurements>> {
    validate_colocalization_shapes(labels, channel_a, channel_b)?;
    let mut tallies = BTreeMap::<u64, ColocalizationTally>::new();
    for ((z, y, x), &raw_label) in labels.indexed_iter() {
        let at = [z, y, x];
        let label = label_value(raw_label, at)?;
        if label == 0 {
            continue;
        }
        tallies
            .entry(label)
            .or_insert_with(|| ColocalizationTally::new(label))
            .add(at, channel_a[[z, y, x]], channel_b[[z, y, x]])?;
    }
    Ok(tallies
        .into_values()
        .map(|tally| ColocalizationMeasurements {
            label: tally.label,
            count: tally.count,
            finite_count: tally.finite_count,
            sum_a: tally.sum_a,
            sum_b: tally.sum_b,
            sum_a2: tally.sum_a2,
            sum_b2: tally.sum_b2,
            sum_ab: tally.sum_ab,
            positive_a: tally.positive_a,
            positive_b: tally.positive_b,
            positive_a_where_b: tally.positive_a_where_b,
            positive_b_where_a: tally.positive_b_where_a,
        })
        .collect())
}

#[derive(Debug, Clone, PartialEq)]
struct FixedColocalizationTally {
    label: u64,
    count: u64,
    position: [u64; 3],
    finite_count: u64,
    sum_a: i128,
    sum_b: i128,
    sum_a2: i128,
    sum_b2: i128,
    sum_ab: i128,
    positive_a: i128,
    positive_b: i128,
    positive_a_where_b: i128,
    positive_b_where_a: i128,
}

impl FixedColocalizationTally {
    fn new(label: u64) -> Self {
        Self {
            label,
            count: 0,
            position: [0; 3],
            finite_count: 0,
            sum_a: 0,
            sum_b: 0,
            sum_a2: 0,
            sum_b2: 0,
            sum_ab: 0,
            positive_a: 0,
            positive_b: 0,
            positive_a_where_b: 0,
            positive_b_where_a: 0,
        }
    }

    fn add(&mut self, fixed: FixedPoint, at: [usize; 3], a: f64, b: f64) -> Result<()> {
        self.count = self
            .count
            .checked_add(1)
            .ok_or_else(|| Error::invalid("measure colocalization: pair count overflowed"))?;
        for (axis, coordinate) in at.into_iter().enumerate() {
            let coordinate =
                usize_coordinate(coordinate, "measure colocalization: coordinate component")?;
            self.position[axis] = self.position[axis].checked_add(coordinate).ok_or_else(|| {
                Error::invalid(
                    "measure colocalization: coordinate sum overflowed while locating row",
                )
            })?;
        }
        if !a.is_finite() || !b.is_finite() {
            return Ok(());
        }
        self.finite_count = self.finite_count.checked_add(1).ok_or_else(|| {
            Error::invalid("measure colocalization: finite pair count overflowed")
        })?;
        self.sum_a += quantise_colocalization_value(fixed, a, "channel A value")?;
        self.sum_b += quantise_colocalization_value(fixed, b, "channel B value")?;
        self.sum_a2 += quantise_colocalization_value(fixed, a * a, "channel A squared value")?;
        self.sum_b2 += quantise_colocalization_value(fixed, b * b, "channel B squared value")?;
        self.sum_ab += quantise_colocalization_value(fixed, a * b, "channel product")?;
        if a > 0.0 {
            self.positive_a += quantise_colocalization_value(fixed, a, "positive channel A value")?;
            if b > 0.0 {
                self.positive_a_where_b +=
                    quantise_colocalization_value(fixed, a, "positive channel A overlap value")?;
            }
        }
        if b > 0.0 {
            self.positive_b += quantise_colocalization_value(fixed, b, "positive channel B value")?;
            if a > 0.0 {
                self.positive_b_where_a +=
                    quantise_colocalization_value(fixed, b, "positive channel B overlap value")?;
            }
        }
        Ok(())
    }

    fn merge_exact(&mut self, other: ExactReduction<&Self>) -> Result<()> {
        let other = other.into_inner();
        if self.label != other.label {
            return Err(Error::invalid(format!(
                "measure colocalization: cannot merge labels {} and {}",
                self.label, other.label
            )));
        }
        self.count = self
            .count
            .checked_add(other.count)
            .ok_or_else(|| Error::invalid("measure colocalization: pair count overflowed"))?;
        self.finite_count = self
            .finite_count
            .checked_add(other.finite_count)
            .ok_or_else(|| {
                Error::invalid("measure colocalization: finite pair count overflowed")
            })?;
        for axis in 0..3 {
            self.position[axis] = self.position[axis]
                .checked_add(other.position[axis])
                .ok_or_else(|| {
                    Error::invalid(
                        "measure colocalization: coordinate sum overflowed while merging",
                    )
                })?;
        }
        self.sum_a += other.sum_a;
        self.sum_b += other.sum_b;
        self.sum_a2 += other.sum_a2;
        self.sum_b2 += other.sum_b2;
        self.sum_ab += other.sum_ab;
        self.positive_a += other.positive_a;
        self.positive_b += other.positive_b;
        self.positive_a_where_b += other.positive_a_where_b;
        self.positive_b_where_a += other.positive_b_where_a;
        Ok(())
    }

    fn centroid(&self) -> Option<[usize; 3]> {
        rounded_centroid_coordinate(self.position, self.count)
    }
}

fn quantise_colocalization_value(
    fixed: FixedPoint,
    value: f64,
    what: &'static str,
) -> Result<i128> {
    fixed.quantise(value)?.ok_or_else(|| {
        Error::invalid(format!(
            "measure colocalization: {what} became non-finite before fixed-point quantization"
        ))
    })
}

struct ColocalizationColumns;

fn validate_colocalization_row(row: &ColocalizationMeasurements) -> Result<()> {
    if row.label == 0 {
        return Err(Error::invalid(
            "measure colocalization: row has background label 0",
        ));
    }
    if row.count == 0 {
        return Err(Error::invalid(format!(
            "measure colocalization: row for label {} has no labelled samples",
            row.label
        )));
    }
    if row.finite_count > row.count {
        return Err(Error::invalid(format!(
            "measure colocalization: row for label {} has {} finite samples but only {} total \
             samples",
            row.label, row.finite_count, row.count
        )));
    }
    for (name, value) in [
        ("sum_a", row.sum_a),
        ("sum_b", row.sum_b),
        ("sum_a2", row.sum_a2),
        ("sum_b2", row.sum_b2),
        ("sum_ab", row.sum_ab),
        ("positive_a", row.positive_a),
        ("positive_b", row.positive_b),
        ("positive_a_where_b", row.positive_a_where_b),
        ("positive_b_where_a", row.positive_b_where_a),
    ] {
        if !value.is_finite() {
            return Err(Error::invalid(format!(
                "measure colocalization: row for label {} has non-finite {name}",
                row.label
            )));
        }
    }
    for (name, value) in [
        ("sum_a2", row.sum_a2),
        ("sum_b2", row.sum_b2),
        ("positive_a", row.positive_a),
        ("positive_b", row.positive_b),
        ("positive_a_where_b", row.positive_a_where_b),
        ("positive_b_where_a", row.positive_b_where_a),
    ] {
        if value < 0.0 {
            return Err(Error::invalid(format!(
                "measure colocalization: row for label {} has negative {name}",
                row.label
            )));
        }
    }
    if row.positive_a_where_b > row.positive_a {
        return Err(Error::invalid(format!(
            "measure colocalization: row for label {} has positive_a_where_b greater than \
             positive_a",
            row.label
        )));
    }
    if row.positive_b_where_a > row.positive_b {
        return Err(Error::invalid(format!(
            "measure colocalization: row for label {} has positive_b_where_a greater than \
             positive_b",
            row.label
        )));
    }
    if row.finite_count == 0 {
        for (name, value) in [
            ("sum_a", row.sum_a),
            ("sum_b", row.sum_b),
            ("sum_a2", row.sum_a2),
            ("sum_b2", row.sum_b2),
            ("sum_ab", row.sum_ab),
            ("positive_a", row.positive_a),
            ("positive_b", row.positive_b),
            ("positive_a_where_b", row.positive_a_where_b),
            ("positive_b_where_a", row.positive_b_where_a),
        ] {
            if value != 0.0 {
                return Err(Error::invalid(format!(
                    "measure colocalization: row for label {} has non-zero {name} without \
                     finite samples",
                    row.label
                )));
            }
        }
    }
    Ok(())
}

impl ColocalizationColumns {
    const WIDTH: usize = 12;
    const LABEL: usize = 0;
    const COUNT: usize = 1;
    const FINITE_COUNT: usize = 2;
    const SUM_A: usize = 3;
    const SUM_B: usize = 4;
    const SUM_A2: usize = 5;
    const SUM_B2: usize = 6;
    const SUM_AB: usize = 7;
    const POSITIVE_A: usize = 8;
    const POSITIVE_B: usize = 9;
    const POSITIVE_A_WHERE_B: usize = 10;
    const POSITIVE_B_WHERE_A: usize = 11;

    fn columns() -> [Column; Self::WIDTH] {
        [
            Column::u64("label"),
            Column::u64("count"),
            Column::u64("finite_count"),
            Column::f64("sum_a"),
            Column::f64("sum_b"),
            Column::f64("sum_a2"),
            Column::f64("sum_b2"),
            Column::f64("sum_ab"),
            Column::f64("positive_a"),
            Column::f64("positive_b"),
            Column::f64("positive_a_where_b"),
            Column::f64("positive_b_where_a"),
        ]
    }

    fn schema() -> Schema {
        fixed_measurement_schema(Self::columns(), "colocalization")
    }

    fn values(tally: &FixedColocalizationTally, fixed: FixedPoint) -> Result<[Value; Self::WIDTH]> {
        Ok([
            Value::U64(tally.label),
            Value::U64(tally.count),
            Value::U64(tally.finite_count),
            Value::F64(fixed.value_of(fixed.from_column(fixed.to_column(tally.sum_a)?))),
            Value::F64(fixed.value_of(fixed.from_column(fixed.to_column(tally.sum_b)?))),
            Value::F64(fixed.value_of(fixed.from_column(fixed.to_column(tally.sum_a2)?))),
            Value::F64(fixed.value_of(fixed.from_column(fixed.to_column(tally.sum_b2)?))),
            Value::F64(fixed.value_of(fixed.from_column(fixed.to_column(tally.sum_ab)?))),
            Value::F64(fixed.value_of(fixed.from_column(fixed.to_column(tally.positive_a)?))),
            Value::F64(fixed.value_of(fixed.from_column(fixed.to_column(tally.positive_b)?))),
            Value::F64(
                fixed.value_of(fixed.from_column(fixed.to_column(tally.positive_a_where_b)?)),
            ),
            Value::F64(
                fixed.value_of(fixed.from_column(fixed.to_column(tally.positive_b_where_a)?)),
            ),
        ])
    }

    fn row_values(row: &ColocalizationMeasurements) -> [Value; Self::WIDTH] {
        [
            Value::U64(row.label),
            Value::U64(row.count),
            Value::U64(row.finite_count),
            Value::F64(row.sum_a),
            Value::F64(row.sum_b),
            Value::F64(row.sum_a2),
            Value::F64(row.sum_b2),
            Value::F64(row.sum_ab),
            Value::F64(row.positive_a),
            Value::F64(row.positive_b),
            Value::F64(row.positive_a_where_b),
            Value::F64(row.positive_b_where_a),
        ]
    }

    fn decode(row: &Row<'_>) -> Result<ColocalizationMeasurements> {
        let measurements = ColocalizationMeasurements {
            label: row.u64(Self::LABEL)?,
            count: row.u64(Self::COUNT)?,
            finite_count: row.u64(Self::FINITE_COUNT)?,
            sum_a: row.f64(Self::SUM_A)?,
            sum_b: row.f64(Self::SUM_B)?,
            sum_a2: row.f64(Self::SUM_A2)?,
            sum_b2: row.f64(Self::SUM_B2)?,
            sum_ab: row.f64(Self::SUM_AB)?,
            positive_a: row.f64(Self::POSITIVE_A)?,
            positive_b: row.f64(Self::POSITIVE_B)?,
            positive_a_where_b: row.f64(Self::POSITIVE_A_WHERE_B)?,
            positive_b_where_a: row.f64(Self::POSITIVE_B_WHERE_A)?,
        };
        validate_colocalization_row(&measurements)?;
        Ok(measurements)
    }
}

pub fn colocalization_measurement_schema() -> Schema {
    ColocalizationColumns::schema()
}

/// Encode primitive colocalization rows as a row-table fragment.
pub fn encode_colocalization_measurements(
    measurements: &[ColocalizationMeasurements],
) -> Result<Vec<u8>> {
    encode_colocalization_measurements_with_schema(
        measurements,
        Arc::new(colocalization_measurement_schema()),
    )
}

fn encode_colocalization_measurements_with_schema(
    measurements: &[ColocalizationMeasurements],
    schema: Arc<Schema>,
) -> Result<Vec<u8>> {
    encode_measurement_rows_at_origin(schema, measurements, |row| {
        validate_colocalization_row(row)?;
        Ok(ColocalizationColumns::row_values(row))
    })
}

struct ColocalizationPartialLayout {
    fixed: FixedPoint,
}

impl ColocalizationPartialLayout {
    const MAGIC: u64 = 0x4246_4d45_4153_434f;
    const VERSION: u64 = 1;
    const HEADER_WORDS: usize = 4;
    const ROW_WORDS: usize = 15;
    const POSITION: Range<usize> = 2..5;
    const SUMS: Range<usize> = 6..15;

    fn new(fixed: FixedPoint) -> Self {
        Self { fixed }
    }

    fn push_header(&self, words: &mut Vec<u64>, rows: usize) -> Result<()> {
        words.push(Self::MAGIC);
        words.push(Self::VERSION);
        words.push(partial_usize_word(
            rows,
            "measure colocalization: partial row count",
        )?);
        words.push(u64::from(self.fixed.fraction_bits()));
        Ok(())
    }

    fn total_words(&self, rows: usize) -> Result<usize> {
        Self::HEADER_WORDS
            .checked_add(rows.checked_mul(Self::ROW_WORDS).ok_or_else(|| {
                Error::invalid("measure colocalization: partial row section overflowed")
            })?)
            .ok_or_else(|| Error::invalid("measure colocalization: partial length overflowed"))
    }

    fn capacity(&self, rows: usize) -> Result<usize> {
        self.total_words(rows)
    }

    fn validate_header(&self, words: &[u64]) -> Result<usize> {
        Self::validate_prefix(words)?;
        if words[3] != u64::from(self.fixed.fraction_bits()) {
            return Err(Error::invalid(format!(
                "measure colocalization: partial was written with q{} but this merge expects q{}",
                words[3],
                self.fixed.fraction_bits()
            )));
        }
        let rows = partial_word_usize(words[2], "measure colocalization: partial row count")?;
        let expected = self.total_words(rows)?;
        if words.len() != expected {
            return Err(Error::invalid(format!(
                "measure colocalization: partial has {} word(s), expected {expected}",
                words.len()
            )));
        }
        Ok(rows)
    }

    fn encode(&self, tallies: &BTreeMap<u64, FixedColocalizationTally>) -> Result<Vec<u8>> {
        let mut words = Vec::with_capacity(self.capacity(tallies.len())?);
        self.push_header(&mut words, tallies.len())?;
        for tally in tallies.values() {
            words.push(tally.label);
            words.push(tally.count);
            words.extend_from_slice(&tally.position);
            words.push(tally.finite_count);
            for value in [
                tally.sum_a,
                tally.sum_b,
                tally.sum_a2,
                tally.sum_b2,
                tally.sum_ab,
                tally.positive_a,
                tally.positive_b,
                tally.positive_a_where_b,
                tally.positive_b_where_a,
            ] {
                words.push(self.fixed.to_column(value)?);
            }
        }
        Ok(pack_u64(&words))
    }

    fn decode(&self, bytes: &[u8]) -> Result<Vec<FixedColocalizationTally>> {
        let words = unpack_u64(bytes)?;
        let rows = self.validate_header(&words)?;
        let mut out = Vec::with_capacity(rows);
        for row in Self::payload_words(&words)?.chunks_exact(Self::ROW_WORDS) {
            let mut tally = FixedColocalizationTally::new(row[0]);
            tally.count = row[1];
            tally.position.copy_from_slice(&row[Self::POSITION]);
            tally.finite_count = row[5];
            let sums = &row[Self::SUMS];
            tally.sum_a = self.fixed.from_column(sums[0]) as i128;
            tally.sum_b = self.fixed.from_column(sums[1]) as i128;
            tally.sum_a2 = self.fixed.from_column(sums[2]) as i128;
            tally.sum_b2 = self.fixed.from_column(sums[3]) as i128;
            tally.sum_ab = self.fixed.from_column(sums[4]) as i128;
            tally.positive_a = self.fixed.from_column(sums[5]) as i128;
            tally.positive_b = self.fixed.from_column(sums[6]) as i128;
            tally.positive_a_where_b = self.fixed.from_column(sums[7]) as i128;
            tally.positive_b_where_a = self.fixed.from_column(sums[8]) as i128;
            out.push(tally);
        }
        Ok(out)
    }
}

impl PartialLayoutContract for ColocalizationPartialLayout {
    const MAGIC: u64 = ColocalizationPartialLayout::MAGIC;
    const VERSION: u64 = ColocalizationPartialLayout::VERSION;
    const HEADER_WORDS: usize = ColocalizationPartialLayout::HEADER_WORDS;
    const FORMAT: &'static str = "measure colocalization";
}

/// Planned per-label fixed-point channel-pair colocalization primitive sums.
pub struct ColocalizationSumsOp {
    name: &'static str,
    labels: TypedSource,
    channel_a: TypedSource,
    channel_b: TypedSource,
    fixed: FixedPoint,
    schema: Arc<Schema>,
    stream: String,
    lifecycle: Lifecycle,
}

impl ColocalizationSumsOp {
    pub fn new(
        name: &'static str,
        labels: impl Into<ImageId>,
        channel_a: impl Into<ImageId>,
        channel_b: impl Into<ImageId>,
        fixed: FixedPoint,
        stream: impl Into<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        let stream = ColocalizationPartialStream::new(stream)?;
        Ok(Self {
            name,
            labels: TypedSource::new(labels),
            channel_a: TypedSource::new(channel_a),
            channel_b: TypedSource::new(channel_b),
            fixed,
            schema: Arc::new(colocalization_measurement_schema()),
            stream: stream.as_str().to_string(),
            lifecycle,
        })
    }

    pub fn holding(mut self, labels: Dtype, channel_a: Dtype, channel_b: Dtype) -> Self {
        self.labels = self.labels.holding(labels);
        self.channel_a = self.channel_a.holding(channel_a);
        self.channel_b = self.channel_b.holding(channel_b);
        self
    }

    fn tally_block(
        &self,
        labels: &BlockBuf,
        channel_a: &BlockBuf,
        channel_b: &BlockBuf,
        read: &Region,
        core: &Region,
    ) -> Result<BTreeMap<u64, FixedColocalizationTally>> {
        let mut tallies = BTreeMap::<u64, FixedColocalizationTally>::new();
        let (BlockBuf::Array(labels), BlockBuf::Array(channel_a), BlockBuf::Array(channel_b)) =
            (labels, channel_a, channel_b)
        else {
            return Ok(tallies);
        };
        let shape = read.shape3();
        for (what, array) in [
            ("label volume", labels),
            ("channel A array", channel_a),
            ("channel B array", channel_b),
        ] {
            expect_extent(
                || {
                    format!(
                        "measure colocalization: the {what} arrived as {:?} for a block read \
                         extent of {shape:?}",
                        array.shape()
                    )
                },
                shape,
                array.shape(),
            )?;
        }
        let labels = labels.widened();
        let channel_a = channel_a.widened();
        let channel_b = channel_b.widened();
        for (index, raw) in labels.indexed_iter() {
            let at = [
                read.start[0] + index.0,
                read.start[1] + index.1,
                read.start[2] + index.2,
            ];
            if !in_region(core, at) {
                continue;
            }
            let label = label_value(*raw, at)?;
            if label == 0 {
                continue;
            }
            tallies
                .entry(label)
                .or_insert_with(|| FixedColocalizationTally::new(label))
                .add(
                    self.fixed,
                    at,
                    channel_a[[index.0, index.1, index.2]],
                    channel_b[[index.0, index.1, index.2]],
                )?;
        }
        Ok(tallies)
    }
}

impl FragmentOp for ColocalizationSumsOp {
    fn name(&self) -> &'static str {
        self.name
    }

    fn reach(&self, _axis: usize, _volume_len: usize) -> usize {
        0
    }

    fn source_inputs(&self, _volume: [usize; 3]) -> Vec<SourceInput> {
        vec![
            self.labels.voxelwise_input(),
            self.channel_a.voxelwise_input(),
            self.channel_b.voxelwise_input(),
        ]
    }

    fn outputs(&self) -> Vec<FragmentOutput> {
        vec![
            FragmentOutput::new(self.stream.clone(), self.lifecycle, Coverage::EveryBlock)
                .sized(SidecarSize::row_table(self.schema.as_ref(), 1)),
        ]
    }

    fn seam_fold(&self) -> Option<SeamFold> {
        MeasurementSeamLaw::per_block().seam_fold()
    }

    fn apply(&self, _at: &BlockView<'_>) -> Result<BlockOutput> {
        Err(Error::invalid(
            "measure colocalization: channel-pair reductions read label and channel sources and \
             are applied through `apply_with`",
        ))
    }

    fn apply_with(&self, at: &BlockView<'_>, sources: SourceBlocks<'_>) -> Result<BlockOutput> {
        let tallies = self.tally_block(
            self.labels
                .block_at_extent(self.name, "label volume", sources, at.read)?,
            self.channel_a
                .block_at_extent(self.name, "channel A array", sources, at.read)?,
            self.channel_b
                .block_at_extent(self.name, "channel B array", sources, at.read)?,
            at.read,
            at.core,
        )?;
        Ok(BlockOutput::fragment(
            self.stream.clone(),
            ColocalizationPartialLayout::new(self.fixed).encode(&tallies)?,
        ))
    }
}

/// Merge planned colocalization partials into one owned row per label.
pub struct MergeColocalizationSumsOp {
    name: &'static str,
    input: PartialPhaseInput,
    fixed: FixedPoint,
    schema: Arc<Schema>,
    stream: String,
    lifecycle: Lifecycle,
}

impl MergeColocalizationSumsOp {
    pub fn new(
        name: &'static str,
        input: impl Into<String>,
        input_phase: usize,
        lattice: [usize; 3],
        fixed: FixedPoint,
        stream: impl Into<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        let input = ColocalizationPartialStream::new(input)?;
        let stream = ColocalizationOutputStream::new(stream)?;
        Ok(Self {
            name,
            input: PartialPhaseInput::try_new(&input, input_phase, lattice)?,
            fixed,
            schema: Arc::new(colocalization_measurement_schema()),
            stream: stream.as_str().to_string(),
            lifecycle,
        })
    }

    fn fold<'a>(
        &self,
        partials: impl IntoIterator<Item = &'a [u8]>,
    ) -> Result<BTreeMap<u64, FixedColocalizationTally>> {
        let mut totals = BTreeMap::<u64, FixedColocalizationTally>::new();
        for bytes in partials {
            for tally in ColocalizationPartialLayout::new(self.fixed).decode(bytes)? {
                match totals.get_mut(&tally.label) {
                    Some(seen) => seen.merge_exact(ExactReduction::new(&tally))?,
                    None => {
                        totals.insert(tally.label, tally);
                    }
                }
            }
        }
        Ok(totals)
    }

    fn encode_owned(
        &self,
        totals: &BTreeMap<u64, FixedColocalizationTally>,
        grid: &BlockGrid,
        block: [usize; 3],
    ) -> Result<Vec<u8>> {
        let mut rows = RowBuilder::new(Arc::clone(&self.schema));
        for tally in totals.values() {
            let Some(at) = tally.centroid() else {
                continue;
            };
            if owner_of(grid, at) != block {
                continue;
            }
            rows.push(at, &ColocalizationColumns::values(tally, self.fixed)?)?;
        }
        Ok(rows.encode())
    }
}

impl FragmentOp for MergeColocalizationSumsOp {
    fn name(&self) -> &'static str {
        self.name
    }

    fn reach(&self, _axis: usize, _volume_len: usize) -> usize {
        0
    }

    fn inputs(&self) -> Vec<FragmentInput> {
        vec![self.input.fragment_input()]
    }

    fn gathers(&self) -> bool {
        false
    }

    fn outputs(&self) -> Vec<FragmentOutput> {
        vec![
            FragmentOutput::new(self.stream.clone(), self.lifecycle, Coverage::EveryBlock)
                .sized(SidecarSize::row_table(self.schema.as_ref(), 1)),
        ]
    }

    fn seam_fold(&self) -> Option<SeamFold> {
        MeasurementSeamLaw::unordered_exact().seam_fold()
    }

    fn apply(&self, at: &BlockView<'_>) -> Result<BlockOutput> {
        let partials = self.input.stream_fragments(at)?;
        let totals = self.fold(partials.iter().map(Vec::as_slice))?;
        Ok(BlockOutput::fragment(
            self.stream.clone(),
            self.encode_owned(&totals, at.grid, at.index)?,
        ))
    }
}

