/// Resident Costes-style thresholded Manders measurements for one label.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct CostesColocalizationMeasurements {
    pub label: u64,
    pub finite_count: u64,
    pub threshold_a: Option<f64>,
    pub threshold_b: Option<f64>,
    pub below_threshold_pearson: Option<f64>,
    pub manders_m1: Option<f64>,
    pub manders_m2: Option<f64>,
}

/// Derived scalar features available from [`CostesColocalizationMeasurements`].
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum CostesColocalizationFeature {
    ThresholdA,
    ThresholdB,
    BelowThresholdPearson,
    MandersM1,
    MandersM2,
}

impl CostesColocalizationFeature {
    pub const ALL: [Self; 5] = [
        Self::ThresholdA,
        Self::ThresholdB,
        Self::BelowThresholdPearson,
        Self::MandersM1,
        Self::MandersM2,
    ];

    pub fn column_name(self) -> &'static str {
        match self {
            Self::ThresholdA => "threshold_a",
            Self::ThresholdB => "threshold_b",
            Self::BelowThresholdPearson => "below_threshold_pearson",
            Self::MandersM1 => "manders_m1",
            Self::MandersM2 => "manders_m2",
        }
    }
}

impl CostesColocalizationMeasurements {
    pub fn feature(&self, feature: CostesColocalizationFeature) -> Option<f64> {
        match feature {
            CostesColocalizationFeature::ThresholdA => self.threshold_a,
            CostesColocalizationFeature::ThresholdB => self.threshold_b,
            CostesColocalizationFeature::BelowThresholdPearson => self.below_threshold_pearson,
            CostesColocalizationFeature::MandersM1 => self.manders_m1,
            CostesColocalizationFeature::MandersM2 => self.manders_m2,
        }
    }
}

/// Compute resident Costes-style thresholds and thresholded Manders ratios.
///
/// The threshold search fits `B = slope * A + intercept`, then scans descending
/// unique `A` candidates and chooses the highest `(A, B)` threshold pair whose
/// below-threshold population has non-positive Pearson correlation. Manders M1
/// and M2 are then computed on intensities above their own channel threshold,
/// counting only pixels where the other channel is also above its threshold.
pub fn costes_colocalization_measurements(
    labels: ArrayView3<'_, f64>,
    channel_a: ArrayView3<'_, f64>,
    channel_b: ArrayView3<'_, f64>,
) -> Result<Vec<CostesColocalizationMeasurements>> {
    let samples = collect_colocalization_samples(labels, channel_a, channel_b)?;

    let mut out = Vec::with_capacity(samples.len());
    for (label, pairs) in samples {
        let result = costes_for_pairs(&pairs);
        out.push(CostesColocalizationMeasurements {
            label,
            finite_count: usize_count(pairs.len(), "measure Costes colocalization: finite_count")?,
            threshold_a: result.map(|row| row.threshold_a),
            threshold_b: result.map(|row| row.threshold_b),
            below_threshold_pearson: result.and_then(|row| row.below_threshold_pearson),
            manders_m1: result.and_then(|row| row.manders_m1),
            manders_m2: result.and_then(|row| row.manders_m2),
        });
    }
    Ok(out)
}

/// Resident rank-weighted colocalization measurements for one label.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct RankWeightedColocalizationMeasurements {
    pub label: u64,
    pub finite_count: u64,
    pub a_weighted_by_b_rank: Option<f64>,
    pub b_weighted_by_a_rank: Option<f64>,
}

/// Derived scalar features available from [`RankWeightedColocalizationMeasurements`].
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum RankWeightedColocalizationFeature {
    AWeightedByBRank,
    BWeightedByARank,
}

impl RankWeightedColocalizationFeature {
    pub const ALL: [Self; 2] = [Self::AWeightedByBRank, Self::BWeightedByARank];

    pub fn column_name(self) -> &'static str {
        match self {
            Self::AWeightedByBRank => "a_weighted_by_b_rank",
            Self::BWeightedByARank => "b_weighted_by_a_rank",
        }
    }
}

impl RankWeightedColocalizationMeasurements {
    pub fn feature(&self, feature: RankWeightedColocalizationFeature) -> Option<f64> {
        match feature {
            RankWeightedColocalizationFeature::AWeightedByBRank => self.a_weighted_by_b_rank,
            RankWeightedColocalizationFeature::BWeightedByARank => self.b_weighted_by_a_rank,
        }
    }
}

/// Compute resident rank-weighted colocalization coefficients.
///
/// For each label, finite paired samples are ranked within the label. Ties get
/// their average rank, normalized by the finite sample count. The A coefficient
/// is `sum(A * normalized_rank(B)) / sum(A)` over positive A samples; the B
/// coefficient mirrors it with channel A ranks. Non-positive denominators return
/// `None` instead of fabricating a coefficient.
pub fn rank_weighted_colocalization_measurements(
    labels: ArrayView3<'_, f64>,
    channel_a: ArrayView3<'_, f64>,
    channel_b: ArrayView3<'_, f64>,
) -> Result<Vec<RankWeightedColocalizationMeasurements>> {
    let samples = collect_colocalization_samples(labels, channel_a, channel_b)?;

    let mut out = Vec::with_capacity(samples.len());
    for (label, pairs) in samples {
        let (a_weighted_by_b_rank, b_weighted_by_a_rank) = rank_weighted_for_pairs(&pairs);
        out.push(RankWeightedColocalizationMeasurements {
            label,
            finite_count: usize_count(
                pairs.len(),
                "measure rank-weighted colocalization: finite_count",
            )?,
            a_weighted_by_b_rank,
            b_weighted_by_a_rank,
        });
    }
    Ok(out)
}

/// Block-local exact channel-pair partials for threshold/rank colocalization.
pub struct ColocalizationPairsOp {
    name: &'static str,
    labels: TypedSource,
    channel_a: TypedSource,
    channel_b: TypedSource,
    stream: String,
    lifecycle: Lifecycle,
}

impl ColocalizationPairsOp {
    pub fn new(
        name: &'static str,
        labels: impl Into<ImageId>,
        channel_a: impl Into<ImageId>,
        channel_b: impl Into<ImageId>,
        stream: impl Into<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        let stream = ColocalizationPartialStream::new(stream)?;
        Ok(Self {
            name,
            labels: TypedSource::new(labels),
            channel_a: TypedSource::new(channel_a),
            channel_b: TypedSource::new(channel_b),
            stream: stream.as_str().to_string(),
            lifecycle,
        })
    }

    pub fn holding(mut self, labels: Dtype, channel_a: Dtype, channel_b: Dtype) -> Self {
        self.labels = self.labels.holding(labels);
        self.channel_a = self.channel_a.holding(channel_a);
        self.channel_b = self.channel_b.holding(channel_b);
        self
    }

    fn tally_block(
        &self,
        labels: &BlockBuf,
        channel_a: &BlockBuf,
        channel_b: &BlockBuf,
        read: &Region,
        core: &Region,
    ) -> Result<BTreeMap<u64, ColocalizationPairPartial>> {
        let mut partials = BTreeMap::<u64, ColocalizationPairPartial>::new();
        let (BlockBuf::Array(labels), BlockBuf::Array(channel_a), BlockBuf::Array(channel_b)) =
            (labels, channel_a, channel_b)
        else {
            return Ok(partials);
        };
        let shape = read.shape3();
        for (what, array) in [
            ("label volume", labels),
            ("channel A array", channel_a),
            ("channel B array", channel_b),
        ] {
            expect_extent(
                || {
                    format!(
                        "measure exact colocalization: the {what} arrived as {:?} for a block \
                         read extent of {shape:?}",
                        array.shape()
                    )
                },
                shape,
                array.shape(),
            )?;
        }
        let labels = labels.widened();
        let channel_a = channel_a.widened();
        let channel_b = channel_b.widened();
        for (index, raw) in labels.indexed_iter() {
            let at = [
                read.start[0] + index.0,
                read.start[1] + index.1,
                read.start[2] + index.2,
            ];
            if !in_region(core, at) {
                continue;
            }
            let label = label_value(*raw, at)?;
            if label == 0 {
                continue;
            }
            let partial = partials.entry(label).or_default();
            let values = [
                channel_a[[index.0, index.1, index.2]],
                channel_b[[index.0, index.1, index.2]],
            ];
            if values[0].is_finite() && values[1].is_finite() {
                partial.push_finite(at, values);
            } else {
                partial.note_label_point(at);
            }
        }
        Ok(partials)
    }
}

impl FragmentOp for ColocalizationPairsOp {
    fn name(&self) -> &'static str {
        self.name
    }

    fn reach(&self, _axis: usize, _volume_len: usize) -> usize {
        0
    }

    fn source_inputs(&self, _volume: [usize; 3]) -> Vec<SourceInput> {
        vec![
            self.labels.voxelwise_input(),
            self.channel_a.voxelwise_input(),
            self.channel_b.voxelwise_input(),
        ]
    }

    fn outputs(&self) -> Vec<FragmentOutput> {
        vec![FragmentOutput::new(
            self.stream.clone(),
            self.lifecycle,
            Coverage::EveryBlock,
        )]
    }

    fn seam_fold(&self) -> Option<SeamFold> {
        MeasurementSeamLaw::per_block().seam_fold()
    }

    fn apply(&self, _at: &BlockView<'_>) -> Result<BlockOutput> {
        Err(Error::invalid(
            "measure exact colocalization: pair partials read label and channel sources and are \
             applied through `apply_with`",
        ))
    }

    fn apply_with(&self, at: &BlockView<'_>, sources: SourceBlocks<'_>) -> Result<BlockOutput> {
        let partials = self.tally_block(
            self.labels
                .block_at_extent(self.name, "label volume", sources, at.read)?,
            self.channel_a
                .block_at_extent(self.name, "channel A array", sources, at.read)?,
            self.channel_b
                .block_at_extent(self.name, "channel B array", sources, at.read)?,
            at.read,
            at.core,
        )?;
        Ok(BlockOutput::fragment(
            self.stream.clone(),
            ColocalizationPairPartialLayout::encode(&partials)?,
        ))
    }
}

/// Merge exact pair partials into Costes-style colocalization rows.
pub struct MergeCostesColocalizationOp {
    name: &'static str,
    input: PartialPhaseInput,
    schema: Arc<Schema>,
    stream: String,
    lifecycle: Lifecycle,
}

impl MergeCostesColocalizationOp {
    pub fn new(
        name: &'static str,
        input: impl Into<String>,
        input_phase: usize,
        lattice: [usize; 3],
        stream: impl Into<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        let input = ColocalizationPartialStream::new(input)?;
        let stream = ColocalizationOutputStream::new(stream)?;
        Ok(Self {
            name,
            input: PartialPhaseInput::try_new(&input, input_phase, lattice)?,
            schema: Arc::new(costes_colocalization_measurement_schema()),
            stream: stream.as_str().to_string(),
            lifecycle,
        })
    }

    fn encode_owned(
        &self,
        totals: &BTreeMap<u64, ColocalizationPairPartial>,
        grid: &BlockGrid,
        block: [usize; 3],
    ) -> Result<Vec<u8>> {
        let mut rows = RowBuilder::new(Arc::clone(&self.schema));
        for (&label, partial) in totals {
            let Some(owner_at) = partial.owner_at else {
                continue;
            };
            if owner_of(grid, owner_at) != block {
                continue;
            }
            let pairs = partial.sorted_pairs();
            let result = costes_for_pairs(&pairs);
            let row = CostesColocalizationMeasurements {
                label,
                finite_count: usize_count(
                    pairs.len(),
                    "measure Costes colocalization: finite_count",
                )?,
                threshold_a: result.map(|row| row.threshold_a),
                threshold_b: result.map(|row| row.threshold_b),
                below_threshold_pearson: result.and_then(|row| row.below_threshold_pearson),
                manders_m1: result.and_then(|row| row.manders_m1),
                manders_m2: result.and_then(|row| row.manders_m2),
            };
            validate_costes_colocalization_row(&row)?;
            rows.push(owner_at, &CostesColocalizationColumns::values(&row))?;
        }
        Ok(rows.encode())
    }
}

