fn collect_colocalization_samples(
    labels: ArrayView3<'_, f64>,
    channel_a: ArrayView3<'_, f64>,
    channel_b: ArrayView3<'_, f64>,
) -> Result<BTreeMap<u64, Vec<[f64; 2]>>> {
    validate_colocalization_shapes(labels, channel_a, channel_b)?;
    let mut samples = BTreeMap::<u64, Vec<[f64; 2]>>::new();
    for ((z, y, x), &raw_label) in labels.indexed_iter() {
        let at = [z, y, x];
        let label = label_value(raw_label, at)?;
        if label == 0 {
            continue;
        }
        let a = channel_a[[z, y, x]];
        let b = channel_b[[z, y, x]];
        if a.is_finite() && b.is_finite() {
            samples.entry(label).or_default().push([a, b]);
        } else {
            samples.entry(label).or_default();
        }
    }
    Ok(samples)
}

#[derive(Debug, Clone, Copy, PartialEq)]
struct ColocalizationPairSample {
    at: [usize; 3],
    values: [f64; 2],
}

#[derive(Debug, Clone, Default, PartialEq)]
struct ColocalizationPairPartial {
    owner_at: Option<[usize; 3]>,
    samples: Vec<ColocalizationPairSample>,
}

impl ColocalizationPairPartial {
    fn note_label_point(&mut self, at: [usize; 3]) {
        self.owner_at = Some(match self.owner_at {
            Some(owner_at) => owner_at.min(at),
            None => at,
        });
    }

    fn push_finite(&mut self, at: [usize; 3], values: [f64; 2]) {
        self.note_label_point(at);
        self.samples.push(ColocalizationPairSample { at, values });
    }

    fn sorted_pairs(&self) -> Vec<[f64; 2]> {
        let mut samples = self.samples.clone();
        samples.sort_by_key(|sample| sample.at);
        samples.into_iter().map(|sample| sample.values).collect()
    }

    fn merge_exact(&mut self, from: ExactReduction<Self>) -> Result<()> {
        let from = from.into_inner();
        self.owner_at = match (self.owner_at, from.owner_at) {
            (Some(a), Some(b)) => Some(a.min(b)),
            (Some(a), None) => Some(a),
            (None, Some(b)) => Some(b),
            (None, None) => None,
        };
        checked_partial_merged_len(
            self.samples.len(),
            from.samples.len(),
            "measure exact colocalization: pair partial sample count",
        )?;
        self.samples.extend(from.samples);
        Ok(())
    }
}

struct ColocalizationPairPartialLayout;

impl ColocalizationPairPartialLayout {
    const MAGIC: u64 = 0x4246_4d45_4350_5331;
    const VERSION: u64 = 1;
    const HEADER_WORDS: usize = 4;
    const LABEL_WORDS: usize = 6;
    const SAMPLE_WORDS: usize = 5;

    fn encode(partials: &BTreeMap<u64, ColocalizationPairPartial>) -> Result<Vec<u8>> {
        let sample_count = checked_partial_item_count(
            partials.values().map(|partial| partial.samples.len()),
            "measure exact colocalization: pair partial",
        )?;
        let mut words = Vec::with_capacity(variable_partial_capacity(
            Self::HEADER_WORDS,
            partials.len(),
            Self::LABEL_WORDS,
            sample_count,
            Self::SAMPLE_WORDS,
            "measure exact colocalization: pair partial",
        )?);
        words.push(Self::MAGIC);
        words.push(Self::VERSION);
        words.push(partial_usize_word(
            partials.len(),
            "measure exact colocalization: pair partial label count",
        )?);
        words.push(partial_usize_word(
            sample_count,
            "measure exact colocalization: pair partial sample count",
        )?);
        for (&label, partial) in partials {
            words.push(label);
            match partial.owner_at {
                Some(owner_at) => {
                    words.push(1);
                    push_partial_point3(
                        &mut words,
                        owner_at,
                        "measure exact colocalization: pair partial owner coordinate",
                    )?;
                }
                None => {
                    words.push(0);
                    words.extend([0, 0, 0]);
                }
            }
            words.push(partial_usize_word(
                partial.samples.len(),
                "measure exact colocalization: pair partial label sample count",
            )?);
            for sample in &partial.samples {
                push_partial_point3(
                    &mut words,
                    sample.at,
                    "measure exact colocalization: pair partial sample coordinate",
                )?;
                words.push(sample.values[0].to_bits());
                words.push(sample.values[1].to_bits());
            }
        }
        Ok(pack_u64(&words))
    }

    fn decode(bytes: &[u8]) -> Result<Vec<(u64, ColocalizationPairPartial)>> {
        let words = unpack_u64(bytes)?;
        Self::validate_prefix(&words)?;
        let label_count = partial_word_usize(
            words[2],
            "measure exact colocalization: pair partial label count",
        )?;
        let declared_sample_count = partial_word_usize(
            words[3],
            "measure exact colocalization: pair partial sample count",
        )?;
        let mut offset = Self::HEADER_WORDS;
        let mut decoded = Vec::with_capacity(label_count);
        let mut seen_samples = 0usize;
        for _ in 0..label_count {
            if words.len().saturating_sub(offset) < Self::LABEL_WORDS {
                return Err(Error::invalid(
                    "measure exact colocalization: pair partial label row is truncated",
                ));
            }
            let label = words[offset];
            if label == 0 {
                return Err(Error::invalid(
                    "measure exact colocalization: pair partial contains background label 0",
                ));
            }
            let has_owner = words[offset + 1];
            let owner_at = match has_owner {
                0 => None,
                1 => Some(partial_point3(
                    &words[offset + 2..offset + 5],
                    "measure exact colocalization: pair partial owner coordinate",
                )?),
                _ => {
                    return Err(Error::invalid(
                        "measure exact colocalization: owner-present flag is invalid",
                    ));
                }
            };
            let sample_count = partial_word_usize(
                words[offset + 5],
                "measure exact colocalization: pair partial label sample count",
            )?;
            offset += Self::LABEL_WORDS;
            let sample_range = checked_variable_partial_section(
                &words,
                offset,
                sample_count,
                Self::SAMPLE_WORDS,
                "measure exact colocalization: sample section",
            )?;
            let mut partial = ColocalizationPairPartial {
                owner_at,
                samples: Vec::with_capacity(sample_count),
            };
            for sample in words[sample_range.clone()].chunks_exact(Self::SAMPLE_WORDS) {
                let at = partial_point3(
                    &sample[..3],
                    "measure exact colocalization: pair partial sample coordinate",
                )?;
                let values = [f64::from_bits(sample[3]), f64::from_bits(sample[4])];
                if !values[0].is_finite() || !values[1].is_finite() {
                    return Err(Error::invalid(
                        "measure exact colocalization: pair partial contains non-finite sample",
                    ));
                }
                partial
                    .samples
                    .push(ColocalizationPairSample { at, values });
            }
            offset = sample_range.end;
            seen_samples = seen_samples.checked_add(sample_count).ok_or_else(|| {
                Error::invalid("measure exact colocalization: sample count overflow")
            })?;
            decoded.push((label, partial));
        }
        if offset != words.len() {
            return Err(Error::invalid(
                "measure exact colocalization: pair partial has trailing words",
            ));
        }
        if seen_samples != declared_sample_count {
            return Err(Error::invalid(
                "measure exact colocalization: pair partial sample count does not match header",
            ));
        }
        Ok(decoded)
    }
}

impl PartialLayoutContract for ColocalizationPairPartialLayout {
    const MAGIC: u64 = ColocalizationPairPartialLayout::MAGIC;
    const VERSION: u64 = ColocalizationPairPartialLayout::VERSION;
    const HEADER_WORDS: usize = ColocalizationPairPartialLayout::HEADER_WORDS;
    const FORMAT: &'static str = "measure exact colocalization: pair partial";
    const SHORT_ERROR: &'static str = "header is truncated";
    const MAGIC_ERROR: &'static str = "has an incompatible layout";
    const VERSION_ERROR: &'static str = "has an incompatible layout";
}

fn fold_colocalization_pair_partials<'a>(
    partials: impl IntoIterator<Item = &'a [u8]>,
) -> Result<BTreeMap<u64, ColocalizationPairPartial>> {
    let mut totals = BTreeMap::<u64, ColocalizationPairPartial>::new();
    for bytes in partials {
        for (label, partial) in ColocalizationPairPartialLayout::decode(bytes)? {
            totals
                .entry(label)
                .or_default()
                .merge_exact(ExactReduction::new(partial))?;
        }
    }
    Ok(totals)
}

fn validate_colocalization_shapes(
    labels: ArrayView3<'_, f64>,
    channel_a: ArrayView3<'_, f64>,
    channel_b: ArrayView3<'_, f64>,
) -> Result<()> {
    if labels.shape() != channel_a.shape() || labels.shape() != channel_b.shape() {
        return Err(Error::invalid(format!(
            "measure colocalization: label and channel volumes must have the same shape, got {:?}, \
             {:?} and {:?}",
            labels.shape(),
            channel_a.shape(),
            channel_b.shape()
        )));
    }
    Ok(())
}

#[derive(Debug, Clone, Copy)]
struct CostesThresholdResult {
    threshold_a: f64,
    threshold_b: f64,
    below_threshold_pearson: Option<f64>,
    manders_m1: Option<f64>,
    manders_m2: Option<f64>,
}

fn costes_for_pairs(pairs: &[[f64; 2]]) -> Option<CostesThresholdResult> {
    if pairs.len() < 2 {
        return None;
    }
    let n = pairs.len() as f64;
    let mut sum_a = 0.0;
    let mut sum_b = 0.0;
    let mut sum_a2 = 0.0;
    let mut sum_ab = 0.0;
    for [a, b] in pairs {
        sum_a += *a;
        sum_b += *b;
        sum_a2 += a * a;
        sum_ab += a * b;
    }
    let var_a = sum_a2 - sum_a * sum_a / n;
    if var_a <= 0.0 {
        return None;
    }
    let slope = (sum_ab - sum_a * sum_b / n) / var_a;
    let intercept = (sum_b - slope * sum_a) / n;

    let mut candidates: Vec<f64> = pairs.iter().map(|[a, _]| *a).collect();
    candidates.sort_by(|a, b| b.total_cmp(a));
    candidates.dedup_by(|a, b| a.total_cmp(b).is_eq());

    for threshold_a in candidates {
        let threshold_b = slope * threshold_a + intercept;
        let below: Vec<[f64; 2]> = pairs
            .iter()
            .copied()
            .filter(|[a, b]| *a <= threshold_a && *b <= threshold_b)
            .collect();
        let below_threshold_pearson = pearson_for_pairs(&below);
        if below_threshold_pearson.is_some_and(|pearson| pearson <= 0.0) {
            let (manders_m1, manders_m2) =
                thresholded_manders_for_pairs(pairs, threshold_a, threshold_b);
            return Some(CostesThresholdResult {
                threshold_a,
                threshold_b,
                below_threshold_pearson,
                manders_m1,
                manders_m2,
            });
        }
    }
    None
}

fn pearson_for_pairs(pairs: &[[f64; 2]]) -> Option<f64> {
    if pairs.len() < 2 {
        return None;
    }
    let n = pairs.len() as f64;
    let mut sum_a = 0.0;
    let mut sum_b = 0.0;
    let mut sum_a2 = 0.0;
    let mut sum_b2 = 0.0;
    let mut sum_ab = 0.0;
    for [a, b] in pairs {
        sum_a += *a;
        sum_b += *b;
        sum_a2 += a * a;
        sum_b2 += b * b;
        sum_ab += a * b;
    }
    let cov = sum_ab - sum_a * sum_b / n;
    let var_a = sum_a2 - sum_a * sum_a / n;
    let var_b = sum_b2 - sum_b * sum_b / n;
    let denom = (var_a * var_b).sqrt();
    (denom > 0.0).then_some(cov / denom)
}

fn thresholded_manders_for_pairs(
    pairs: &[[f64; 2]],
    threshold_a: f64,
    threshold_b: f64,
) -> (Option<f64>, Option<f64>) {
    let mut sum_a_above = 0.0;
    let mut sum_b_above = 0.0;
    let mut sum_a_colocalized = 0.0;
    let mut sum_b_colocalized = 0.0;
    for [a, b] in pairs {
        if *a > threshold_a {
            sum_a_above += *a;
            if *b > threshold_b {
                sum_a_colocalized += *a;
            }
        }
        if *b > threshold_b {
            sum_b_above += *b;
            if *a > threshold_a {
                sum_b_colocalized += *b;
            }
        }
    }
    (
        (sum_a_above > 0.0).then_some(sum_a_colocalized / sum_a_above),
        (sum_b_above > 0.0).then_some(sum_b_colocalized / sum_b_above),
    )
}

fn rank_weighted_for_pairs(pairs: &[[f64; 2]]) -> (Option<f64>, Option<f64>) {
    if pairs.is_empty() {
        return (None, None);
    }
    let ranks_a = normalized_average_ranks(pairs.iter().map(|[a, _]| *a).collect());
    let ranks_b = normalized_average_ranks(pairs.iter().map(|[_, b]| *b).collect());

    let mut sum_a = 0.0;
    let mut weighted_a = 0.0;
    let mut sum_b = 0.0;
    let mut weighted_b = 0.0;
    for (index, [a, b]) in pairs.iter().enumerate() {
        if *a > 0.0 {
            sum_a += *a;
            weighted_a += *a * ranks_b[index];
        }
        if *b > 0.0 {
            sum_b += *b;
            weighted_b += *b * ranks_a[index];
        }
    }

    (
        (sum_a > 0.0).then_some(weighted_a / sum_a),
        (sum_b > 0.0).then_some(weighted_b / sum_b),
    )
}

fn normalized_average_ranks(values: Vec<f64>) -> Vec<f64> {
    let count = values.len();
    let mut ordered: Vec<(usize, f64)> = values.into_iter().enumerate().collect();
    ordered.sort_by(|(_, a), (_, b)| a.total_cmp(b));

    let mut ranks = vec![0.0; count];
    let mut start = 0;
    while start < ordered.len() {
        let mut end = start + 1;
        while end < ordered.len() && ordered[start].1.total_cmp(&ordered[end].1).is_eq() {
            end += 1;
        }
        let average_rank = ((start + 1 + end) as f64 / 2.0) / count as f64;
        for (original_index, _) in &ordered[start..end] {
            ranks[*original_index] = average_rank;
        }
        start = end;
    }
    ranks
}

fn offset_position(at: [usize; 3], offset: [isize; 3], shape: [usize; 3]) -> Option<[usize; 3]> {
    let mut out = [0usize; 3];
    for axis in 0..3 {
        let coordinate = at[axis].checked_add_signed(offset[axis])?;
        if coordinate >= shape[axis] {
            return None;
        }
        out[axis] = coordinate;
    }
    Some(out)
}

fn parse_label_volume(labels: ArrayView3<'_, f64>) -> Result<Array3<u64>> {
    let mut parsed = Array3::<u64>::zeros(labels.raw_dim());
    for ((z, y, x), &raw) in labels.indexed_iter() {
        parsed[[z, y, x]] = label_value(raw, [z, y, x])?;
    }
    Ok(parsed)
}

fn same_label_six_neighbours(
    labels: ndarray::ArrayView3<'_, u64>,
    volume: [usize; 3],
    at: [usize; 3],
    label: u64,
) -> bool {
    for axis in 0..3 {
        for step in [-1isize, 1] {
            let mut offset = [0isize; 3];
            offset[axis] = step;
            let Some(neighbour) = offset_position(at, offset, volume) else {
                continue;
            };
            if labels[neighbour] != label {
                return false;
            }
        }
    }
    true
}

struct DistributionColumns;

impl DistributionColumns {
    const LABEL: usize = 0;
    const COUNT: usize = 1;
    const NONFINITE: usize = 2;
    const UNDERFLOW: usize = 3;
    const OVERFLOW: usize = 4;
    const BINS: usize = 5;
    const FIXED_WIDTH: usize = Self::BINS;

    fn width(set: DistributionSet) -> usize {
        Self::FIXED_WIDTH + set.bins()
    }

    fn schema(set: DistributionSet) -> Schema {
        let mut columns = Vec::with_capacity(Self::width(set));
        columns.extend([
            Column::u64("label"),
            Column::u64("count"),
            Column::u64("nonfinite"),
            Column::u64("underflow"),
            Column::u64("overflow"),
        ]);
        columns.extend((0..set.bins()).map(|bin| Column::u64(format!("bin_{bin}"))));
        trusted_measurement_schema_from_layout_columns(columns, "distribution")
    }

    fn values(tally: &HistogramTally) -> Vec<Value> {
        let mut values = Vec::with_capacity(Self::FIXED_WIDTH + tally.bins.len());
        values.push(Value::U64(tally.label));
        values.push(Value::U64(tally.count));
        values.push(Value::U64(tally.nonfinite));
        values.push(Value::U64(tally.underflow));
        values.push(Value::U64(tally.overflow));
        values.extend(tally.bins.iter().copied().map(Value::U64));
        values
    }

    fn decode(row: &Row<'_>, set: DistributionSet) -> Result<DistributionMeasurements> {
        let mut bins = Vec::with_capacity(set.bins());
        for column in 0..set.bins() {
            bins.push(row.u64(Self::BINS + column)?);
        }
        Ok(DistributionMeasurements {
            label: row.u64(Self::LABEL)?,
            at: row.at(),
            count: row.u64(Self::COUNT)?,
            nonfinite: row.u64(Self::NONFINITE)?,
            underflow: row.u64(Self::UNDERFLOW)?,
            overflow: row.u64(Self::OVERFLOW)?,
            set,
            bins,
        })
    }
}

pub fn distribution_measurement_schema(set: DistributionSet) -> Schema {
    DistributionColumns::schema(set)
}

fn distribution_measurement(
    row: &Row<'_>,
    set: DistributionSet,
) -> Result<DistributionMeasurements> {
    DistributionColumns::decode(row, set)
}

struct AutoDistributionColumns;

impl AutoDistributionColumns {
    const LABEL: usize = 0;
    const COUNT: usize = 1;
    const NONFINITE: usize = 2;
    const UNDERFLOW: usize = 3;
    const OVERFLOW: usize = 4;
    const RANGE_MIN: usize = 5;
    const RANGE_MAX: usize = 6;
    const BINS: usize = 7;
    const FIXED_WIDTH: usize = Self::BINS;

    fn width(set: AutoDistributionSet) -> usize {
        Self::FIXED_WIDTH + set.bins()
    }

    fn schema(set: AutoDistributionSet) -> Schema {
        let mut columns = Vec::with_capacity(Self::width(set));
        columns.extend([
            Column::u64("label"),
            Column::u64("count"),
            Column::u64("nonfinite"),
            Column::u64("underflow"),
            Column::u64("overflow"),
            Column::f64("range_min"),
            Column::f64("range_max"),
        ]);
        columns.extend((0..set.bins()).map(|bin| Column::u64(format!("bin_{bin}"))));
        trusted_measurement_schema_from_layout_columns(columns, "auto distribution")
    }

    fn values(row: &DistributionMeasurements, set: AutoDistributionSet) -> Result<Vec<Value>> {
        validate_auto_distribution_row(row, set)?;
        let mut values = Vec::with_capacity(Self::width(set));
        values.extend([
            Value::U64(row.label),
            Value::U64(row.count),
            Value::U64(row.nonfinite),
            Value::U64(row.underflow),
            Value::U64(row.overflow),
            Value::F64(row.set.min()),
            Value::F64(row.set.max()),
        ]);
        values.extend(row.bins.iter().copied().map(Value::U64));
        Ok(values)
    }

    fn decode(row: &Row<'_>, set: AutoDistributionSet) -> Result<DistributionMeasurements> {
        let distribution_set = DistributionSet::new(
            set.bins(),
            row.f64(Self::RANGE_MIN)?,
            row.f64(Self::RANGE_MAX)?,
        )?;
        let mut bins = Vec::with_capacity(set.bins());
        for column in 0..set.bins() {
            bins.push(row.u64(Self::BINS + column)?);
        }
        let measurements = DistributionMeasurements {
            label: row.u64(Self::LABEL)?,
            at: row.at(),
            count: row.u64(Self::COUNT)?,
            nonfinite: row.u64(Self::NONFINITE)?,
            underflow: row.u64(Self::UNDERFLOW)?,
            overflow: row.u64(Self::OVERFLOW)?,
            set: distribution_set,
            bins,
        };
        validate_auto_distribution_row(&measurements, set)?;
        Ok(measurements)
    }
}

fn validate_auto_distribution_row(
    row: &DistributionMeasurements,
    set: AutoDistributionSet,
) -> Result<()> {
    if row.set.bins() != set.bins() || row.bins.len() != set.bins() {
        return Err(Error::invalid(format!(
            "measure auto distributions: row for label {} has {} bins and set width {}, expected {}",
            row.label,
            row.bins.len(),
            row.set.bins(),
            set.bins()
        )));
    }
    DistributionSet::new(row.set.bins(), row.set.min(), row.set.max())?;
    Ok(())
}

pub fn auto_distribution_measurement_schema(bins: usize) -> Result<Schema> {
    Ok(auto_distribution_measurement_schema_set(
        AutoDistributionSet::new(bins)?,
    ))
}

pub fn auto_distribution_measurement_schema_set(set: AutoDistributionSet) -> Schema {
    AutoDistributionColumns::schema(set)
}

pub fn encode_auto_distribution_measurements(
    measurements: &[DistributionMeasurements],
    bins: usize,
) -> Result<Vec<u8>> {
    encode_auto_distribution_measurements_set(measurements, AutoDistributionSet::new(bins)?)
}

pub fn encode_auto_distribution_measurements_set(
    measurements: &[DistributionMeasurements],
    set: AutoDistributionSet,
) -> Result<Vec<u8>> {
    let schema = Arc::new(auto_distribution_measurement_schema_set(set));
    let mut rows = RowBuilder::new(schema);
    for row in measurements {
        rows.push(row.at, &AutoDistributionColumns::values(row, set)?)?;
    }
    Ok(rows.encode())
}

fn auto_distribution_measurement(
    row: &Row<'_>,
    set: AutoDistributionSet,
) -> Result<DistributionMeasurements> {
    AutoDistributionColumns::decode(row, set)
}

struct ExactDistributionColumns;

impl ExactDistributionColumns {
    const LABEL: usize = 0;
    const COUNT: usize = 1;
    const NONFINITE: usize = 2;
    const VALUE_COUNT: usize = 3;
    const VALUES: usize = 4;

    fn width(set: ExactDistributionSet) -> usize {
        set.row_width()
    }

    fn schema(set: ExactDistributionSet) -> Schema {
        let max_values = set.max_values();
        let mut columns = Vec::with_capacity(Self::width(set));
        columns.extend([
            Column::u64("label"),
            Column::u64("count"),
            Column::u64("nonfinite"),
            Column::u64("value_count"),
        ]);
        columns.extend((0..max_values).map(|index| Column::f64(format!("value_{index}"))));
        trusted_measurement_schema_from_layout_columns(columns, "exact distribution")
    }

    fn values(
        row: &ExactDistributionMeasurements,
        set: ExactDistributionSet,
    ) -> Result<Vec<Value>> {
        let max_values = set.max_values();
        let mut values = Vec::with_capacity(Self::width(set));
        values.extend([
            Value::U64(row.label),
            Value::U64(row.count),
            Value::U64(row.nonfinite),
            usize_column(row.values.len(), "measure exact distributions: value_count")?,
        ]);
        for index in 0..max_values {
            values.push(Value::F64(row.values.get(index).copied().unwrap_or(0.0)));
        }
        Ok(values)
    }

    fn decode(row: &Row<'_>, set: ExactDistributionSet) -> Result<ExactDistributionMeasurements> {
        let max_values = set.max_values();
        let value_count = row_usize(
            row,
            Self::VALUE_COUNT,
            "measure exact distributions: value_count",
        )?;
        if value_count > max_values {
            return Err(Error::invalid(format!(
                "measure exact distributions: row has {value_count} finite values, maximum is \
                 {max_values}"
            )));
        }
        let mut values = Vec::with_capacity(value_count);
        for index in 0..value_count {
            values.push(row.f64(Self::VALUES + index)?);
        }
        let measurements = ExactDistributionMeasurements {
            label: row.u64(Self::LABEL)?,
            at: row.at(),
            count: row.u64(Self::COUNT)?,
            nonfinite: row.u64(Self::NONFINITE)?,
            values,
        };
        validate_exact_distribution_row(&measurements, set)?;
        Ok(measurements)
    }
}

/// Table schema for [`ExactDistributionMeasurements`] with bounded stored values.
pub fn exact_distribution_measurement_schema(max_values: usize) -> Result<Schema> {
    Ok(exact_distribution_measurement_schema_set(
        ExactDistributionSet::new(max_values)?,
    ))
}

/// Table schema for [`ExactDistributionMeasurements`] with a validated bound.
pub fn exact_distribution_measurement_schema_set(set: ExactDistributionSet) -> Schema {
    ExactDistributionColumns::schema(set)
}

/// Encode exact distribution rows as a row-table fragment.
pub fn encode_exact_distribution_measurements(
    measurements: &[ExactDistributionMeasurements],
    max_values: usize,
) -> Result<Vec<u8>> {
    encode_exact_distribution_measurements_set(measurements, ExactDistributionSet::new(max_values)?)
}

/// Encode exact distribution rows with a validated stored-value bound.
pub fn encode_exact_distribution_measurements_set(
    measurements: &[ExactDistributionMeasurements],
    set: ExactDistributionSet,
) -> Result<Vec<u8>> {
    let schema = Arc::new(exact_distribution_measurement_schema_set(set));
    let mut rows = RowBuilder::new(schema);
    for row in measurements {
        validate_exact_distribution_row(row, set)?;
        rows.push(row.at, &ExactDistributionColumns::values(row, set)?)?;
    }
    Ok(rows.encode())
}

fn exact_distribution_measurement(
    row: &Row<'_>,
    set: ExactDistributionSet,
) -> Result<ExactDistributionMeasurements> {
    ExactDistributionColumns::decode(row, set)
}

fn trusted_measurement_schema_from_layout_columns(
    columns: Vec<Column>,
    layout: &'static str,
) -> Schema {
    Schema::new(columns).unwrap_or_else(|error| {
        panic!("{layout} measurement schema has invalid column contract: {error}")
    })
}

fn fixed_measurement_schema<const WIDTH: usize>(
    columns: [Column; WIDTH],
    layout: &'static str,
) -> Schema {
    trusted_measurement_schema_from_layout_columns(Vec::from(columns), layout)
}

fn encode_measurement_rows_at_origin<T, V>(
    schema: Arc<Schema>,
    measurements: &[T],
    mut values: impl FnMut(&T) -> Result<V>,
) -> Result<Vec<u8>>
where
    V: AsRef<[Value]>,
{
    let mut rows = RowBuilder::new(schema);
    for row in measurements {
        let values = values(row)?;
        rows.push([0, 0, 0], values.as_ref())?;
    }
    Ok(rows.encode())
}

struct RadiusColumns;

impl RadiusColumns {
    const WIDTH: usize = 9;
    const LABEL: usize = 0;
    const COUNT: usize = 1;
    const FINITE_COUNT: usize = 2;
    const HAS_MEAN: usize = 3;
    const MEAN: usize = 4;
    const HAS_MAX: usize = 5;
    const MAX: usize = 6;
    const HAS_MEDIAN: usize = 7;
    const MEDIAN: usize = 8;

    fn schema() -> Schema {
        let columns: [Column; Self::WIDTH] = [
            Column::u64("label"),
            Column::u64("count"),
            Column::u64("finite_count"),
            Column::u64("has_mean"),
            Column::f64("mean"),
            Column::u64("has_max"),
            Column::f64("max"),
            Column::u64("has_median"),
            Column::f64("median"),
        ];
        fixed_measurement_schema(columns, "radius")
    }

    fn option_values(value: Option<f64>) -> [Value; 2] {
        match value {
            Some(value) => [Value::U64(1), Value::F64(value)],
            None => [Value::U64(0), Value::F64(0.0)],
        }
    }

    fn values(
        label: u64,
        count: u64,
        finite_count: u64,
        mean: Option<f64>,
        max: Option<f64>,
        median: Option<f64>,
    ) -> [Value; Self::WIDTH] {
        let [has_mean, mean] = Self::option_values(mean);
        let [has_max, max] = Self::option_values(max);
        let [has_median, median] = Self::option_values(median);
        [
            Value::U64(label),
            Value::U64(count),
            Value::U64(finite_count),
            has_mean,
            mean,
            has_max,
            max,
            has_median,
            median,
        ]
    }

    fn decode_option(
        row: &Row<'_>,
        present_column: usize,
        value_column: usize,
    ) -> Result<Option<f64>> {
        let present = row.u64(present_column)?;
        match present {
            0 => Ok(None),
            1 => Ok(Some(row.f64(value_column)?)),
            other => Err(Error::invalid(format!(
                "measure radius: option presence column {present_column} must be 0 or 1, got {other}"
            ))),
        }
    }

    fn decode_shared(row: &Row<'_>) -> Result<SharedBoundaryRadiusMeasurements> {
        let measurements = SharedBoundaryRadiusMeasurements {
            label: row.u64(Self::LABEL)?,
            count: row.u64(Self::COUNT)?,
            finite_count: row.u64(Self::FINITE_COUNT)?,
            mean: Self::decode_option(row, Self::HAS_MEAN, Self::MEAN)?,
            max: Self::decode_option(row, Self::HAS_MAX, Self::MAX)?,
            median: Self::decode_option(row, Self::HAS_MEDIAN, Self::MEDIAN)?,
        };
        validate_radius_row(
            measurements.label,
            measurements.count,
            measurements.finite_count,
            measurements.mean,
            measurements.max,
            measurements.median,
        )?;
        Ok(measurements)
    }

    fn decode_exact(row: &Row<'_>) -> Result<ExactLabelRadiusMeasurements> {
        let measurements = ExactLabelRadiusMeasurements {
            label: row.u64(Self::LABEL)?,
            count: row.u64(Self::COUNT)?,
            finite_count: row.u64(Self::FINITE_COUNT)?,
            mean: Self::decode_option(row, Self::HAS_MEAN, Self::MEAN)?,
            max: Self::decode_option(row, Self::HAS_MAX, Self::MAX)?,
            median: Self::decode_option(row, Self::HAS_MEDIAN, Self::MEDIAN)?,
        };
        validate_radius_row(
            measurements.label,
            measurements.count,
            measurements.finite_count,
            measurements.mean,
            measurements.max,
            measurements.median,
        )?;
        Ok(measurements)
    }
}

