struct Moment3dColumns;

impl Moment3dColumns {
    const LABEL: usize = 0;
    const COUNT: usize = 1;
    const MAX_ORDER: usize = 2;
    const CENTROID: [usize; 3] = [3, 4, 5];
    const MOMENTS: usize = 6;
    const FIXED_WIDTH: usize = Self::MOMENTS;

    fn width_for_count(count: usize) -> Result<usize> {
        Self::FIXED_WIDTH
            .checked_add(count.checked_mul(2).ok_or_else(|| {
                Error::invalid("measure moments: row moment section width overflowed")
            })?)
            .ok_or_else(|| Error::invalid("measure moments: row width overflowed"))
    }

    fn width(set: ObjectMoment3dSet) -> Result<usize> {
        Self::width_for_count(moment_3d_orders(set).len())
    }

    fn schema(set: ObjectMoment3dSet) -> Result<Schema> {
        let mut columns = Vec::with_capacity(Self::width(set)?);
        columns.extend([
            Column::u64("label"),
            Column::u64("count"),
            Column::u64("max_order"),
            Column::f64("centroid_0"),
            Column::f64("centroid_1"),
            Column::f64("centroid_2"),
        ]);
        for order in moment_3d_orders(set) {
            let order = order.get();
            columns.push(Column::f64(format!(
                "central_{}_{}_{}",
                order[0], order[1], order[2]
            )));
            columns.push(Column::f64(format!(
                "normalized_{}_{}_{}",
                order[0], order[1], order[2]
            )));
        }
        Ok(trusted_measurement_schema_from_layout_columns(
            columns,
            "3D moment",
        ))
    }

    fn values(row: &ObjectMoment3dMeasurements) -> Result<Vec<Value>> {
        let mut values = Vec::with_capacity(Self::width_for_count(row.moments.len())?);
        values.extend([
            Value::U64(row.label),
            Value::U64(row.count),
            usize_column(row.max_order, "measure moments: max_order")?,
            Value::F64(row.centroid[0]),
            Value::F64(row.centroid[1]),
            Value::F64(row.centroid[2]),
        ]);
        for moment in &row.moments {
            values.push(Value::F64(moment.central));
            values.push(Value::F64(moment.normalized));
        }
        Ok(values)
    }

    fn decode(row: &Row<'_>, set: ObjectMoment3dSet) -> Result<ObjectMoment3dMeasurements> {
        let orders = moment_3d_orders(set);
        let mut moments = Vec::with_capacity(orders.len());
        for (index, order) in orders.into_iter().enumerate() {
            let column = Self::MOMENTS + index * 2;
            moments.push(Moment3d {
                order: order.get(),
                central: row.f64(column)?,
                normalized: row.f64(column + 1)?,
            });
        }
        let measurements = ObjectMoment3dMeasurements {
            label: row.u64(Self::LABEL)?,
            count: row.u64(Self::COUNT)?,
            max_order: row_usize(row, Self::MAX_ORDER, "measure moments: max_order")?,
            centroid: [
                row.f64(Self::CENTROID[0])?,
                row.f64(Self::CENTROID[1])?,
                row.f64(Self::CENTROID[2])?,
            ],
            moments,
        };
        validate_object_3d_moment_row(&measurements, set)?;
        Ok(measurements)
    }
}

