struct ZernikeMomentColumns;

impl ZernikeMomentColumns {
    const LABEL: usize = 0;
    const PROJECTED_COUNT: usize = 1;
    const PROJECTION_AXIS: usize = 2;
    const MAX_ORDER: usize = 3;
    const CENTROID: [usize; 2] = [4, 5];
    const RADIUS: usize = 6;
    const MOMENTS: usize = 7;
    const FIXED_WIDTH: usize = Self::MOMENTS;

    fn width_for_count(count: usize) -> Result<usize> {
        Self::FIXED_WIDTH
            .checked_add(count.checked_mul(3).ok_or_else(|| {
                Error::invalid("measure Zernike moments: row moment section width overflowed")
            })?)
            .ok_or_else(|| Error::invalid("measure Zernike moments: row width overflowed"))
    }

    fn width(set: ObjectZernikeMomentSet) -> Result<usize> {
        Self::width_for_count(zernike_orders(set.max_order()).len())
    }

    fn schema(set: ObjectZernikeMomentSet) -> Result<Schema> {
        let max_order = set.max_order();
        let mut columns = Vec::with_capacity(Self::width(set)?);
        columns.extend([
            Column::u64("label"),
            Column::u64("projected_count"),
            Column::u64("projection_axis"),
            Column::u64("max_order"),
            Column::f64("centroid_0"),
            Column::f64("centroid_1"),
            Column::f64("radius"),
        ]);
        for (order, repetition) in zernike_orders(max_order) {
            columns.push(Column::f64(format!("zernike_{order}_{repetition}_real")));
            columns.push(Column::f64(format!("zernike_{order}_{repetition}_imag")));
            columns.push(Column::f64(format!(
                "zernike_{order}_{repetition}_magnitude"
            )));
        }
        Ok(trusted_measurement_schema_from_layout_columns(
            columns,
            "Zernike moment",
        ))
    }

    fn values(row: &ObjectZernikeMomentsMeasurements) -> Result<Vec<Value>> {
        let mut values = Vec::with_capacity(Self::width_for_count(row.moments.len())?);
        values.extend([
            Value::U64(row.label),
            Value::U64(row.projected_count),
            Value::U64(projection_axis_code(row.projection_axis)),
            usize_column(row.max_order, "measure Zernike moments: max_order")?,
            Value::F64(row.centroid[0]),
            Value::F64(row.centroid[1]),
            Value::F64(row.radius),
        ]);
        for moment in &row.moments {
            values.push(Value::F64(moment.real));
            values.push(Value::F64(moment.imag));
            values.push(Value::F64(moment.magnitude));
        }
        Ok(values)
    }

    fn decode(
        row: &Row<'_>,
        set: ObjectZernikeMomentSet,
    ) -> Result<ObjectZernikeMomentsMeasurements> {
        let max_order = set.max_order();
        let orders = zernike_orders(max_order);
        let mut moments = Vec::with_capacity(orders.len());
        for (index, (order, repetition)) in orders.into_iter().enumerate() {
            let column = Self::MOMENTS + index * 3;
            moments.push(ObjectZernikeMoment {
                order,
                repetition,
                real: row.f64(column)?,
                imag: row.f64(column + 1)?,
                magnitude: row.f64(column + 2)?,
            });
        }
        let measurements = ObjectZernikeMomentsMeasurements {
            label: row.u64(Self::LABEL)?,
            projected_count: row.u64(Self::PROJECTED_COUNT)?,
            projection_axis: projection_axis_from_code(row.u64(Self::PROJECTION_AXIS)?)?,
            max_order: row_usize(row, Self::MAX_ORDER, "measure Zernike moments: max_order")?,
            centroid: [row.f64(Self::CENTROID[0])?, row.f64(Self::CENTROID[1])?],
            radius: row.f64(Self::RADIUS)?,
            moments,
        };
        validate_object_zernike_moment_row(&measurements, set)?;
        Ok(measurements)
    }
}

