struct Zernike3dColumns;

impl Zernike3dColumns {
    const LABEL: usize = 0;
    const COUNT: usize = 1;
    const MAX_ORDER: usize = 2;
    const CENTROID: [usize; 3] = [3, 4, 5];
    const RADIUS: usize = 6;
    const DESCRIPTORS: usize = 7;
    const FIXED_WIDTH: usize = Self::DESCRIPTORS;

    fn width(set: ObjectZernike3dSet) -> Result<usize> {
        Self::FIXED_WIDTH
            .checked_add(set.max_order() + 1)
            .ok_or_else(|| Error::invalid("measure 3D Zernike descriptors: row width overflowed"))
    }

    fn schema(set: ObjectZernike3dSet) -> Result<Schema> {
        let mut columns = Vec::with_capacity(Self::width(set)?);
        columns.extend([
            Column::u64("label"),
            Column::u64("count"),
            Column::u64("max_order"),
            Column::f64("centroid_z"),
            Column::f64("centroid_y"),
            Column::f64("centroid_x"),
            Column::f64("radius"),
        ]);
        for order in 0..=set.max_order() {
            columns.push(Column::f64(format!("zernike3d_{order}_descriptor")));
        }
        Ok(trusted_measurement_schema_from_layout_columns(
            columns,
            "3D Zernike descriptor",
        ))
    }

    fn values(row: &ObjectZernike3dMeasurements) -> Result<Vec<Value>> {
        let mut values = Vec::with_capacity(Self::FIXED_WIDTH + row.descriptors.len());
        values.extend([
            Value::U64(row.label),
            Value::U64(row.count),
            usize_column(row.max_order, "measure 3D Zernike descriptors: max_order")?,
            Value::F64(row.centroid[0]),
            Value::F64(row.centroid[1]),
            Value::F64(row.centroid[2]),
            Value::F64(row.radius),
        ]);
        for descriptor in &row.descriptors {
            values.push(Value::F64(descriptor.value));
        }
        Ok(values)
    }

    fn decode(row: &Row<'_>, set: ObjectZernike3dSet) -> Result<ObjectZernike3dMeasurements> {
        let descriptors = (0..=set.max_order())
            .map(|order| ObjectZernike3dDescriptor {
                order,
                value: row.f64(Self::DESCRIPTORS + order).unwrap_or(f64::NAN),
            })
            .collect();
        let measurements = ObjectZernike3dMeasurements {
            label: row.u64(Self::LABEL)?,
            count: row.u64(Self::COUNT)?,
            max_order: row_usize(
                row,
                Self::MAX_ORDER,
                "measure 3D Zernike descriptors: max_order",
            )?,
            centroid: [
                row.f64(Self::CENTROID[0])?,
                row.f64(Self::CENTROID[1])?,
                row.f64(Self::CENTROID[2])?,
            ],
            radius: row.f64(Self::RADIUS)?,
            descriptors,
        };
        validate_object_zernike3d_row(&measurements, set)?;
        Ok(measurements)
    }
}

