struct ProjectedConvexColumns;

impl ProjectedConvexColumns {
    const LABEL: usize = 0;
    const PROJECTED_COUNT: usize = 1;
    const PROJECTION_AXIS: usize = 2;
    const PROJECTED_AREA: usize = 3;
    const CONVEX_HULL_AREA: usize = 4;
    const SOLIDITY: usize = 5;
    const HULL_VERTEX_COUNT: usize = 6;
    const MAX_PROJECTED_FERET: usize = 7;
    const CIRCLE_CENTER: [usize; 2] = [8, 9];
    const CIRCLE_RADIUS: usize = 10;
    const CIRCLE_SUPPORT_POINTS: usize = 11;
    const HULL_VERTICES: usize = 12;

    fn width(set: ProjectedConvexSet) -> usize {
        set.row_width()
    }

    fn schema(set: ProjectedConvexSet) -> Schema {
        let max_hull_vertices = set.max_hull_vertices();
        let mut columns = Vec::with_capacity(Self::width(set));
        columns.extend([
            Column::u64("label"),
            Column::u64("projected_count"),
            Column::u64("projection_axis"),
            Column::f64("projected_area"),
            Column::f64("convex_hull_area"),
            Column::f64("solidity"),
            Column::u64("hull_vertex_count"),
            Column::f64("max_projected_feret_diameter"),
            Column::f64("min_enclosing_circle_center_0"),
            Column::f64("min_enclosing_circle_center_1"),
            Column::f64("min_enclosing_circle_radius"),
            Column::u64("min_enclosing_circle_support_points"),
        ]);
        for index in 0..max_hull_vertices {
            columns.push(Column::f64(format!("hull_vertex_{index}_0")));
            columns.push(Column::f64(format!("hull_vertex_{index}_1")));
        }
        trusted_measurement_schema_from_layout_columns(columns, "projected convex")
    }

    fn values(
        row: &ObjectProjectedConvexMeasurements,
        set: ProjectedConvexSet,
    ) -> Result<Vec<Value>> {
        let max_hull_vertices = set.max_hull_vertices();
        let mut values = Vec::with_capacity(Self::width(set));
        values.extend([
            Value::U64(row.label),
            Value::U64(row.projected_count),
            Value::U64(projection_axis_code(row.projection_axis)),
            Value::F64(row.projected_area),
            Value::F64(row.convex_hull_area),
            Value::F64(row.solidity.unwrap_or(0.0)),
            usize_column(
                row.hull_vertices.len(),
                "measure projected convex: hull_vertex_count",
            )?,
            Value::F64(row.max_projected_feret_diameter),
            Value::F64(row.min_enclosing_circle_center[0]),
            Value::F64(row.min_enclosing_circle_center[1]),
            Value::F64(row.min_enclosing_circle_radius),
            usize_column(
                row.min_enclosing_circle_support_points,
                "measure projected convex: min_enclosing_circle_support_points",
            )?,
        ]);
        for index in 0..max_hull_vertices {
            let vertex = row.hull_vertices.get(index).copied().unwrap_or([0.0, 0.0]);
            values.push(Value::F64(vertex[0]));
            values.push(Value::F64(vertex[1]));
        }
        Ok(values)
    }

    fn decode(row: &Row<'_>, set: ProjectedConvexSet) -> Result<ObjectProjectedConvexMeasurements> {
        let max_hull_vertices = set.max_hull_vertices();
        let hull_vertex_count = row_usize(
            row,
            Self::HULL_VERTEX_COUNT,
            "measure projected convex: hull_vertex_count",
        )?;
        if hull_vertex_count > max_hull_vertices {
            return Err(Error::invalid(format!(
                "measure projected convex: row has {hull_vertex_count} hull vertices, maximum is \
                 {max_hull_vertices}"
            )));
        }
        let mut hull_vertices = Vec::with_capacity(hull_vertex_count);
        for index in 0..hull_vertex_count {
            let column = Self::HULL_VERTICES + index * 2;
            hull_vertices.push([row.f64(column)?, row.f64(column + 1)?]);
        }
        let measurements = ObjectProjectedConvexMeasurements {
            label: row.u64(Self::LABEL)?,
            projected_count: row.u64(Self::PROJECTED_COUNT)?,
            projection_axis: projection_axis_from_code(row.u64(Self::PROJECTION_AXIS)?)?,
            projected_area: row.f64(Self::PROJECTED_AREA)?,
            convex_hull_area: row.f64(Self::CONVEX_HULL_AREA)?,
            solidity: Some(row.f64(Self::SOLIDITY)?),
            hull_vertices,
            max_projected_feret_diameter: row.f64(Self::MAX_PROJECTED_FERET)?,
            min_enclosing_circle_center: [
                row.f64(Self::CIRCLE_CENTER[0])?,
                row.f64(Self::CIRCLE_CENTER[1])?,
            ],
            min_enclosing_circle_radius: row.f64(Self::CIRCLE_RADIUS)?,
            min_enclosing_circle_support_points: row_usize(
                row,
                Self::CIRCLE_SUPPORT_POINTS,
                "measure projected convex: min_enclosing_circle_support_points",
            )?,
        };
        validate_object_projected_convex_row(&measurements, set)?;
        Ok(measurements)
    }
}

/// Table schema for [`ObjectProjectedConvexMeasurements`] with bounded hull vertices.
pub fn object_projected_convex_measurement_schema(max_hull_vertices: usize) -> Result<Schema> {
    Ok(object_projected_convex_measurement_schema_set(
        ProjectedConvexSet::new(max_hull_vertices)?,
    ))
}

/// Table schema for [`ObjectProjectedConvexMeasurements`] with a validated hull bound.
pub fn object_projected_convex_measurement_schema_set(set: ProjectedConvexSet) -> Schema {
    ProjectedConvexColumns::schema(set)
}

/// Encode projected convex rows as a row-table fragment.
pub fn encode_object_projected_convex_measurements(
    measurements: &[ObjectProjectedConvexMeasurements],
    max_hull_vertices: usize,
) -> Result<Vec<u8>> {
    encode_object_projected_convex_measurements_set(
        measurements,
        ProjectedConvexSet::new(max_hull_vertices)?,
    )
}

/// Encode projected convex rows with a validated hull-vertex bound.
pub fn encode_object_projected_convex_measurements_set(
    measurements: &[ObjectProjectedConvexMeasurements],
    set: ProjectedConvexSet,
) -> Result<Vec<u8>> {
    let schema = Arc::new(object_projected_convex_measurement_schema_set(set));
    encode_measurement_rows_at_origin(schema, measurements, |row| {
        validate_object_projected_convex_row(row, set)?;
        ProjectedConvexColumns::values(row, set)
    })
}

fn object_projected_convex_measurement(
    row: &Row<'_>,
    set: ProjectedConvexSet,
) -> Result<ObjectProjectedConvexMeasurements> {
    ProjectedConvexColumns::decode(row, set)
}

