    #[test]
    fn plan_value_sources_validate_base_availability_before_op_construction() {
        let decomposition = Decomposition {
            volume: [2, 3, 4],
            dtype: Dtype::F64,
            phases: vec![crate::PhaseDecomposition::derive(
                vec![0],
                vec!["values".to_string()],
                [0, 0, 0],
                [0, 0, 0],
                BlockGrid::new([2, 3, 4], [2, 3, 4]).unwrap(),
            )],
            chain_reach: [0, 0, 0],
        };

        let labels =
            PlanLabelSource::new(LabelImage::new(0usize).holding(Dtype::F64), &decomposition)
                .unwrap();
        assert_eq!(labels.id(), 0usize.into());
        assert_eq!(labels.extent(), [2, 3, 4]);

        let missing_label = PlanLabelSource::new(LabelImage::new(99usize), &decomposition)
            .unwrap_err()
            .to_string();
        assert!(missing_label.contains("label image 99 is not image 0"));

        let source = label_separated_plan_value_source(
            0usize.into(),
            1usize.into(),
            Some(Dtype::F64),
            "intensity image",
            &decomposition,
        )
        .unwrap();
        assert_eq!(source.id(), 1usize.into());

        let missing = label_separated_plan_value_source(
            0usize.into(),
            99usize.into(),
            Some(Dtype::F64),
            "intensity image",
            &decomposition,
        )
        .unwrap_err()
        .to_string();
        assert!(missing.contains("intensity image 99 is not image 0"));

        let supplied = label_separated_plan_value_source(
            0usize.into(),
            ImageId::supplied(0),
            Some(Dtype::F64),
            "intensity image",
            &decomposition,
        )
        .unwrap();
        assert_eq!(supplied.id(), ImageId::supplied(0));

        let channels = MeasurementChannelPair::for_plan(
            ColocalizationRequest {
                channel_a: 1usize.into(),
                channel_a_dtype: Some(Dtype::F64),
                channel_b: ImageId::supplied(0),
                channel_b_dtype: Some(Dtype::F32),
            },
            0usize.into(),
            &decomposition,
        )
        .unwrap();
        let contract = ColocalizationContract::from_plan_pair(0usize.into(), channels);
        assert_eq!(contract.channel_a(), 1usize.into());
        assert_eq!(contract.channel_a_dtype(), Some(Dtype::F64));
        assert_eq!(contract.channel_b(), ImageId::supplied(0));
        assert_eq!(contract.channel_b_dtype(), Some(Dtype::F32));

        let missing_pair = MeasurementChannelPair::for_plan(
            ColocalizationRequest {
                channel_a: 99usize.into(),
                channel_a_dtype: Some(Dtype::F64),
                channel_b: ImageId::supplied(0),
                channel_b_dtype: Some(Dtype::F32),
            },
            0usize.into(),
            &decomposition,
        )
        .unwrap_err()
        .to_string();
        assert!(missing_pair.contains("colocalization intensity image 99 is not image 0"));
    }

