    #[test]
    fn exact_distribution_partial_layout_validates_header_and_rows() {
        let mut tallies = BTreeMap::new();
        let mut tally = ExactDistributionTally::new(3);
        tally.add([1, 2, 3], 4.0).unwrap();
        tally.add([1, 2, 4], 5.0).unwrap();
        tallies.insert(tally.label, tally);

        let encoded = ExactDistributionPartialLayout::encode(&tallies, None).unwrap();
        let decoded = ExactDistributionPartialLayout::decode(&encoded, None).unwrap();
        assert_eq!(decoded, tallies.values().cloned().collect::<Vec<_>>());

        let set = ExactDistributionSet::new(8).unwrap();
        let encoded = ExactDistributionPartialLayout::encode(&tallies, Some(set)).unwrap();
        assert_eq!(
            ExactDistributionPartialLayout::decode(&encoded, Some(set)).unwrap(),
            decoded
        );
        let error = ExactDistributionPartialLayout::decode(
            &encoded,
            Some(ExactDistributionSet::new(9).unwrap()),
        )
        .unwrap_err()
        .to_string();
        assert!(error.contains("was written for max_values 8"));

        let mut words =
            unpack_u64(&ExactDistributionPartialLayout::encode(&tallies, None).unwrap()).unwrap();
        words[1] = 2;
        let error = ExactDistributionPartialLayout::decode(&pack_u64(&words), None)
            .unwrap_err()
            .to_string();
        assert!(error.contains("unsupported partial version"));

        let mut words =
            unpack_u64(&ExactDistributionPartialLayout::encode(&tallies, None).unwrap()).unwrap();
        words[3] = 1;
        let error = ExactDistributionPartialLayout::decode(&pack_u64(&words), None)
            .unwrap_err()
            .to_string();
        assert!(error.contains("reserved word"));

        let mut words =
            unpack_u64(&ExactDistributionPartialLayout::encode(&tallies, None).unwrap()).unwrap();
        words.pop();
        let error = ExactDistributionPartialLayout::decode(&pack_u64(&words), None)
            .unwrap_err()
            .to_string();
        assert!(error.contains("ended inside values"));
    }

    #[test]
    fn exact_distribution_tally_merge_uses_exact_reduction_witness() {
        let mut left = ExactDistributionTally::new(3);
        left.add([1, 2, 3], 4.0).unwrap();
        left.add([1, 2, 4], f64::NAN).unwrap();

        let mut right = ExactDistributionTally::new(3);
        right.add([4, 5, 6], 7.0).unwrap();

        left.merge_exact(ExactReduction::new(right)).unwrap();

        assert_eq!(left.count, 3);
        assert_eq!(left.nonfinite, 1);
        assert_eq!(left.position, [6, 9, 13]);
        assert_eq!(left.values, vec![4.0, 7.0]);

        let wrong = ExactDistributionTally::new(4);
        let error = left
            .merge_exact(ExactReduction::new(wrong))
            .unwrap_err()
            .to_string();
        assert!(error.contains("cannot merge labels 3 and 4"));
    }

    #[test]
    fn colocalization_partial_layout_validates_header_and_length() {
        let fixed = FixedPoint::bits(24).unwrap();
        let mut tally = FixedColocalizationTally::new(7);
        tally.count = 2;
        tally.finite_count = 2;
        tally.position = [1, 2, 3];
        tally.sum_a = fixed.quantise(1.0).unwrap().unwrap();
        tally.sum_b = fixed.quantise(2.0).unwrap().unwrap();
        tally.sum_a2 = fixed.quantise(1.0).unwrap().unwrap();
        tally.sum_b2 = fixed.quantise(4.0).unwrap().unwrap();
        tally.sum_ab = fixed.quantise(2.0).unwrap().unwrap();
        let mut tallies = BTreeMap::new();
        tallies.insert(tally.label, tally);

        let encoded = ColocalizationPartialLayout::new(fixed)
            .encode(&tallies)
            .unwrap();
        let decoded = ColocalizationPartialLayout::new(fixed)
            .decode(&encoded)
            .unwrap();
        assert_eq!(decoded, tallies.into_values().collect::<Vec<_>>());

        let wrong_fixed = FixedPoint::bits(20).unwrap();
        let error = ColocalizationPartialLayout::new(wrong_fixed)
            .decode(&encoded)
            .unwrap_err()
            .to_string();
        assert!(error.contains("written with q"));

        let mut words = unpack_u64(&encoded).unwrap();
        words[2] = 2;
        let error = ColocalizationPartialLayout::new(fixed)
            .decode(&pack_u64(&words))
            .unwrap_err()
            .to_string();
        assert!(error.contains("expected"));

        let mut words = unpack_u64(&encoded).unwrap();
        words.pop();
        let error = ColocalizationPartialLayout::new(fixed)
            .decode(&pack_u64(&words))
            .unwrap_err()
            .to_string();
        assert!(error.contains("expected"));

        let layout = ColocalizationPartialLayout::new(fixed);
        let error = layout.capacity(usize::MAX).unwrap_err().to_string();
        assert!(error.contains("row section overflowed"));
    }

    #[test]
    fn fixed_colocalization_tally_merge_uses_exact_reduction_witness() {
        let mut left = FixedColocalizationTally::new(7);
        left.count = 2;
        left.finite_count = 1;
        left.position = [1, 2, 3];
        left.sum_a = 10;
        left.sum_b = 20;
        left.sum_a2 = 30;
        left.sum_b2 = 40;
        left.sum_ab = 50;
        left.positive_a = 60;
        left.positive_b = 70;
        left.positive_a_where_b = 80;
        left.positive_b_where_a = 90;

        let mut right = FixedColocalizationTally::new(7);
        right.count = 3;
        right.finite_count = 2;
        right.position = [4, 5, 6];
        right.sum_a = 1;
        right.sum_b = 2;
        right.sum_a2 = 3;
        right.sum_b2 = 4;
        right.sum_ab = 5;
        right.positive_a = 6;
        right.positive_b = 7;
        right.positive_a_where_b = 8;
        right.positive_b_where_a = 9;

        left.merge_exact(ExactReduction::new(&right)).unwrap();

        assert_eq!(left.count, 5);
        assert_eq!(left.finite_count, 3);
        assert_eq!(left.position, [5, 7, 9]);
        assert_eq!(left.sum_a, 11);
        assert_eq!(left.sum_b, 22);
        assert_eq!(left.sum_a2, 33);
        assert_eq!(left.sum_b2, 44);
        assert_eq!(left.sum_ab, 55);
        assert_eq!(left.positive_a, 66);
        assert_eq!(left.positive_b, 77);
        assert_eq!(left.positive_a_where_b, 88);
        assert_eq!(left.positive_b_where_a, 99);

        let wrong = FixedColocalizationTally::new(8);
        let error = left
            .merge_exact(ExactReduction::new(&wrong))
            .unwrap_err()
            .to_string();
        assert!(error.contains("cannot merge labels 7 and 8"));
    }

    #[test]
    fn weighted_hu_point_partial_merge_uses_exact_reduction_witness() {
        let mut left = WeightedHuPointPartial {
            owner_at: Some([3, 0, 0]),
            finite_weight_count: 2,
            nonfinite_weight_count: 1,
            samples: vec![WeightedHuSample {
                at: [3, 0, 0],
                weight: 2.0,
            }],
        };
        let right = WeightedHuPointPartial {
            owner_at: Some([1, 4, 0]),
            finite_weight_count: 5,
            nonfinite_weight_count: 7,
            samples: vec![WeightedHuSample {
                at: [1, 4, 0],
                weight: 3.0,
            }],
        };

        left.merge_exact(ExactReduction::new(right)).unwrap();

        assert_eq!(left.owner_at, Some([1, 4, 0]));
        assert_eq!(left.finite_weight_count, 7);
        assert_eq!(left.nonfinite_weight_count, 8);
        assert_eq!(left.samples.len(), 2);

        let overflow = WeightedHuPointPartial {
            owner_at: None,
            finite_weight_count: u64::MAX,
            nonfinite_weight_count: 0,
            samples: Vec::new(),
        };
        let error = left
            .merge_exact(ExactReduction::new(overflow))
            .unwrap_err()
            .to_string();
        assert!(error.contains("finite weight count overflow"));
    }

