/// Class A per-label fixed-range intensity histogram.
pub struct IntensityHistogramOp {
    name: &'static str,
    labels: TypedSource,
    values: TypedSource,
    set: DistributionSet,
    schema: Arc<Schema>,
    stream: String,
    lifecycle: Lifecycle,
}

impl IntensityHistogramOp {
    pub fn new(
        name: &'static str,
        labels: impl Into<ImageId>,
        values: impl Into<ImageId>,
        set: DistributionSet,
        stream: impl Into<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        let stream = DistributionPartialStream::new(stream)?;
        Ok(Self {
            name,
            labels: TypedSource::new(labels),
            values: TypedSource::new(values),
            set,
            schema: Arc::new(distribution_measurement_schema(set)),
            stream: stream.as_str().to_string(),
            lifecycle,
        })
    }

    pub fn holding(mut self, labels: Dtype, values: Dtype) -> Self {
        self.labels = self.labels.holding(labels);
        self.values = self.values.holding(values);
        self
    }

    fn tally_block(
        &self,
        labels: &BlockBuf,
        values: &BlockBuf,
        read: &Region,
        core: &Region,
    ) -> Result<BTreeMap<u64, HistogramTally>> {
        let mut tallies = BTreeMap::<u64, HistogramTally>::new();
        let (BlockBuf::Array(labels), BlockBuf::Array(values)) = (labels, values) else {
            return Ok(tallies);
        };
        let shape = read.shape3();
        for (what, array) in [("label volume", labels), ("value array", values)] {
            expect_extent(
                || {
                    format!(
                        "measure distributions: the {what} arrived as {:?} for a block read \
                         extent of {shape:?}",
                        array.shape()
                    )
                },
                shape,
                array.shape(),
            )?;
        }
        let labels = labels.widened();
        let values = values.widened();
        for (index, raw) in labels.indexed_iter() {
            let at = [
                read.start[0] + index.0,
                read.start[1] + index.1,
                read.start[2] + index.2,
            ];
            if !in_region(core, at) {
                continue;
            }
            let label = label_value(*raw, at)?;
            if label == 0 {
                continue;
            }
            tallies
                .entry(label)
                .or_insert_with(|| HistogramTally::new(label, self.set.bins()))
                .add(at, values[[index.0, index.1, index.2]], self.set)?;
        }
        Ok(tallies)
    }
}

impl FragmentOp for IntensityHistogramOp {
    fn name(&self) -> &'static str {
        self.name
    }

    fn reach(&self, _axis: usize, _volume_len: usize) -> usize {
        0
    }

    fn source_inputs(&self, _volume: [usize; 3]) -> Vec<SourceInput> {
        vec![self.labels.voxelwise_input(), self.values.voxelwise_input()]
    }

    fn outputs(&self) -> Vec<FragmentOutput> {
        vec![
            FragmentOutput::new(self.stream.clone(), self.lifecycle, Coverage::EveryBlock)
                .sized(SidecarSize::row_table(self.schema.as_ref(), 1)),
        ]
    }

    fn seam_fold(&self) -> Option<SeamFold> {
        MeasurementSeamLaw::per_block().seam_fold()
    }

    fn apply(&self, _at: &BlockView<'_>) -> Result<BlockOutput> {
        Err(Error::invalid(
            "measure distributions: intensity histograms read label and value sources and are \
             applied through `apply_with`",
        ))
    }

    fn apply_with(&self, at: &BlockView<'_>, sources: SourceBlocks<'_>) -> Result<BlockOutput> {
        let tallies = self.tally_block(
            self.labels
                .block_at_extent(self.name, "label volume", sources, at.read)?,
            self.values
                .block_at_extent(self.name, "value array", sources, at.read)?,
            at.read,
            at.core,
        )?;
        Ok(BlockOutput::fragment(
            self.stream.clone(),
            HistogramPartialLayout::new(self.set).encode(&tallies)?,
        ))
    }
}

/// Merge intensity histogram partials into one row per label.
pub struct MergeIntensityHistogramOp {
    name: &'static str,
    input: PartialPhaseInput,
    set: DistributionSet,
    schema: Arc<Schema>,
    stream: String,
    lifecycle: Lifecycle,
}

impl MergeIntensityHistogramOp {
    pub fn new(
        name: &'static str,
        input: impl Into<String>,
        input_phase: usize,
        lattice: [usize; 3],
        set: DistributionSet,
        stream: impl Into<String>,
        lifecycle: Lifecycle,
    ) -> Result<Self> {
        let input = DistributionPartialStream::new(input)?;
        let stream = DistributionOutputStream::new(stream)?;
        Ok(Self {
            name,
            input: PartialPhaseInput::try_new(&input, input_phase, lattice)?,
            set,
            schema: Arc::new(distribution_measurement_schema(set)),
            stream: stream.as_str().to_string(),
            lifecycle,
        })
    }

    fn fold<'a>(
        &self,
        partials: impl IntoIterator<Item = &'a [u8]>,
    ) -> Result<BTreeMap<u64, HistogramTally>> {
        let mut totals = BTreeMap::<u64, HistogramTally>::new();
        for bytes in partials {
            for tally in HistogramPartialLayout::new(self.set).decode(bytes)? {
                match totals.get_mut(&tally.label) {
                    Some(seen) => seen.merge_exact(ExactReduction::new(&tally))?,
                    None => {
                        totals.insert(tally.label, tally);
                    }
                }
            }
        }
        Ok(totals)
    }

    fn encode_owned(
        &self,
        totals: &BTreeMap<u64, HistogramTally>,
        grid: &BlockGrid,
        block: [usize; 3],
    ) -> Result<Vec<u8>> {
        let mut rows = RowBuilder::new(Arc::clone(&self.schema));
        for tally in totals.values() {
            let Some(at) = tally.centroid() else {
                continue;
            };
            if owner_of(grid, at) != block {
                continue;
            }
            let values = DistributionColumns::values(tally);
            rows.push(at, &values)?;
        }
        Ok(rows.encode())
    }
}

impl FragmentOp for MergeIntensityHistogramOp {
    fn name(&self) -> &'static str {
        self.name
    }

    fn reach(&self, _axis: usize, _volume_len: usize) -> usize {
        0
    }

    fn inputs(&self) -> Vec<FragmentInput> {
        vec![self.input.fragment_input()]
    }

    fn gathers(&self) -> bool {
        false
    }

    fn outputs(&self) -> Vec<FragmentOutput> {
        vec![
            FragmentOutput::new(self.stream.clone(), self.lifecycle, Coverage::EveryBlock)
                .sized(SidecarSize::row_table(self.schema.as_ref(), 1)),
        ]
    }

    fn seam_fold(&self) -> Option<SeamFold> {
        MeasurementSeamLaw::unordered_exact().seam_fold()
    }

    fn apply(&self, at: &BlockView<'_>) -> Result<BlockOutput> {
        let partials = self.input.stream_fragments(at)?;
        let totals = self.fold(partials.iter().map(Vec::as_slice))?;
        Ok(BlockOutput::fragment(
            self.stream.clone(),
            self.encode_owned(&totals, at.grid, at.index)?,
        ))
    }
}

pub fn collect_distribution_measurements(
    env: &dyn Environment,
    stream: &str,
    phase: usize,
    volume: [usize; 3],
    set: DistributionSet,
) -> Result<Vec<DistributionMeasurements>> {
    let rows = MeasurementRows::<DistributionRows>::from_legacy_collector(stream, phase)?;
    collect_distribution_rows(env, &rows, volume, set)
}

pub fn collect_class_a_shapes(
    env: &dyn Environment,
    rows: &MeasurementRows<ClassARows>,
    volume: [usize; 3],
    fixed: FixedPoint,
) -> Result<Vec<RegionShape>> {
    collect_measurement_rows_table(env, rows, volume, tabulation_schema(fixed), region_shape)
}

pub fn collect_class_a_values(
    env: &dyn Environment,
    rows: &MeasurementRows<ClassARows>,
    volume: [usize; 3],
    fixed: FixedPoint,
) -> Result<Vec<RegionValues>> {
    collect_measurement_rows_table(env, rows, volume, tabulation_schema(fixed), |row| {
        region_values(row, fixed)
    })
}

fn collect_measurement_rows_table<K, T>(
    env: &dyn Environment,
    rows: &MeasurementRows<K>,
    volume: [usize; 3],
    schema: Schema,
    decode: impl FnMut(&Row<'_>) -> Result<T>,
) -> Result<Vec<T>> {
    let table = row_table_from_env_fragments(env, rows.stream(), rows.phase(), volume, schema)?;
    scan_measurement_table(table, volume, decode)
}

fn scan_measurement_table<T>(
    table: Table,
    volume: [usize; 3],
    mut decode: impl FnMut(&Row<'_>) -> Result<T>,
) -> Result<Vec<T>> {
    let mut out = Vec::with_capacity(table.len());
    for row in table.scan(&Region::whole(&volume))? {
        out.push(decode(&row)?);
    }
    Ok(out)
}

fn row_table_from_single_fragment(
    volume: [usize; 3],
    schema: Schema,
    encoded: &[u8],
) -> Result<Table> {
    let mut table = Table::new(volume, schema)?;
    table.write([0, 0, 0], encoded)?;
    table.seal()?;
    Ok(table)
}

fn row_table_from_env_fragments(
    env: &dyn Environment,
    stream: &str,
    phase: usize,
    volume: [usize; 3],
    schema: Schema,
) -> Result<Table> {
    let mut table = Table::new(volume, schema)?;
    fold_fragments(env, stream, &mut |key, bytes| {
        if key.phase != phase {
            return Ok(());
        }
        table.write(key.block, bytes)
    })?;
    table.seal()?;
    Ok(table)
}

fn row_table_from_block_stream_fragments(
    at: &BlockView<'_>,
    stream: &str,
    schema: Schema,
) -> Result<Table> {
    let mut table = Table::new(at.grid.volume(), schema)?;
    at.stream_fragments(stream, &mut |key, bytes| table.write(key.block, bytes))?;
    table.seal()?;
    Ok(table)
}

fn class_a_shape_row_table_from_block_input(
    at: &BlockView<'_>,
    input: &PartialPhaseInput,
    fixed: FixedPoint,
) -> Result<Table> {
    row_table_from_block_stream_fragments(at, input.stream(), tabulation_schema(fixed))
}

