/// Resident per-label histogram with automatic global finite range discovery.
///
/// The discovered range spans finite intensities inside non-background labels.
/// Non-finite labelled samples still contribute to per-label `count` and
/// `nonfinite`, but not to the range. A constant finite population is expanded
/// by half a unit on each side so the histogram contract remains increasing.
pub fn auto_distribution_measurements(
    labels: ArrayView3<'_, f64>,
    values: ArrayView3<'_, f64>,
    bins: usize,
) -> Result<Vec<DistributionMeasurements>> {
    if labels.shape() != values.shape() {
        return Err(Error::invalid(format!(
            "measure distributions: label and value volumes must have the same shape, got {:?} \
             and {:?}",
            labels.shape(),
            values.shape()
        )));
    }
    let mut range: Option<(f64, f64)> = None;
    for ((z, y, x), &raw_label) in labels.indexed_iter() {
        let at = [z, y, x];
        let label = label_value(raw_label, at)?;
        if label == 0 {
            continue;
        }
        let value = values[[z, y, x]];
        if !value.is_finite() {
            continue;
        }
        range = Some(match range {
            Some((min, max)) => (min.min(value), max.max(value)),
            None => (value, value),
        });
    }
    let Some((mut min, mut max)) = range else {
        return Ok(Vec::new());
    };
    if min == max {
        min -= 0.5;
        max += 0.5;
    }
    let set = DistributionSet::new(bins, min, max)?;
    resident_distribution_measurements(labels, values, set)
}

