impl FragmentOp for AutoDistributionOp {
    fn name(&self) -> &'static str {
        self.name
    }

    fn reach(&self, _axis: usize, _volume_len: usize) -> usize {
        0
    }

    fn reads_pixels(&self) -> bool {
        false
    }

    fn source_inputs(&self, _volume: [usize; 3]) -> Vec<SourceInput> {
        vec![
            FullVolumeSourceRead::new(self.labels).source_input(),
            FullVolumeSourceRead::new(self.values).source_input(),
        ]
    }

    fn outputs(&self) -> Vec<FragmentOutput> {
        vec![
            FragmentOutput::new(self.stream.clone(), self.lifecycle, Coverage::EveryBlock)
                .sized(SidecarSize::row_table(self.schema.as_ref(), 1)),
        ]
    }

    fn seam_fold(&self) -> Option<SeamFold> {
        MeasurementSeamLaw::per_block().seam_fold()
    }

    fn apply(&self, _at: &BlockView<'_>) -> Result<BlockOutput> {
        Err(Error::invalid(
            "measure auto distributions: automatic histogram range discovery reads label and value \
             sources and is applied through `apply_with`",
        ))
    }

    fn apply_with(&self, at: &BlockView<'_>, sources: SourceBlocks<'_>) -> Result<BlockOutput> {
        if at.index != [0, 0, 0] {
            return Ok(BlockOutput::fragment(
                self.stream.clone(),
                encode_auto_distribution_measurements_set(&[], self.set)?,
            ));
        }
        let labels = self
            .labels
            .block_at_extent(self.name, "label volume", sources, at.read)?;
        let values = self
            .values
            .block_at_extent(self.name, "value volume", sources, at.read)?;
        let (BlockBuf::Array(labels), BlockBuf::Array(values)) = (labels, values) else {
            return Ok(BlockOutput::fragment(
                self.stream.clone(),
                encode_auto_distribution_measurements_set(&[], self.set)?,
            ));
        };
        let labels = labels.widened();
        let values = values.widened();
        let rows = auto_distribution_measurements(labels.view(), values.view(), self.set.bins())?;
        Ok(BlockOutput::fragment(
            self.stream.clone(),
            encode_auto_distribution_measurements_set(&rows, self.set)?,
        ))
    }
}

/// Resident exact per-label distribution using sorted finite intensity samples.
///
/// This stores every finite labelled value per object, so it is intended for
/// exact order statistics and validation rather than compact planned execution.
pub fn exact_distribution_measurements(
    labels: ArrayView3<'_, f64>,
    values: ArrayView3<'_, f64>,
) -> Result<Vec<ExactDistributionMeasurements>> {
    if labels.shape() != values.shape() {
        return Err(Error::invalid(format!(
            "measure distributions: label and value volumes must have the same shape, got {:?} \
             and {:?}",
            labels.shape(),
            values.shape()
        )));
    }
    let mut tallies = BTreeMap::<u64, ExactDistributionTally>::new();
    for ((z, y, x), &raw_label) in labels.indexed_iter() {
        let at = [z, y, x];
        let label = label_value(raw_label, at)?;
        if label == 0 {
            continue;
        }
        tallies
            .entry(label)
            .or_insert_with(|| ExactDistributionTally::new(label))
            .add(at, values[[z, y, x]])?;
    }
    let mut out = Vec::with_capacity(tallies.len());
    for (_, mut tally) in tallies {
        tally.values.sort_by(f64::total_cmp);
        out.push(tally.finish()?);
    }
    Ok(out)
}

